/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240311-3","meetingId":"r06-c-budget","date":"2024年3月11日","dateIso":"2024-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を165件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和６年度品川区一般会計予算","agenda":"令和６年度品川区一般会計予算","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"おはようあります。私からは、３２１ページ、商店街活性化事業についてお伺いいたします。２０２０年春の緊急事態宣言の発令から約２年の間、見えざるコロナという感染症の蔓延という形の国難が我が国を襲いました。人生の大部分をお店の経営に携わってこられた方々の無念も含めて、商店街の未来を憂い、一方で商店街の発展を願い、質問いたします。その推移に対する区の考えをお示しいただければと思います。","respondent":"小林商業・ものづくり課長","answer":"その状況につきまして、先ほど東京都の調査の中で、課題ということで、後継者が不足しているというお話がございましたけれども、商店街においても担い手不足といいますか、後継者。","voiceIndex":4,"id":"exchange-001"},{"speaker":"こしば委員","kind":"提案","question":"商店街の中で担い手不足というものが深刻化しているという答弁でございました。これまで、私も何度か商店街の振興支援について質問や提案をさせていただいたことがありました。実際に、大井地域にあります商店街の一つが昨年閉じました。その一つが街路灯の撤去ではないでしょうか。そこで、商店街が解散した場合の影響、また、その課題について教えていただきたいと思います。","respondent":"小林商業・ものづくり課長","answer":"こうした部分につきましては、道路課とも調整しまして、地域の区民の方とも問題がないようにということで一定の設置を行っていくわけですけれども、我々としては、そういうふうにならないように、商店街はやはり地域のコミュニティで。","voiceIndex":6,"id":"exchange-002"},{"speaker":"こしば委員","kind":"質問","question":"ぜひ、街路灯の撤去も含めて、先ほどの課長の答弁のとおり、ほかの所管とも連携して対策を講じてもらいたいと思います。この商店街の街路灯、装飾灯ともいいますが、そこの補助金についてお伺いしたいと思います。この額が１本当たりの算定額となるのか、また、今話しましたとおり、２倍にした額に２０％を上乗せした額なのか、その辺りを教えていただければと思います。","respondent":"小林商業・ものづくり課長","answer":"それに加えまして、平成２１年度より補助基準額を倍増いたしまして、さらにそこから電気料金値上げというような対応もございましたので、そこから２０％アップということで、区の予算の方針でいけば、経常予算、政策予算という言い方をしますけれども。","voiceIndex":8,"id":"exchange-003"},{"speaker":"こしば委員","kind":"提案","question":"ぜひ、よろしくお願いします。続きまして、商店街を支える人の取組についてお伺いします。私たち品川区議会自民党・無所属の会も、これまで一般質問などでサポーター制度の拡充を提案してきましたので、来年新たに創設されます業務サポーター制度というものを高く評価いたします。この業務サポーターですが、これまでのエリアサポーターとの役割の違いについて教えてもらいたいと思います。","respondent":"小林商業・ものづくり課長","answer":"具体的に言いますと、先ほどご指摘がございましたように、補助金の申請や、あるいは商店街の例えば決算、会計といった基礎的な部分をお手伝いしながら、本来の役員の方、会員の方には、例えば本来の中核的な事業や商店街の中の取りまとめ。","voiceIndex":10,"id":"exchange-004"},{"speaker":"こしば委員","kind":"質問","question":"地域を巻き込むサポーター制度の運用をぜひお願いしたいと思います。そうすることによって、商店街の地域性に寄り添った支援のますますのさらなる拡充をお願いしまして、私からの質問は終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"ゆきた委員","kind":"提案","question":"私からは、２点お伺いいたします。３１３ページの収集運搬事業に関連して火災ごみ、２９９ページの、そ族昆虫防除対策費について、それぞれお伺いしてまいります。初めに、収集運搬事業に関連して、火災ごみについて質問いたします。そこで、火災ごみの減額免除の公的支援を受けるための申請についてはオンライン化を提案しますが、区のご所見を伺いたいと思います。","respondent":"品川品川区清掃事務所長","answer":"現在、火災の費用につきましては、罹災証明をお持ちいただいて、９割減免するという形を取っております。昨今、いろいろな申請システムの電子化等の流れもありますので、こちらについては電子で申請ができるような形で検討していきたいと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"本当に前向きな答弁をありがとうあります。こちらは要望で終わりたいと思います。続いて、そ族昆虫防除対策費について質問いたします。そ族昆虫防除の中のネズミ対策について、年間を通してどのぐらい被害や相談の声が寄せられているのか、改めて区ではどういった対策をしてこられたのか、また来年度の予算でどういった対策を取られていくのか、お聞きしたいと思います。","respondent":"舩木生活衛生課長","answer":"こういった中ですが、今後につきましては、現在行っている支援に加えまして、必要に応じて、区が契約する専門業者を現場に派遣し、進入口の探し方、塞ぎ方、駆除方法のアドバイスに対応するほか、駆除剤の使用方法や、ネズミを寄せつけないための環境整備に向けた助言など。","voiceIndex":16,"id":"exchange-007"},{"speaker":"ゆきた委員","kind":"確認","question":"年間を通して２０１件以上の状況、また次年度予算では毒餌やネズミ捕りのサンプル紹介以外に、ネズミ専門業者の個別での派遣調査も新しく行うことを確認いたしました。我が会派としても、このことはもう少し踏み込んだ形での対策が必要であると訴えてきましたが、次年度は新しい取組を始められますが、改めて、その後の施策の方向性・展開についてお聞きできればと思います。","respondent":"舩木生活衛生課長","answer":"したがいまして、区では個人からの相談のほか、例えば町会・自治会、それから商店街などの単位からの相談に対しても対応し、地域全体でネズミ対策を行うことで、ネズミが定着しづらい環境整備を目指すとともに、日常生活における生ごみの管理などを含め。","voiceIndex":18,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"被害の調査、発生の状況調査など、より一層進めていただければと思います。あらゆる会派からも取り上げられているところですが、建物の解体があった場合に、ネズミの被害と苦情の声が寄せられていますが、こちらの対策について、最後にお聞きできればと思います。","respondent":"舩木生活衛生課長","answer":"ネズミをはじめとする害獣の生息が確認できた場合の駆除の方法などについては、必要に応じて保健所も協力しながら対応してまいります。","voiceIndex":20,"id":"exchange-009"},{"speaker":"山本委員","kind":"提案","question":"私からは、３２３ページのデジタル商品券導入検討経費、２８９ページの健康ポイント等事業、３０１ページの各種がん検診について伺います。デジタル商品券の導入について伺います。昨年の決算特別委員会や一般質問でもご提案させていただきました。デジタル地域通貨へのステップとして、デジタル商品券の導入をご提案いたしました。区が都から何かしら連絡を受けておりますでしょうか。お教えください。","respondent":"横田情報推進課長","answer":"仮称「Tokyo Tokyo Point」ですが、現在、都が事業スキームを検討中でございまして、具体的な話は下りてきてございません。","voiceIndex":24,"id":"exchange-010"},{"speaker":"山本委員","kind":"提案","question":"都が私の提案と同じことを進めようとしているということです。さらに、２月２８日の都議会の一般質問において、詳しい仕組みの案が示されました。「Tokyo Tokyo Point」の出来上がりを待つのではなく、区は商品設計の段階から主体的に都へ区の要望を伝えていき、区にとって少しでも使いやすい仕組みとなるよう努めることが重要です。いろいろとご要望いたしましたが、区のご見解を伺います。","respondent":"横田情報推進課長","answer":"引き続き、東京都あるいはＧｏｖＴｅｃｈ東京の動向を注視しながら、また、区が実施予定のデジタル商品券の状況や他区の動向などを踏まえまして、デジタル地域通貨について検討を進めてまいります。","voiceIndex":26,"id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"ぜひ前向きに検討をよろしくお願いいたします。続いて、健康ポイント事業について伺います。昨年の決算特別委員会でも質問し、一般質問でも触れた事業で、スマホアプリを使って、ウォーキングなど健康につながる活動でポイントをためるものですが、今年度の参加者数、昨年度との比較、その要因とアンケートの状況についてお教えください。","respondent":"若生健康課長","answer":"これまで数年間、前のアプリで継続して参加していただいていたので、前年度については約６,３００人の登録があったところではあります。","voiceIndex":28,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"アンケートについては、前回お聞きした昨年度分では、ポイントが上位の人に当たったり、頑張ったりした人が報われるような仕組みにしてほしいという声や、期待する景品は１位が商品券で半数以上だったと記憶しています。続いて、がん検診について伺います。とうきょう健康ステーションのウェブサイトから、がん検診の受診率について確認いたしました。区のご認識と、理由が分かれば簡単にお教えください。","respondent":"若生健康課長","answer":"一方で、それを全部のがんに適用してきている状況ではございません。受診率があまり伸びていない、ほかのがんの対策については今後、検討していきたいと考えています。","voiceIndex":30,"id":"exchange-013"},{"speaker":"山本委員","kind":"質問","question":"きめ細やかに連絡をすれば、効果が上がるということで理解いたしました。連絡だけではなくて、受診に当たってのインセンティブの付与もできれば、よりいいですね。効果が高まるのではないかと思っています。続きは総括質疑ですることといたしまして、本日の私の質問は終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"産業経済費全体と、２９１ページ、公衆浴場の支援について伺います。産業経済費ですが、区は４月からの組織改正で、現在の商業・ものづくり課を地域産業振興課に改称するとしています。伺いますけれども、４月からの組織改正で部署の名前を変える理由というのを伺います。それと、「ものづくり」を名前に冠した部署名というのはいつから用いてきたのでしょうか。伺います。","respondent":"小林商業・ものづくり課長","answer":"こういった変化も捉えまして、地域産業の振興に幅広く取り組んでいくために、創業・スタートアップ支援担当課長の設置も含めて、地域産業振興課ということで課名変更を行うものです。","voiceIndex":34,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"先日、「出没！課の名称が変わったとしても、今、課長から答弁もありましたけれども、品川区のものづくりというのは重要だと、伝統工芸を含めて、守り、継承していくべきものだと思います。各事業、どれも大切だと思うのですが、課の名称は変更されますけれども、これらのものづくり産業の支援事業には、ぜひ引き続き力を入れていただきたいのですが、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"そういったところも踏まえまして、今ご指摘のあったような事業あるいは、それ以外に今後新たな取組を含めて、製造業、ものづくりを引き続き支援してまいりたいと考えております。","voiceIndex":36,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"よろしくお願いします。２０１１年６月の末、私も石巻市に泥のかき出しのボランティアに行きました。震災時に入浴するということが、いかに被災者の心の救いになるか、もちろん衛生上もそうですけれども求められているかというのを、そのときにすごく実感したのです。伺いますけれども、災害時における入浴の重要性や、銭湯に期待する役割などについて、保健衛生部門としてのお考えを伺いたいと思います。","respondent":"若生健康課長","answer":"災害時についても、そういったところで何ができるかというところは、災害部門とも連携して考えていかなければいけないと考えています。","voiceIndex":38,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"事項別明細書を見ますと、公衆浴場に対する補助金に、政策的経費として耐震化促進事業３７０万円が計上されておりまして、公衆浴場の耐震化を促進し、利用者の安心安全を確保するとありました。応急的修繕１００万円が２件、計画的修繕１７０万円が１件とありましたが、それぞれ、どのような修繕や工事に対する予算なのか伺います。","respondent":"若生健康課長","answer":"公衆浴場の耐震化促進の支援です。こちらについては、東京都の補助の仕組みが既にありまして、都の助成を受けた場合に、その上乗せとして区が行うというような助成になってあります。応急的修繕と計画的修繕の事例というか中身です。","voiceIndex":40,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"上乗せということで、すばらしいと思いました。なので、上下水道の継ぎ手の耐震化事業の対象に、やはり災害時に非常に被災者の方にとっても心のよりどころにもなりますし、衛生上も重要な銭湯も入れるべきだと思うのですけれども、公衆衛生部門からも、防災部門と連携して、上下水道耐震化計画を作成して進めている東京都に、ぜひ働きかけていただきたいのですけれども、いかがでしょうか。","respondent":"若生健康課長","answer":"これは、東京都とも、区の所管とも連携してやる必要もあるかと認識していますし、区でもそういった関係所管と、今後、意見交換等もしていきたいと思います。","voiceIndex":42,"id":"exchange-019"},{"speaker":"筒井委員","kind":"提案","question":"デジタル商品券についてですけれども、別の委員の方からご質問がありましたけれども、東京都のデジタル地域通貨プラットフォーム「Tokyo Tokyo Point」は、都民ファーストの会が最重点政策として提案・要望させていただいて、東京都の令和６年度予算に入れさせていただいたものですけれども、区のデジタル商品券導入に当たり。","respondent":"横田情報推進課長","answer":"委員のご意見もありますが、引き続き、東京都やＧｏｖＴｅｃｈ東京の動向ということを注視しながら、区が実施予定のデジタル商品券をどうしていくか、検討を進めてまいりたいと考えております。","voiceIndex":45,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。それに対する、目的を達成するための目標として、フリー利用延べ参加者数、コース型教室延べ参加者数とありますけれど、延べ参加者数というのは、やはり目的、あくまで品川区民の健康の保持・増進を図るという目的達成のためですから、当然、品川区民だけでないとおかしいのですけれども、この利用に当たり、品川区民と区外の方の区別というのはついているのでしょうか。","respondent":"若生健康課長","answer":"内訳については、これは区で今把握していないのですが、およそ９割が区民というところで、アンケート結果から把握しています。","voiceIndex":47,"id":"exchange-021"},{"speaker":"筒井委員","kind":"確認","question":"区別はつかれていないということで、９割、品川区民の方とはいえ、残り１割が品川区外の方になるということかと思うのですけれども、昨年の決算特別委員会でも質問させていただきましたけれども、品川区民か区外の方かという区別は、受付事務が煩雑ということですけれども、当然、新規では登録団体で確認して区別をつけられる。そして、私は料金もやはり分けるべきかと考えております。","respondent":"若生健康課長","answer":"そういった観点から、区民の方についても区外の方についても応益負担という観点がありますので、これについて、どういった料金設定がいいのかというところを、今後これは改定も視野に入れまして、現在、内部で検討は進めているところです。","voiceIndex":49,"id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひよろしくお願いします。区外料金が少し上がれば、指定管理者も、ある意味、収益面では助かるということなので、区民と区民外の区別というのをしっかりつけていただきたいと考えています。ぜひよろしくお願い申し上げます。しながわ健康プランについて伺います。この座り過ぎについて、今度のしながわ健康プラン２１ではどのように反映されていくのか、お考えをお聞かせください。","respondent":"若生健康課長","answer":"こういった様々な、国や世界で発表されているような知見なども含めまして、これは健康づくりでも、やはり座りっ放しの時間が長くならないように注意するというところがガイド等でも言われておりますので、そういったところも意識しながら。","voiceIndex":51,"id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"プランに反映するだけ、計画を立てるだけでは駄目だと考えておりまして、やはり、会議は３０分に１度立って休憩。マイボトル導入も致しましたし、そうした新たな時代に合った取組、もう実際上、エビデンス的にも健康に悪いと言われているので、やはり会議の仕方の工夫というのをしていかなくてはいけないと思いますけれども、品川区役所として具体的な取組・行動のお考えはあるのでしょうか。","respondent":"堀越総務部長","answer":"職員の健康管理につきましては、いろいろな労働安全の法令にのっとった対応をするのと、それから、より働きやすく仕事をして能率を上げるという面の検討が必要だと思いますので、様々な角度から検討して、取り入れるものについては取り入れていきたいと考えています。","voiceIndex":53,"id":"exchange-024"},{"speaker":"筒井委員","kind":"意見","question":"ぜひよろしくお願い申し上げます。様々、産業に影響があると思いますけれども、それでも体に悪いという情報は適切にお知らせしていかなくてはいけないと考えておりますけれども、厚生委員会でも、しながわ健康プラン２１に反映されるというご答弁を頂きましたけれども、改めてどのようにしながわ健康プラン２１に反映されるのか、お知らせください。","respondent":"若生健康課長","answer":"そういったものを参考にしながら、しながわ健康プラン２１の改定についても指標化して出たところに、確実に取り組んでいきたいと考えています。","voiceIndex":55,"id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"様々、今言った座り過ぎや飲酒など、新しい医学的な情報というのが更新されていっておりますので、そのとき適切に品川区の健康プランにも反映していっていただいて、かつ具体的な取組・行動に移していっていただきたいと思います。ぜひよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-026"},{"speaker":"せらく委員","kind":"質問・要望","question":"３０３ページ、こころの健康づくり事業から、各種相談・教室等事業、避難行動要支援者個別計画作成について触れながら、主にひきこもりの家族支援について質問します。先日、ひきこもりの家族連合会の運営に携わる方による講演会を拝聴してまいりました。学習会への参加は１回当たり大体何組ほどでしょうか。年齢層や、複数回参加したことがある方、学習会の雰囲気を教えてください。","respondent":"矢木大井保健センター所長","answer":"雰囲気ですが、こちらは、まず、ひきこもり家族学習会は、地域の普及啓発と家族の対応能力の向上ということで、２時間ぐらいの学習会ですが、そのうちの１時間半ほど、講師から、それぞれ知識の普及や、困り事をこういうふうに解決して。","voiceIndex":59,"id":"exchange-027"},{"speaker":"せらく委員","kind":"質問","question":"詳しく学習会の雰囲気を教えてくださいまして、ありがとうあります。毎回幾つかテーマを決めていらっしゃると思うのですけれども、そのテーマの選び方はどのように決めていらっしゃるのか、講師選びについてもどのような講師の方が学習会を開いていらっしゃるのか、お聞かせいただけたらと思います。この学習会を知るきっかけとしては、保健センターとしてどういった案内をされているのか、教えてください。","respondent":"矢木大井保健センター所長","answer":"テーマ選びですが、こちらは毎年度、ベースになるような、例えばひきこもりの理解などのシステムや、助けてとは言えない家族の危うさや家族の困り事などといったところと、あとは毎年度のアンケートを年度末に実施するのですが、そのアンケート結果を踏まえ。","voiceIndex":61,"id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"８０５０という問題もありますが、家族が元気なうちに、ひきこもり本人が信頼できる第三者とつながっておくことは、その先も生きていく上で必要だと感じますが、親や兄弟から家族支援として相談された際には、行政機関とはどのようにつなげていらっしゃいますでしょうか。必要とされている支援の内容の事例も教えてください。","respondent":"矢木大井保健センター所長","answer":"１つの事例ですが、例えば小学校低学年の方が、その方は昨年度までお母様が相談に行っていらっしゃるのですが、妊娠・出産を控えられましてというところで、そういったお子様のご相談におばあ様がいらしたというような事例においては。","voiceIndex":63,"id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"分かりました。引き続き、的確な行政機関とのつながりを、よろしくお願いいたします。個別計画については、こちらは精神保健事業ということで、精神障害者保健福祉手帳をお持ちの方が対象と伺いまして、ひきこもりの方全てが対象ではないという理解をしています。対象外の方においては、個別計画のような発災時の対策では、ご家庭で準備をする必要がありそうです。こちら、ご所見を伺いたいと思います。","respondent":"矢木大井保健センター所長","answer":"発災時の個別避難計画といったものを作成するのをテーマの内容にしてはどうかというご質問でございまして、こちらは、今年度末で間もなくアンケート結果がまとまりますので、それらを含めまして来年度に反映できるかどうか、また所内で相談・検討してまいりたいと思います。","voiceIndex":65,"id":"exchange-030"},{"speaker":"せらく委員","kind":"質問・要望","question":"震災については、皆様ご興味があるテーマかと思いますので、アンケートといったところも、能登半島地震が起きたというところも踏まえましてテーマに入れていただきたいと思います。社会課題として、ひきこもり本人と家族が孤立しないような支援、震災に向けた対策、引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-031"},{"speaker":"横山委員","kind":"質問","question":"私からは、２９５ページ、母子保健指導事業費、３１５ページ、創業・スタートアップ等支援経費についてお伺いいたします。１点目に、母子保健指導事業費についてお伺いいたします。母子保健の援助対象をご説明ください。虐待予防の観点からの母子保健の役割と重要性を区はどのようにお考えでしょうか。母子保健における指導と支援の違いについてもお伺いいたします。","respondent":"榎本荏原保健センター所長、石橋品川保健センター所長","answer":"それから支援についてですが、子育て中の方が少しでも安心して子育てができるように共感し、気持ちに寄り添った対応を大切にして支援していくことと考えております。保健師の役割ですが、保健センターの保健師は最も身近な存在として、不安などを抱えている養育者のご相談に対応しております。そして、その相談に応じて区の関係各課と連携しております。","voiceIndex":69,"id":"exchange-032"},{"speaker":"横山委員","kind":"提案","question":"「思い描いていたよい母親になることができない私のままでやっていくしかないと認めて、提案されている援助を拒むのをやめる。そこで、子育て安心教室の内容と現状を教えてください。大井・品川・荏原保健センターで内容に違いはあるのでしょうか。個別支援とグループ支援をどのように併用して成果につなげているのか、区のお考えをお聞かせください。","respondent":"石橋品川保健センター所長","answer":"ペアレントトレーニングなのですが、所管ではないのであまりしっかり把握はしていないので申し訳ありませんが、発達障害などのご本人様やご家庭などを対象に、区の個別支援や講演会などを実施しているものと認識しております。最後の３点目です。","voiceIndex":72,"id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"関連しまして、私は昨年１１月、日本子ども虐待防止学会第２９回学術集会滋賀大会、「１０００人の子を救う！！２点目に参ります。創業・スタートアップ等支援経費についてお伺いいたします。区内においてスタートアップの力が高まることで、地域社会にどのような影響を及ぼすと区はお考えでしょうか。","respondent":"石橋品川保健センター所長、小林商業・ものづくり課長","answer":"初めに私から、先ほどの答弁の修正を１か所させてください。年間の回数１０回というお話をさせていただきましたが、こちらは各保健センターにて１０回前後、実施している形になります。大変失礼いたしました。ＣＤＲの件になります。西大井創業支援センターにつきましては、若者あるいは、今回はアントレプレナーシップ教育というところで、小中学生も対象にしたような事業も行ってまいりたいと思います。五反田産業文化施設は５月１日にオープン予定です。","voiceIndex":74,"id":"exchange-034"},{"speaker":"横山委員","kind":"提案","question":"私は、地域社会の中で尊重され、守られる体験が、次世代の虐待を予防すると考えています。さらに、地域保健の力で関係機関につなぐことに加えて機能を高めていくネットワークの構築も併せてお願いいたします。スタートアップにつきましては、スピード感を持って提案内容を検証したり、事業の妥当性を判断する道の重要性が指摘されていますので、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":77,"id":"exchange-035"},{"speaker":"西村委員","kind":"質問・要望","question":"２９７ページ、０歳児見守り・子育てサポート事業、３０３ページ、子宮頸がん、ＨＰＶワクチン、３２１ページ、モンゴル高専、時間が許せば２９７ページ、産後ケア事業と行きたいと思います。おむつ宅配の経過と改善点を伺います。明石市のおむつ宅配がいいと私が思ったのは、コープ・生協に勤める先輩ママが、最近どうかと訪問してくれると伺ったからです。今届いている要望と併せてお聞かせください。","respondent":"石橋品川保健センター所長","answer":"引き続き、見守り支援員は配慮に欠けないような言葉遣い、声かけを心がけるように、受託者を通じて指導してまいります。","voiceIndex":79,"id":"exchange-036"},{"speaker":"西村委員","kind":"提案","question":"相談員こそアウトリーチの価値だと思います。相談を受けるための研修にもさらに力を入れていただきたいと思います。区民の方から、「相談したらその後どうなるのか分からない。一目瞭然なフローチャートがあると、双方にとってよいのではないかと思いましたので、ご提案します。既に声を聞きながら軌道修正をしていると伺っております。その点を教えていただければと思います。","respondent":"石橋品川保健センター所長","answer":"今後の相談の流れがよく分からないというご指摘がありましたが、その辺りにつきましてはしっかりと、訪問支援員が訪問時に丁寧に利用者の方にはご説明をしていくとともに、今後の展開については検討してまいります。続いての２点目の質問になります。","voiceIndex":81,"id":"exchange-037"},{"speaker":"西村委員","kind":"質問・要望","question":"軌道修正がすごく早いと思っておりまして、お母さんたちからも感謝の声が聞こえています。次に、モンゴル高専に移らせていただきます。既にモンゴル高専生の取り合いが始まっていると見ていただいて、予算を割いて、次なる打ち手を検討してほしいと思います。人材の交流を目的とした協定や友好都市の締結など、人材の流出を防ぐ手だてをお願いしたいと思いますが、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"そういう中で現地側とも信頼関係を築いて、その中でより成果が見えるような取組を進めていきたいと考えております。","voiceIndex":83,"id":"exchange-038"},{"speaker":"西村委員","kind":"意見","question":"いずれモンゴルに帰って仕事をしたいという意向がある方々も既に出ておられるかもしれませんし、出てくることも踏まえて、人材流出しない、さらなる取組をお願いしたいと思います。五反田バレーとの取組も現在、検討中かと思いますが、今後の展開についてお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"具体的に言うと、技術者のところをどう対応していくかですけれども、今後の交流の中で情報通信業という部分も、モンゴル高専にはそのような対応をする学科がございまして、そこの学生たち、若者たちということも視野に入れたような取組もできるのではないかと考えておりますので。","voiceIndex":85,"id":"exchange-039"},{"speaker":"西村委員","kind":"質問・要望","question":"情報通信業も、区内企業の皆様が採用難で大変苦しんでおられます。孤独にならないコミュニティの形成や日本語支援の強化にも大変力を入れていただいておりますので、この点も引き続き、ぜひとも力を入れていただきたいと思います。現状を捉えて、今後どのような施策を考えていくのか、お聞かせください。","respondent":"小林商業・ものづくり課長","answer":"こういったものをやはり総合的に、どれか１つのアプローチということではなくて、こういうものは総合的に進めながら、人材の部分にも対応しながら、区内中小企業の下支えというものをやってまいりたいと考えております。","voiceIndex":87,"id":"exchange-040"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。次に、ＨＰＶワクチン、子宮頸がんを伺っていきたいと思います。会派としても要望してきました男性接種助成を開始するに当たりまして、情報に触れる機会をいかに増やせるか、なぜ男性に接種が必要かを正しく理解してもらう施策が必要だと考えます。男性が接種可能な医療機関ですが、現在の子宮頸がんと同等の医療機関数になるのでしょうか。お伺いいたします。","respondent":"坂野保健予防課長","answer":"一応、今の予定なのですけれども、令和６年７月１日の広報に記事を掲載しようかというのを考えているところです。男性接種の医療機関のお尋ねかと思います。","voiceIndex":89,"id":"exchange-041"},{"speaker":"西村委員","kind":"質問・要望","question":"５年生の段階から、科学的根拠に基づいた情報も届けてほしいと要望させていただきました。キャッチアップに関しましては、先日の委員会の中でも、７月をめどにお知らせの送付ができるということで伺っておりました。東京都も都立高校での出張授業を実現しています。その授業を実施したのが医学生団体ということで、実際にお話を伺いました。","respondent":"坂野保健予防課長","answer":"いろいろな形で情報は出していきたいと思うのですけれども、本日は衛生費ですので、なかなか学校でどうこうというのは、私からは言いにくい部分があるのですが、いろいろな方法はパラレルに使っていって、立体的な情報提供ということを考えていきたいと思います。","voiceIndex":91,"id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"まさに、立体的な周知をお願いしたいというのが今回の質問の全般でお伝えしたいことでありまして、男性接種もですが、子宮頸がんワクチン全般に関して、ＳＮＳ等だけではなく、ポスター、あとこちらから出向いていく出張授業、いろいろな方法が考えられると思いますので、正しい知識が区民の皆様に届きますようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"順番に伺ってまいります。１点目の、しながわ健康プラン２１等策定に関しまして、事項別説明書の資料の中で、策定委員会の開催４回と、策定支援業務委託との予算案を確認いたしました。昨年の第３回定例会一般質問で、この策定の見直しに当たって、この内容に、更年期、また更年期症状について掲載していただきたいと、施策展開を要望いたしました。","respondent":"若生健康課長","answer":"次期の健康プラン２１改定のスケジュールですが、これは、現計画の最終評価および、次期、令和７年度からの１２年間の計画の策定を行うものでございまして、スケジュールにつきましては、委員ご案内の年間４回の委員会を、１回目が夏頃以降、開催していく予定でございまして。","voiceIndex":95,"id":"exchange-044"},{"speaker":"新妻委員","kind":"質問・要望","question":"策定委員会の中で、しっかり議論を進めていただきたいと思います。次に、骨粗鬆症検診についてです。会派から重ねて、骨粗鬆症検診の受診・検診をお願いしています。医師会とのご協力が非常に重要であります。丁寧にやっていただくということが大事かと思いますけれども、医師会との協議がまとまり次第、補正予算を組んででも早期の実施をしていただきたいと思いますが、見解を伺います。","respondent":"若生健康課長","answer":"新しい検診の仕組みをつくるというところで、当然、両医師会のご協力、一緒に進めていく必要があるというところで、早期の実現に向けて、引き続き具体的な協議を進めてまいりたいと考えています。","voiceIndex":97,"id":"exchange-045"},{"speaker":"新妻委員","kind":"質問・要望","question":"早期の実現とご答弁を頂きましたので、ぜひよろしくお願いいたします。続きまして、猫に関連いたしましてお伺いいたします。私もこのことを要望させていただきましたので、これは非常にうれしく思っておりますし、また地域の猫のボランティアの方にお話をしたところ、とても、これはいいことだとお話を頂いております。","respondent":"舩木生活衛生課長","answer":"今、予算案は詳しくはご説明できませんでしたけれども、区が予定している大きな方向性といったところを説明いたしまして、あと詳細については、また実際に申請していただいたりご案内をする中で詳しく説明をしていくということで。","voiceIndex":99,"id":"exchange-046"},{"speaker":"新妻委員","kind":"質問","question":"今現状、町会・自治会にご理解いただいて地域猫活動がされているのですが、今度はここにプラス、個人と、またグループですか、入ってくるとなると、町会・自治会の皆様が、うちはそういうグループがないのだけれどもという、一方でそのようなお声も上がってくるのではないかと思われますので、町会・自治会の皆様に関してはどのようにこのことをご説明いただくのか、お知らせください。","respondent":"舩木生活衛生課長","answer":"そういった意味では、なかなか年度が明けてすぐ４月にというわけにはいかないかもしれませんが、大体６月前後、少し落ち着いた頃に、保健所から町会・自治会をお回りして、こういった制度に変わりますので、ぜひそういった目でご支援・ご協力を頂きたいという旨を。","voiceIndex":101,"id":"exchange-047"},{"speaker":"新妻委員","kind":"質問・要望","question":"最後に、子宮頸がんワクチンについてお伺いいたします。今も質問がありました。品川区は２０２１年に、声優の野沢雅子さんのご協力で、防犯広報プロジェクトを組んでやった経緯もありますけれども、例えば若い女性に人気のある方、若い女性が多く知っていらっしゃる方にお願いして、動画等、またメッセージを頂くなり、そのような工夫をしながら、もう一歩の周知をお願いしたいと思いますが、見解を伺います。","respondent":"坂野保健予防課長","answer":"先ほど西村委員からお話もあったところ、キャッチアップ接種が令和７年３月末で、今の予定では終わってしまう予定なので、ご指摘のとおり、夏ぐらいにスタートしないと、６か月のあれが終わってしまうという状況でございまして。","voiceIndex":103,"id":"exchange-048"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、２９１ページ、食育推進事業、２９５ページ、乳児健康診査、３０１ページ、成人歯科健診、３０３ページ、新型コロナウイルスワクチン経費、３１５ページ、産業振興経費と、３１９ページ、販路拡大支援事業について、時間があるところまでお聞きします。は食育推進事業ですが、来年の歳出予算見積書を見ますと、品川栄養士会への委託事業の見直しとありますが、どのような点が変更となるのでしょうか。","respondent":"若生健康課長","answer":"そのうち、キッズ料理教室の回数を少し減らしまして、その分、親子料理教室を増やしていこうというようなことで、栄養士会から提案がありまして、様々検討して、そういったことで考えてあります。","voiceIndex":106,"id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"これからも現場と栄養士とお話ししながら進めていただきたいと思います。今年度の受診率はどれぐらいでしょうか。受診されなかった方へのフォローはどうされているのでしょうか。全件、連絡は取れている状態でしょうか。成人歯科健診についてお聞きします。受診率はどれぐらいでしょうか。８０２０・９０１６顕彰が４００人となっていますが、こちらは他の区に比べて割合としては多いのでしょうか。","respondent":"石橋品川保健センター所長、若生健康課長","answer":"私からは、４か月健診の受診率またはフォローについてご回答いたします。本年度１月末までの受診率になりますが、９４.６％となります。フォローについてです。８０２０の達成者顕彰につきまして、これは件数を他区と比べてというところは把握してございませんが、毎年、これは歯科医師会が中心となって顕彰式を行っておりますが。","voiceIndex":108,"id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問・要望","question":"乳児健康診査に関しては受診率が９４.６％ということで、やはり非常に高いと思って安心しています。続きまして、新型コロナワクチンについてお聞きします。それだけ今回、多くの方が健康被害に苦しんでいることになりますが、品川区の現在の健康被害救済制度の申請における、今までの進達受理件数、そのうちの認定件数、否定件数、保留件数と支払金額についてお聞きします。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"認定件数は１６件、否認件数は３件です。認定に伴う支給額につきましては、約３８６万円となっております。今後、健康被害救済に関しまして丁寧にご相談に対応するとともに、迅速かつ適切に手続を進めてまいります。","voiceIndex":111,"id":"exchange-051"},{"speaker":"おぎの委員","kind":"意見","question":"死亡一時金が４,５３０万円ですので、この時点で、品川区民の死亡認定は出ていないということがうかがえます。令和６年４月以降の新型コロナワクチン予防接種の対象者の変更点についてお聞かせください。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"これは、制度が大きく変更しまして、定期接種Ｂ類の枠に、対象者の方が６５歳以上の高齢者および、６０歳から６４歳までの重症化リスクの高い方を対象に、秋から冬にかけて年１回、接種を実施する予定です。使用ワクチンは、最新の流行株に対応したワクチンを接種します。","voiceIndex":113,"id":"exchange-052"},{"speaker":"ひがし委員","kind":"質問・要望","question":"本日もよろしくお願いいたします。令和６年度の品川区当初予算案プレス発表では、希望者全てが利用可能になるよう、利用要件の緩和、また利用回数の拡大などが盛り込まれており、一般質問の回答でも、拡大する経緯については、利用者アンケートでの複数回利用の要望、また多くの方から利用の要望を頂き、拡大したとのご答弁があり、利用者の声を聞いた上で迅速に取り組んでくださったことを評価しております。","respondent":"石橋品川保健センター所長","answer":"そこにつきまして、産後ケアの宿泊型につきましては要件をなくしたということもありますので、ネット予約、電子申請での予約という形を４月から取れるように、今、進捗を進めているところになります。","voiceIndex":116,"id":"exchange-053"},{"speaker":"ひがし委員","kind":"質問・要望","question":"少なくとも拡大したということは大変うれしく思っております。予約についても、宿泊型についてネットの予約が４月からできるということで、ぜひ日帰り型、また訪問型にも拡充してほしいと思うのですけれども、今まだ進んでいないというところについて、課題がどのようなところにあるのかというのを聞かせていただきたいと思います。","respondent":"石橋品川保健センター所長","answer":"産後ケアの場所についてになりますが、今回、要件緩和をすることで人数が増えていくと想定されますので、その人数に鑑みて、場所や実施場所を課題として検討してまいりたいと考えております。","voiceIndex":118,"id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問・要望","question":"各種がん検診について伺います。都民の死亡の第１位はがん、全死亡者数の３人に１人、年間３万４,０００人ががんで亡くなっている。先ほど山本委員から、この結果を区としてどういうふうに分析しているのですかというような質問がありましたが、個別で受診券を送付していて、それが結果につながっているのではないかという回答があったと記憶しております。","respondent":"若生健康課長","answer":"未受診者に関しての勧奨につきましては、乳がん、子宮がんにつきましては、令和３年度から未受診者への再勧奨という形でおはがきをお送りしたりということをやっていまして、今回、肺がん検診、それから大腸がん検診についても、今年度。","voiceIndex":120,"id":"exchange-055"},{"speaker":"ひがし委員","kind":"意見","question":"早く見つかると手術も少しの侵潤でできるので、小線源治療といって、一部のところに放射線を当てて治療するということができたりすると思うので、品川区ではこの経緯になったというところは、時間がないのでお尋ねしませんけれども、検診をしないということで、次につなげていく、病院につなげていくというところはせめてやっていただかないと、罹患率が高い。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、ページはありませんが、省エネルギー設備更新助成と、公衆浴場、運送業者への物価高騰対策支援金の継続を求め、３０５ページ、省エネルギー対策事業にも関わって質問します。３２１ページの雇用確保支援事業の奨学金返還支援助成についても伺いたいと思います。中小企業支援についてです。この間の実績と実施期間、いつまでかというのを、それぞれの事業について伺います。","respondent":"小林商業・ものづくり課長、若生健康課長","answer":"交付決定としましては、現時点ではまだ最終的な確定調整というのもやっているところですけれども、３６２件で。公衆浴場の物価対策支援金のところですが、こちらについても第４回定例会の補正予算で計上しまして、その後、浴場組合に周知させていただきまして。まだ現時点で途中段階ですけれども、件数としましては今１８０件程度、件数を受け付けておりまして、金額にしまして２,３４０万円というところで、今現在。","voiceIndex":125,"id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、省エネルギー対策設備更新助成金は１月３１日までと。それで、運送事業者はまだ受付中ということで、それはいつまでなのかというのを伺いたいと思います。銭湯のほうは１年間、３月までということですけれども、まず運送業者のものを伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"運送事業者等燃料費高騰対策支援金につきましては、先ほど申し上げたように１月２５日からスタートしまして、今、受付の終了期限としましては令和６年３月１５日までということで対策を進めているところです。","voiceIndex":129,"id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"どの事業も３月までで終わってしまうということでした。しかし、物価高騰、燃料費の高騰はまだ続いて、高止まりという状況です。引き続き、支援が必要だと考えます。設備更新と運送業、銭湯への助成金は引き続き実施していただきたいと思いますが、いかがでしょうか。なぜ当初予算で組まなかったのでしょうか。伺いたいと思います。","respondent":"小林商業・ものづくり課長、若生健康課長","answer":"商業・ものづくり課で実施しております省エネ対策の更新助成金、運送事業者等の燃料費高騰対策支援金ですけれども、その背景としまして、やはり物価高騰の中でとりわけ電気代・ガス代、燃料費高騰が。公衆浴場の物価高騰対策につきましても、当初予算としては計上してございませんが、これは東京都でも補正予算を組んでというところもありますし、燃料費の高騰等の状況については、他の補助等も踏まえつつ。","voiceIndex":131,"id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"銭湯は東京都で補正を組んだりというお話がありましたけれども、既にそういうもので予想されているものがあるということなのか、伺いたいと思います。そこをぜひしっかり見ていただいて、引き続き支援が必要だということで、やっていただきたいと思うのですけれども、区としては、既に物価高騰が収まっているという考えなのか、伺いたいと思います。","respondent":"若生健康課長、小林商業・ものづくり課長","answer":"都の補正について、今年度、東京都がやっている、７月ですか、補正の予算を組んだ、それを受けて区でも検討してというところで、第４回定例会の補正というところでやっております。ただし、その中で全体の物価水準ということに加えまして、電気代・ガス代、燃料費のように、政府の激変緩和措置といった補助が入る中で、直近の状況で見ますと。","voiceIndex":134,"id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで行ってきたところをぜひ実施していっていただきたいと要望しておきたいと思います。それで、これまで中小企業支援の観点で求めてきましたけれども、省エネルギー設備更新というのは、やはり温暖化対策としても重要だと思います。温暖化対策として省エネルギー対策設備更新助成金が有効だと思いますけれども、いかがでしょうか。この事業の概要と、本年度の実績を伺います。","respondent":"小林商業・ものづくり課長","answer":"もう一点、奨学金返済のところです。こちらはやはり人材難というところで、これは東京都の仕組み、東京しごと財団の仕組みを使いまして、企業と東京都が、奨学金を負った方が入社した場合にその負担を軽減する仕組みに、企業負担の部分の２分の１を区が支援するという状況です。","voiceIndex":137,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"設備更新のほうは、やはり環境対策としてもエネルギー消費を減らしていくということが重要だと思いますので、環境対策としても、温暖化対策としても、ぜひ実施していっていただきたいと思います。これはむしろ平時から利用できる仕組みにしていくべきだと思いますし、奨学金返還金支援制度も引き続きよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"対象が６５歳からということですが、ぜひ若い世代も対象にしていただきたいと思いますが、いかがでしょうか。かつては、仕事は正規雇用が中心で、元気で健康でばりばり働いているという若者の前提でしたが、一旦、白紙に戻して、若い世代がどういう状況に置かれているのか、対象年齢の議論の出発点にしていただきたいと思いますが、いかがでしょうか。","respondent":"坂野保健予防課長","answer":"これも公費が相当入って、２,５００円でやれるというスキームがあって、予防接種法に基づくものであるから、そこで線を引かせていただいているというところになろうかと思います。","voiceIndex":141,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"組織の半分は既にこの世代となっていると思います。どこでもブラック企業が横行する。親は定年で、息子は派遣社員で、家族そのものの生活も成り立たないという話を伺います。保健所は様々事業を行っておりますが、法律で定められていると線を引くだけではなく、若者のリアルな実態から出発していただき、まずは実態調査も行って、支援策や対象年齢も検討していただきたいと思いますが、いかがでしょうか。","respondent":"坂野保健予防課長、阿部品川区保健所長","answer":"結局、定期接種はもう、Ａ類もＢ類も厳格・厳密に対象者が決まっているのです。そこで、Ｂ類の人に支援しようというスキームでやっております関係上、この年齢を変えるというところにはならないのかと思います。必要な施策については年齢を問わず対応していくことが必要と考えますけれども、予防接種や健康診断等につきましては、やはりリスクの高い年齢の方を中心に対策を進めてまいりたいと存じます。","voiceIndex":143,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ若い世代のリアルな生活実態を見ていただき、支援策を検討していただきたいと要望しておきたいと思います。例えば品川区が被災地となった場合、営業許可はどうなるのか、伺いたいと思います。例えば受け入れるための、キッチンカーが役割を発揮できるようにするための準備や課題の整理などを行って、品川区でもホームページで必要な情報を発表していただきたいと思いますが、いかがでしょうか。","respondent":"舩木生活衛生課長","answer":"一方で、品川区が被災地になった場合ということですけれども、この辺りも、例えばもう区内の事業者で既に食品営業許可を持ち合わせている方が、やはり移動販売の特性を活かして、例えばライフラインの復旧が間に合っていない場所でも調理ができる。","voiceIndex":146,"id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつ起きてもおかしくないと言われている中で、ぜひキッチンカーがその力を発揮できるように、環境整備をお願いしたいと思います。キッチンカーは被災者への支援とともに、福祉避難所や救護所や病院など、様々な食の提供というのは支援の柱になってくるかと思いますので、防災課などとの連携を強くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-066"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"私からは、プレス発表資料の６８ページの、マーケティング助成と販路拡大の支援金、あと３０９ページの資源持ち去り防止対策費、２９１ページのしながわ健康プラン２１等策定についてということでお伺いしたいと思います。初めに、マーケティングの販路拡大支援金ということで、非常に歓迎しております。名前のところで、恐らくこのままだと販路拡大支援助成みたいな感じになるのかと思っています。","respondent":"小林商業・ものづくり課長","answer":"１つ、周知です。我々が行う周知ということで、ホームページあるいは産業ニュースといった通常の手段もありますけれども、例年、３月末に、品川区の令和６年度の予算施策を説明する助成金の制度説明会というのをまとめてやっているものがあります。","voiceIndex":150,"id":"exchange-067"},{"speaker":"せりざわ委員","kind":"提案","question":"これは要望で、進めていきます。資源の持ち去りについて、私の認識だと、ある調査だと約２０％から３０％ぐらいが、いろいろな自治体で資源ごみを、持ち去りをされていると伺っています。私が調べている限りでは、２３区の中でもそこそこ早い段階で罰金等も強めに押し出していただいているのかと思うのですが、そこの実績がまずあるのかお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"やはり、現場で持ち去りと遭遇したりして、そこで戻せということで指示をして、戻すようであれば過料の対象にはならないというようなことで、大体、注意をすればそこで置いていくというようなことなのですけれども、それでもやはりまた繰り返しというような形で。","voiceIndex":152,"id":"exchange-068"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"２０％から３０％ぐらいということで、大体４分の１ぐらいが持っていかれているというのが認識であります。資源ごみという名前で、ごみと言われてしまいますが、リサイクルを求めて、区民も区に対してお渡ししている。それに対して、しっかりと取締りをしていくというのを、ぜひお願いしたいと思います。取締りの方法も、今いろいろ見回りをしていただいていると伺っております。ご見解をお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"確かに今、パトロールをしている段階では、大分、持ち去りをしている方々の高齢化というところもありまして、徐々には減ってきている傾向があるかというところは思いとしてはあるのですが、ただ依然として持ち去りがあるということは事実ですので。","voiceIndex":154,"id":"exchange-069"},{"speaker":"せりざわ委員","kind":"質問","question":"トレーニングをしましょう、運動習慣をつけましょうと、たくさん書いてあるのですが、心の健康というところだけをピックアップすると、心の健康に対しては、睡眠を取ってください、休養を取ってください、そしてストレスを抱えないでください、誰かと話してくださいというようなことが書いてあって、運動と心の健康はすごく密接に関わっていると私は思っていて、特に運動の中でも筋トレというのは、ある意味。","respondent":"若生健康課長","answer":"現状の健康プランでも、筋トレという記載はないかもしれないですが、運動について、特に筋力が落ちると、高齢者などはフレイルや転倒のリスクが高まるというところもありますので、筋力トレーニングというところは、基礎代謝を高めて健康を維持するということで。","voiceIndex":156,"id":"exchange-070"},{"speaker":"せりざわ委員","kind":"意見","question":"ぜひ筋力トレーニングの推進をしていただければと思います。それだけに限らず、例えば民間の企業で、区内企業で、フィットネス事業を持っているところというのも区内にもあると思うのですが、そういったところに例えば補助して、自分の地域で健康の筋トレをしていくというのも、１つ、支援として、在り方としてあるのかと思うのですが、その感覚もご見解をお聞かせください。","respondent":"若生健康課長","answer":"民間のフィットネスジムへの補助といったものも、民間との連携についても今後考えてまいりたいと思います。","voiceIndex":158,"id":"exchange-071"},{"speaker":"つる委員","kind":"質問・要望","question":"今、立ち上がろうとして膝が痛かったです。産後ケアでありますが、昨年の第２回定例会で、それぞれ産後ケアの拡充を求めさせていただいたものが、ほぼ全て反映されたかというところでは、本当に個人的にも歓迎したいですし、産後ケアの推進が品川区をリードするといったことで、来年度もしっかりと強力に進めていただきたいと、まず思います。ここにつきまして、現在の対応を教えてください。","respondent":"石橋品川保健センター所長","answer":"次年度以降、そういったメニューの中でまたいろいろ要望がありましたら、検討を考えていきたい、課題として考えていきたいと考えています。","voiceIndex":161,"id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"特に乳腺炎については、炎症性乳がんの早期発見にも資すると。症状が似ているというところから、検査等で、そうしたことも発見しやすいということもあるそうでありますので、この辺の療養支援等については、引き続きの拡充をお願いしたいと、求めたいと思います。次に就業支援費でありますが、先日の款で、高齢者地域支援という観点で求めさせていただきました。","respondent":"小林商業・ものづくり課長","answer":"今後とも、今、シルバー人材センターなどでいきますと、やはり人手不足もこういう部分に、会員の増減には影響しているようでして、そういったところも状況を踏まえながら、引き続き就労の場というのができるだけ広がる。","voiceIndex":163,"id":"exchange-073"},{"speaker":"つる委員","kind":"質問・要望","question":"現役世代を支えていただくというようなところも、引き続き各課連携しながら進めていっていただきたいと思います。２年前では、これは環境省か、「ｍｏｔｔＥＣＯ」の取組もぜひ活かしたらどうですかというところで、ここについては、２３区で見ると昨年、杉並区が、普及推進のコンソーシアムに参画して、取組を始めているというところの中で、品川区はドギーバッグということでやっていただきます。","respondent":"河内環境課長","answer":"この中で、やはり自分のメニューの中の、例えば小盛り対応など、細々したところをご対応いただくことになりますので、まずは食品ロスが出ない努力をいろいろしていただくというところを第１点としてやってきていただいております。","voiceIndex":165,"id":"exchange-074"},{"speaker":"つる委員","kind":"質問・要望","question":"先日、私も家族で、あるハンバーグチェーンに行ったら、まさにこの普及推進コンソーシアムに参画するハンバーグチェーンで、注文をタブレットでやるものですから、個数が全然分からなくて、子どもがぱちぱちやったらフライドポテトが３皿出てきて、どうするのだということで、食べ切れなくて聞いてみたら、ちょうど、まさに「ｍｏｔｔＥＣＯ」だったのです。","respondent":"小林商業・ものづくり課長","answer":"ただいま、エシカル消費イベントについてのお尋ねがございました。昨年１０月に、委員にもお越しいただきましたけれども、エシカルファッションショーを初めて取り入れる形で、エシカル消費イベントというのを実施いたしました。","voiceIndex":167,"id":"exchange-075"},{"speaker":"つる委員","kind":"質問","question":"今、一番最後のほうにあった新たな連携先というところで、この間、何回か紹介している、まさに昨年のイベントを通じて、さらに私もエシカル消費の推進をされて、啓発されて、啓発を受けて、今日、身に着けているものも半分以上がエシカル関係ということで、ネクタイ、ベスト、靴、肌着というところで、個人的にも推進を図っていきたいと思っていますが、昨年は環境課のイベントと同じ日に開催して。","respondent":"河内環境課長","answer":"社会意義を伴うのがエシカルファッションと認識しておりますが、例えば製品リメイクなど、それから洗濯性能でマイクロプラスチックの流出などといったものをテーマにしながら、お互い見やすいように、日付もきちんと工夫しながら。","voiceIndex":169,"id":"exchange-076"},{"speaker":"つる委員","kind":"質問・要望","question":"時間がないので、商業・ものづくり課の課長から答弁がなかったですけれども、しっかりと勉強して、いい味わいを来年度も出していただきたい。私もファッションショーの一員として出られたらいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私は、２９７ページの、おむつ定期便、３０５ページの自殺対策事業と、３０１ページのがん検診にまたがって、ＨＰＶも行けたら行きます。今回、ＴＮＣプロジェクトというところに、プロポーザル方式で５社応募があって、選定して一括で委託しているというところなのですけれども、委託する上で、配達する、いわゆる支援員の方の採用基準、配達員の方の採用基準を伺いたいと思いますけれども、お願いします。","respondent":"石橋品川保健センター所長","answer":"こちらに関しては、区としましては、有資格者、もし有資格者がいなければ子育て経験者というところの要件を付してプロポーザルをしたところになります。それで、実際の採用は受託者のほうで実施しておりますので、その辺りについては受託者にお願いしている形になります。","voiceIndex":173,"id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"質問","question":"有資格者というのは、保育士や保健師、助産師あたりになってくるのだと思うのですけれども、現在の支援員の方の資格者の内訳を教えていただけますか。","respondent":"石橋品川保健センター所長","answer":"今、見守り支援員は９名おりまして、うち有資格者は１名となっております。残りの８名は子育て経験者というところで採用させていただいていると伺っております。","voiceIndex":175,"id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問","question":"基本的に、先ほどご答弁がありましたとおり、有資格者を基本にして委託を出しているので、つまり今の時点でも無資格者の方が多いということで、今後、有資格者が増えてくると、当然、委託で出している計算の中に、有資格者を前提としている分の上積み分が無資格者にもあると思うので、それがもし人手不足で、無資格者の人の賃金割増しになっていればいいのですけれども、そうではなくて、ただその分が丸々。","respondent":"石橋品川保健センター所長","answer":"見守り支援訪問は、始まる前にまず２回の研修を実施して、今も月１回、支援員は定期的に研修をしっかりしているところになります。委託、またその金額についてですが、５年間のプロポーザル契約で今お願いしているところになります。","voiceIndex":177,"id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お願いします。人が要になる事業ということで、もう一点なのですけれども、今、支援員が９名いるということなのですけれども、その方たちが直接雇用なのか業務委託なのかといった内訳はお分かりでしょうか。","respondent":"石橋品川保健センター所長","answer":"こちらは正式な手続を経て、再委託という形で見守り支援員の雇用をしていると伺っております。","voiceIndex":179,"id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"つまり、ＴＮＣプロジェクトは配送業者から派遣されてくる方を使っているという状況が、何名かは分からないけれども、少なからずあるという状況で、そうなってくると、もしかしたらＴＮＣプロジェクトが採用に関して、どういう人物なのかといったことに関われていない可能性があると思うのです。なので、その辺をしっかり管理・監督といいますか、していただきたいのですけれども、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"プロポーザルの時点でも、実際、契約が決まった、受託者が決まった時点でも、本事業は見守り支援ということがかなり重大な部分を占めますので、人に関してはしっかりと対応していただくように受託者にはお願いして実施しております。","voiceIndex":181,"id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ぜひ今後ともしっかりその辺も管理・監督していただいて、本当に品川区のオリジナルの事業だと思うので、ぜひ成功させるように、一丸となって皆さんでやっていきたいと思います。よろしくお願いします。時間がなくなったので次なのですけれども、自殺対策なのですけれども、国と区の、１０万人当たりの自殺率の数字を教えていただけますでしょうか。","respondent":"坂野保健予防課長","answer":"すみません。調べて後で申し上げます。","voiceIndex":183,"id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問","question":"すみません。恐らく品川区は平均的に全国よりも低いと思うのです。ちなみに、自殺の対策計画というものを品川区でもつくっていて、厚生労働省からの交付金によって行われている、補助があるかと思うのですけれども、これは計画の中にある自殺率の数値というのを、必ずその計画に入れなくてはいけないものなのか、教えていただけますか。","respondent":"坂野保健予防課長","answer":"先ほどは答えられなくてすみません。令和４年の実績で、人口１０万人ベースで、全国が１７.４％で、品川区は１２.５％。ご指摘のとおり、品川区は全国ベースより若干低めであると。","voiceIndex":185,"id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"意見","question":"そうですね。そうしたら言われたのが、いや、そういっても自殺しているのでしょうと。品川区では年間５０人ぐらいいると思うのですけれども。改善ができないし、つまり基本的にゼロを目指すべきで、数字は出さないで結果的に後々数字が出たというのは仕方ないけれども、基本的にはゼロを目指すという気持ちでやっていただければいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":187,"id":"exchange-085"},{"speaker":"木村委員","kind":"質問","question":"少し足のぐあいが悪いものですから、座ったままで質問をします。私からは、３２１ページ、上から５行目、雇用確保支援事業のうちモンゴル高専との科学技術交流事業について質問を致します。２０１７年、平成２９年６月からスタートしたとのこと。今年で７年目を迎える事業になりました。質問ですけれども、改めて、このモンゴル高専との科学技術交流事業の目的は何でしょうか。聞かせてください。","respondent":"小林商業・ものづくり課長","answer":"人手不足に悩んでおります区内中小企業にとりましては、若手の人材、特に技術を持った若手人材の確保につながるため、海外からの人材活用に対する期待が高まっているところであります。引き続き、こういう事業に品川区として力を入れていきたいと考えています。","voiceIndex":189,"id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"昨年５月に新型コロナウイルスが５類に移行し、経済活動もコロナ以前に戻ってきたことから、今後の景気回復を見込んで、企業の採用活動も活発化していると聞いています。そこでお聞きしますけれども、この事業が開始されてから、これまで何人が日本での就職を果たしたのでしょうか。","respondent":"小林商業・ものづくり課長","answer":"就職が進み始めたのが、令和に入ってから、令和元年度を皮切りにです。途中、新型コロナウイルスに伴う海外渡航の中止というのもございましたので、その間は止まっていた部分もありますけれども、これまでに計２０名の卒業生が区内中小企業６社に就職しております。","voiceIndex":191,"id":"exchange-087"},{"speaker":"木村委員","kind":"質問","question":"言葉の問題もあろうかと思いますが、どのような業種の企業に就職しているのでしょうか。お聞かせください。","respondent":"小林商業・ものづくり課長","answer":"その意味で、モンゴル高専の若者たちは学校で一旦勉強していますので、一定の日本語のレベルというのはあるわけですけれども、品川区としても、就職が決まるに当たってのフォローとして、日本語をきちんと、さらに磨きをかけていただくとか。","voiceIndex":193,"id":"exchange-088"},{"speaker":"木村委員","kind":"質問","question":"日本の若者でさえそうですから、言葉や文化、生活習慣の異なるモンゴルの学生にとっては、思いどおりに就職活動も進まない、進められないということでありますから、不安な点もあろうかとも思います。お聞きしますけれども、この点については、就職のミスマッチなどをなくし、スムーズに日本の生活や会社に入っていけるような配慮や工夫はされているのでしょうか。本区の取組などお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"就職した後にこちらで寂しくならないようにというか、ネットワークが維持できるように、モンゴルの若者同士で集まれるような勉強会、交流会も品川区で進めているところです。","voiceIndex":195,"id":"exchange-089"},{"speaker":"藤原委員","kind":"確認","question":"関連します。今の説明を聞きますと、この事業は、就職したいと考えるモンゴル出身の若者たちの立場、双方の意思を確認しながら、かなり丁寧に進められている事業だということが分かるのですけれども、採用したら終わりというのではなく、採用後の状況もしっかりと行くことにより、モンゴルの若者たちが長く元気で働いてくれることが重要だと思いますが、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"品川区に来ると、きちんと安心して働いていけるだろう」という安心感を持っていけるようにということで、この事業はしっかりやっていきたいと考えています。","voiceIndex":198,"id":"exchange-090"},{"speaker":"藤原委員","kind":"質問・要望","question":"自分たちの日本語能力や技術力を活かして日本で働きたいモンゴルの若者たち、区内の中小企業にとって、この事業はプラスになっていることは確かで、品川区にとってもメリットの大きい事業だと考えますが、いかがお考えになるでしょうか。この事業を大切に品川区で育てていただきたいと考えていますので、その辺についてもお伺いします。","respondent":"小林商業・ものづくり課長","answer":"つまり、今後、区内の中小企業の中で、ひとつ将来的に安心して働いていただける人材だということの認識もできているのだと思います。","voiceIndex":200,"id":"exchange-091"},{"speaker":"藤原委員","kind":"意見","question":"グローバルという意味でもモンゴルは大切だと私は思うのですが、やはり、毎回区民委員会でもお話ししていますが、まず日本の方たちをどういうふうに守っていくかが私は大事だと思っているのですけれども、最後にその辺も含めて答弁していただけますか。","respondent":"小林商業・ものづくり課長","answer":"そういった意味で、先ほどご質問も少し出ておりましたけれども、例えば今、若者たちも結構、奨学金の返済というのに追われているような学生たちも多い中で、そういう方たちも安心して企業に入っていただけるような仕組みとして、助成制度など。","voiceIndex":202,"id":"exchange-092"},{"speaker":"澤田委員","kind":"質問","question":"３０１ページ、健康診査、３０７ページ、もったいないプロジェクトについて質問いたします。品川区では、２０歳以上の偶数年に子宮がん検診を行っています。大変手厚く、とても心強いと思います。ここ数年の受診者の人数は、増加傾向または減少傾向にあるのか、そのように至った理由についてご見解をお聞かせください。","respondent":"若生健康課長","answer":"子宮がん検診ですが、こちらの推移につきましては、令和２年度から令和４年度までの受診者数で申し上げますと、まず令和２年度が１万５,９００人余、令和３年度が１万３,６５０人余、令和４年度が１万８,５６０人余と年々増加しています。","voiceIndex":205,"id":"exchange-093"},{"speaker":"澤田委員","kind":"提案","question":"そのような未接種の方たちは、西村委員も先ほど様々提案していたように、周知啓発については立体的に取り組んでいかれると課長もおっしゃっていましたけれども、それでもやはりワクチン接種は受けたくないという方たちをカバーする意味でも、ＨＰＶ検査の導入が効果的だと考えます。区としてはＨＰＶ検査の導入についてどのようなお考えでいるのか、また方向性などをお聞かせください。","respondent":"若生健康課長","answer":"医師会や検診実施機関等の理解・協力が不可欠になってありますし、区でもシステムの構築や実施体制の整備には相応の時間が必要と考えていますので、現時点ではかなりハードルが高いと感じておりますが、導入に当たっては今後慎重に考えていきたいと考えております。","voiceIndex":207,"id":"exchange-094"},{"speaker":"澤田委員","kind":"質問","question":"随時更新されているということと、様々頑張りポイントなど、また新しいこともいろいろやっていらっしゃるということで、大変うれしく思います。区では“もったいない”推進店を、現在１６３店舗とおっしゃっていましたが、次年度さらに１００店舗増やすという目標をプレスに掲げていらっしゃいます。情報の発信についてもどうお考えかお聞かせください。","respondent":"河内環境課長","answer":"エコルとごしですが、様々多様な発信をしている関係もございまして、次々新しいものを繰り出す方式を重視していますが、こういった定常的な取組もしっかりと発信し、皆様にご理解いただけますよう進めてまいりたいと考えているところです。","voiceIndex":211,"id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは、３０３ページ、感染症対策について新型インフルエンザ、それと３１９ページ、３２１ページ、３１５ページ辺りで、商店街、中小企業、五反田バレー等について質問します。初めに、午前中のおぎの委員の質疑の中で、４月以降の新型コロナワクチンがＢ類接種に変更ということで、それに伴って様々な救済制度なども変更されるのではないかと。よろしくお願いします。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"委員がご指摘のとおり、年金の額や死亡一時金、遺族一時金などといった制度も変更がありますので、こちらも丁寧に区民の皆様に周知していきたいと考えています。","voiceIndex":215,"id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"やはり、計画とどうしても合わなかった。これは、いわゆる企業や行政の壁を越えた起点となりたいという思いもあるので、私は、１つのやり方として商店街支援というのはいいのかと思います。なので、これを１つのきっかけとして、こういったことを五反田バレーの皆さんと話をしていただきながら、ぜひ進めていっていただきたいと思うのですが、その辺をどのようにお考えか、お知らせください。","respondent":"舩木生活衛生課長、小林商業・ものづくり課長","answer":"こちらは昨年の５月に５類相当に変更する前に、令和５年３月のときに、区としてしっかりと、こういった長年の、３年以上にもわたったコロナの対応をしっかりと検証して、今後の健康管理に結びつけていこうではないかということで。令和６年度におきまして、スタートアップエコシステム事業というものを予算に計上していますけれども、こういった中で、幅広い企業なり団体なり事業者なりというのが。","voiceIndex":219,"id":"exchange-097"},{"speaker":"塚本委員","kind":"質問・要望","question":"もう一つがシングリックス、不活化ワクチンですけれども、これは１回１万円を２回接種するという、２つのワクチンがあるのですけれども、これが令和５年度、ビケンについては３,３８０件、シングリックスはそれに対して１,３６０件という内容だったのですけれども、これが来年度は大きく逆転して、ビケン５,０００円が９６０件、シングリックスが５,４１０件、これが２回かかるということが。","respondent":"坂野保健予防課長","answer":"ところが実際、蓋を開けてみると、今お話があったように、かなり不活化ワクチンのほうに人気がシフトしているというのが分かります。それで、令和６年度の予算としては、シングリックス、不活化ワクチンのほうに多めに数を割り当てたという経緯です。","voiceIndex":225,"id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"実績的に見てシングリックスがというお話だったと思いますけれども、去年、いろいろな議会の場面で、帯状疱疹ワクチンの助成に関しては幾つか質疑が出ていますけれども、そのときにシングリックスというもののワクチンとしての優位性ですか、効果や有効期間といったことに関しては、それほど明確に、区の答弁としてはシングリックスが優位であるというようなことは出ていなかったように思うのですけれども。","respondent":"坂野保健予防課長","answer":"一年、二年では、いわゆるワクチン効率を計算するような値はなかなか出てこないと考えております。","voiceIndex":227,"id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"世間では、やはりシングリックスのほうがかなり優位だろうということで、一応、ホームページなどでは医者によく相談してどちらを打つかというのを決めてほしいと、区のホームページには載っていますけれども、そういった意味では、医者なども恐らく現場では、シングリックスのほうがいいのではないですかというお話が、相談すれば出てくるのかというようなことも想像されるところがありますので。","respondent":"小林商業・ものづくり課長","answer":"いろいろ我々は経営相談を日々お受けするところですけれども、この件については、二、三件程度ですけれども、やはり何か使える制度はないのですか、設備投資を支援するようなものはありますかというようなお問合せはございました。","voiceIndex":229,"id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"そういった中で、実際に使える支援策、簡単に言えば、買ったときに幾らか補助できるのですかと。こういったものがあるのかというところなのですが、実際に区として、また都や国なども含めた形で、あるのかないのかということについてお知らせください。","respondent":"小林商業・ものづくり課長","answer":"こういったものを幅広く、これは全業種ですけれども、使えるというような制度と、あと国の支援制度ということでいきますと、ＩＴ導入補助金が、一定要件であればこういうのを使い得るかというような話も専門家と話をしておりまして、こういうご相談なりご質問が来たときに。","voiceIndex":231,"id":"exchange-101"},{"speaker":"塚本委員","kind":"意見","question":"相談があった場合には、ぜひお願いしたいと思いますけれども、国のＩＴ導入補助金は、私もこういうものがあるのだと思って、一応、券売機なども対象にはなっているみたいですけれども、丸っとＩＴ化を業務的に変えていかないと、券売機だけの購入でということでは、なかなか助成の対応につながらないというところで、いわゆる個人でやっている飲食店みたいなところは、なかなか難しい支援策かというところで。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-102"},{"speaker":"田中委員","kind":"質問","question":"私は、３２３ページの商店街活性化推進事業についてお伺いいたします。そのうちの共通商品券普及促進事業についてであります。これはもう、特に商店街支援ということですので、プレミアム付商品券に関してお伺いしたいのですが、既にこの事業はもう何年にもわたって行われてきております。改めて、この共通商品券、プレミアム付商品券の商店街活性化に向けた目的・意義についてお伺いします。","respondent":"小林商業・ものづくり課長","answer":"この後、夏にはキャッシュレス決済ポイント還元事業というものを予定しておりまして、切れ目なくこういった事業が続くことによって、区内消費の喚起につなげることができるのではないかと考えております。","voiceIndex":235,"id":"exchange-103"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、では令和５年の春のときと比較いたしますと、申込み期間が今年は３月２１日からに対しまして、去年は４月１１日からで、販売そのものも今年は５月９日からが、昨年は５月１９日からということで、僅か１０日ほど前倒しで、この事業がなされるということでありますが、たとえ僅か１０日とはいえども早めに取り組むことの効果を期待されていらっしゃると思いますが、特に専決処分。","respondent":"小林商業・ものづくり課長","answer":"コロナが終わりまして、少しそこからは持ち直しているものの、またやはり直近、令和５年度の中で消費支出が落ち込んでいる中で、少しでも早く、また今日からは東京都の事業なども始まりますけれども、そういうものとの連動性なども考えまして。","voiceIndex":237,"id":"exchange-104"},{"speaker":"田中委員","kind":"質問","question":"私は、その流れをくんだ共通商品券だとも思っておりまして、合計１２億円ですが、要は２億円が広まるというだけではなくて、ではそれぞれの商店街なり個店が、流通している商品券を自らの売上げ増進にいかにして活かしていくかという前向きな取組が必要だと私は思いますが、この制度が導入されてもう何年もたっているので、例年のような毎年のような行事として捉えられて。","respondent":"小林商業・ものづくり課長","answer":"先ほど申し上げましたように、この事業は２００３年から始まって、発行支援という形で品川区商店街連合会の支援事業としてやってあります。","voiceIndex":239,"id":"exchange-105"},{"speaker":"田中委員","kind":"質問","question":"私は、さらに有効に事業を活かす上では、もう一段高い目標を掲げて、商店街のいわゆる活性化にという視点での評価にもつなげていくべきだと思いますが、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"我々の目標として、区民への定着なり区民の申込みという点で目標設定をしていますけれども、一番、究極的には我々、消費喚起という意味では、区内経済がやはり上向くというか、そういうところが最終的には、つまりは卸売・小売業というところも含めてなのですけれども。","voiceIndex":241,"id":"exchange-106"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味で、商品券そのものの売上げ増進も１つの目標と掲げられていますが、商品券を使える範囲が、大型店ではなくて商店街を中心にではありますが、数年前から、しながわ水族館で使えたり、タクシーで使えるというのは、これは使い勝手からするといいことなのかもしれませんけれども、共通商品券を導入する、そして商店街の支援がまずは第一にあるべきだという考えに基づくと。","respondent":"小林商業・ものづくり課長","answer":"区民の皆さんの身の回りのところでというところで、いろいろ、この点も含めて、今後どういう対象範囲がいいのかというのは考えていきたいと考えています。","voiceIndex":243,"id":"exchange-107"},{"speaker":"えのした委員","kind":"質問","question":"私からは、３０５ページ、自殺対策事業についてお伺いします。世界中で最も多くツイートされた論文「抗うつ薬とランニング療法」では、効果の比較をした結果から、鬱病や不安障害の患者に対する２種類の治療は、メンタルヘルスの有効性については差が見られなかったが、身体的な指標ではランニング療法のほうが抗うつ薬よりも優れていたと結論づいています。その後の区の取組や対策をお知らせください。","respondent":"坂野保健予防課長","answer":"区の自殺対策事業ですが、今お話があったように、今まさに３月です。それで、９月と３月が予防月間というふうに、基本法上、決まっておりますので、区民の状況に応じたいろいろなアプローチの方法を、何といいますか、組み合わせるというか、啓発を実施しています。","voiceIndex":246,"id":"exchange-108"},{"speaker":"えのした委員","kind":"質問","question":"歳入では、孤独・孤立対策推進についてお伺いしましたが、品川区の令和４年度アンケートでは、孤独を感じるのかの設問に対して、２０代・３０代、約５０％の方が孤独を感じると回答しており、子育て世代、ヤングケアラー、ひきこもり等も懸念されると意見を述べましたが、筑波大学医学医療系、災害・地域精神医学教授は、コロナ禍には世界中でメンタルヘルス、心の健康の悪化が問題となり、自殺者が増加。","respondent":"坂野保健予防課長","answer":"本年度も実施しております。その際の対応方法など、１回の研修で、あとはできるようになるかというと、なかなかそうはいかないとは思うのですけれども、こういった研修を繰り返し実施しています。","voiceIndex":248,"id":"exchange-109"},{"speaker":"えのした委員","kind":"質問","question":"子ども・若者の取組を、さらに拡充して進めていただければと思います。今、ゲートキーパーのお話がございましたが、品川区ではインターネットゲートキーパーについて、これはグーグルの検索エンジンを使った取組だと思いますが、私も「死にたい」と入れてみたのですが、すぐに厚生労働省のページなどにつながるようになっていますので、こちらも具体的に詳しくお知らせいただけますでしょうか。","respondent":"坂野保健予防課長","answer":"今お話があったように、区内にあるホストから、自殺に関する関連度の高い、リスクの高い検索をした場合に、今委員がおっしゃられたように、相談先を案内するような検索アルゴリズムで、相談先に誘導していく。その相談先につながった後は、人手でやっているという感じです。","voiceIndex":250,"id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"やめろというのはなかなか言えないと思うので、やめなくてもいいけれども、その辺の調査はしてほしいと思っています。私は、粗大ごみは、お願いをしてでもいいから、こういうことで粗大ごみを出してくださいぐらいの拡大はしたほうがいいと思っていて、ぜひその辺も考えていただきたいのと、あと、お礼を言ってほしいのは、ペットボトル。これは、区民の皆さんにもっと感謝をしてほしい。","respondent":"品川品川区清掃事務所長","answer":"ただ、統計を見ると、人口の多い自治体では有料化をしていないという傾向が非常に高いというところもありまして、そういった点もいろいろ含めながら、やはり２３区でバランスを取っていったほうがいいのかなどというところもいろいろ含めながら、今後、有料化については、やはり。","voiceIndex":254,"id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"意見","question":"次に行きます。それで、区民税の部分で、今、雇用の話をすると、単純に言うと２万７,６００人、１１.５％に、税４５.８％を負担してもらっています。それから、中間層とされる１０万６,０００人の方、４４.５％の方が４２.４％、合計で８８.２％で、私は相互扶助の在り方、それから中間層の方々の収入をもっとしっかり拡充していくべきだろうと思っていて、これは１つだけどうしても聞きたかった。","respondent":"小林商業・ものづくり課長","answer":"副業など、新しい働き方が出てまいっておりますので、いろいろな制度を見ながら人材の問題も考えていきたいと思います。","voiceIndex":256,"id":"exchange-112"},{"speaker":"松永委員","kind":"質問","question":"私からは、２９９ページの、そ族昆虫防除対策費について、３０７ページのカラス及び外来種対策事業について、同じく３０７ページのマイボトル用給水機設置助成について伺います。初めに２９９ページの、そ族昆虫防除対策費について伺います。そこで昨年に比べて、先ほどは質疑の中でもネズミについて伺ったのですが、今回は、スズメバチやスズメバチ以外の蜂についての相談件数について伺いたいと思います。","respondent":"舩木生活衛生課長","answer":"蜂に関するご質問ですけれども、統計上、蚊や蜂などと分類していまして、それがスズメバチかアシナガバチかなどというところの統計は今お答えできないのですけれども、蜂に関しましては、令和２年度５２３件、令和３年度５４７件、令和４年度６９６件と。","voiceIndex":259,"id":"exchange-113"},{"speaker":"松永委員","kind":"質問・要望","question":"早急に対応していただきたいのですが、この時期、特に４月から１１月、梅雨明けが特にそうした被害が大きいということを思います。そこで、例えば事前に対策という、例えば蜂の巣を作らせない対策はないのかということで、インターネット等で調べたら、様々グッズなどはあるのですけれども、そうした予防対策についての補助というのはあるのかどうか、確認だけさせてください。","respondent":"舩木生活衛生課長","answer":"今のところ、住まいのところに発生する巣に関しての助成の制度は持ち合わせておりません。","voiceIndex":261,"id":"exchange-114"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、その調査内容なのですけれども、例えば区内の公道や公園、児童公園や保育園、様々あるのですけれども、その中で調査場所について、どのくらいやられているのか確認させてください。例えば近隣住民の方から、ここはやっていないのではないかというような声も上がっておりまして、取り組んだ場所というか、調査された場所について、どういったところをやられているのか、改めて伺います。","respondent":"舩木生活衛生課長","answer":"蚊の対策についてのご質問ですけれども、区の場合、幼虫、いわゆるボウフラ対策というところで、成虫になる前の薬剤を、区全体で４万８,０００か所に行っております。","voiceIndex":263,"id":"exchange-115"},{"speaker":"松永委員","kind":"質問・要望","question":"そしてもう一つ、暑い時期の夕刻になりますと、小さな虫が大量発生しております。それで、たまに髪の毛についたり口の中に入ったりするのですけれども、そうしたところで、ユスリカの病気ですか、アレルギー性鼻炎などといったところでも、結構被害に遭われている方もいらっしゃるそうです。もちろん近隣住民の方に対しても、そうした周知をしていただきたいのですが、品川区の対応・対策をお知らせください。","respondent":"舩木生活衛生課長","answer":"ただ、発生源が、実は雨水ますと、河川が考えられるのです。立会川などの河川の管理は保健所の管理外なので、どういった対応かは存じ上げませんが、保健所としてはユスリカ対策も含めた対応を取っているということで答弁します。","voiceIndex":265,"id":"exchange-116"},{"speaker":"松永委員","kind":"確認","question":"３０７ページのカラス及び外来種対策事業について伺います。初めにカラス対策ですけれども、今頃、４月頃ですか、巣作りが始まって、ゴールデンウイークあたりに卵を二、三個産むということで、その中でよく言われるのが、ハンガーや木の枝を使って巣を作るということであります。これは現在もその１店舗のみなのでしょうか。その事業について今後どのように進めていかれるのでしょうか。","respondent":"品川品川区清掃事務所長","answer":"今後のいろいろな対策としましては、カラスにつきましてはカラス用ネットを今、区としては配布して対策を取っているというところを、一般的な対応としてやっているところです。","voiceIndex":267,"id":"exchange-117"},{"speaker":"松永委員","kind":"質問・要望","question":"そうですね。こうしたところも、見えないということで黄色い袋を推奨しているのであれば、ぜひもっと品川区民の方に周知していただければと思います。例えば、ごみの分別の冊子があると思うのです。資源などといったところに、こういったグッズもある、商品があるといったところも含めて進めていただければと思いますので、これは要望で終わらせていただきます。次に、ハトについて、野鳥について伺います。","respondent":"河内環境課長","answer":"一方で餌やりについて、そこの環境が汚れることについて防止する条例など、世田谷区、大田区などが設置している状況でありますが、直接規制できるものではないことから、結局、直営職員が何度も足を運び、注意し、粘り強く対応というのが基本になってくるかと思います。","voiceIndex":269,"id":"exchange-118"},{"speaker":"松永委員","kind":"質問","question":"例えばインターネットで調べたのは、ハトの駆除１万１,０００円からなど、よくネットには載っているのですけれども、そうした部分で、なぜネットではできていて品川区ができないのかというと、恐らく法律があるからだと思います。そうしたところで、駆除してほしいという方に対して、例えばハトの巣の、そういったところの補助というのはできるものなのかどうか、伺いたいと思います。","respondent":"河内環境課長","answer":"そうしたことから、各自治体におきましては積極的な駆除ということではお金をつけておりませんが、一方で、そういった特定の狩猟許可を得た業者など、精査に精査を重ねまして、非常にいい施策や道具などを磨きに磨いたというようなところを選びに選びまして現地に派遣して。","voiceIndex":271,"id":"exchange-119"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ、そうした民間との連携も含めて進めていただければと思います。要望です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"そして３０３ページのＨＰＶワクチン予防接種、３０３ページの感染症予防費についてお伺いします。すくすく赤ちゃん訪問事業ですけれども、これは非常に、先ほどもいろいろ質問が出ていましたが、検診率が９４％ということで非常に高いということで、これは私も、アウトリーチ的な支援というのが必要だということで、非常に進めてまいりました。それをまず教えてください。","respondent":"石橋品川保健センター所長","answer":"すくすく赤ちゃん訪問と見守りおむつ定期便の目的についてです。すくすく赤ちゃん訪問の目的につきましては、児童福祉法に位置づけられ、今は国のガイドラインに基づいて実施しております。国では、子育ての孤立化を防ぐということが目的と書かれております。","voiceIndex":275,"id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"今、目的をお聞きしましたけれども、かぶっているのです。非常にかぶっています。それを考えるならば、すくすく赤ちゃん訪問をされている方々というのは専門家の方が多いので、私はこちらを拡充して、できればそこで、民間に頼むかどうかは分かりませんけれども、両方、統合して、さらに、すくすく赤ちゃん訪問のほうをバージョンアップするという形のほうが現実的ではないかと思いますが、いかがでしょうか。","respondent":"石橋品川保健センター所長","answer":"見守り訪問につきまして、今、申請ベースというお話がありましたが、確かに申請していただいて見守り訪問に伺っている形にはなりますが、こちらは申請されていないご家庭に関しては勧奨ということを定期的に実施しているところになりますので。","voiceIndex":277,"id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、もう少し考えていただきたいということで、お願いしたいと思います。迅速性が求められるということだと思います。その際にどういう対応をされるのか。そして、注意喚起というのがやはり必要だと思いますし、そこの対応についてはどういう仕組みでやっていくのかということを教えてください。今回、男性なのですけれども、なぜ男性にこのワクチンを接種することになったのでしょうか。","respondent":"坂野保健予防課長","answer":"今回、東京都の補助も活用して、ＨＰＶの男性接種の補助を４月からスタートするわけですが、これは私からこれを目的としてというのは、なかなか強く言いにくい部分があるのですが、ただ社会全体としてＨＰＶの総量を抑えることによって、長期的に見て。","voiceIndex":281,"id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"男性に対するというデータが、エビデンスがないのです。女性のほうも今やっている中で、副反応が非常に多い。今、課題になっております。私は、エビデンスがないものに対して区が推進するというのはとても心配です。とても心配です。これは、品川区で何かあったときにどうやって責任を取るつもりですか。そこをお答えください。","respondent":"坂野保健予防課長","answer":"今のスキームだと、女性は法定というか定期接種なので、そちらのスキーム。男性は任意接種ですので、ＰＭＤＡ、医薬品医療機器総合機構の補償スキームというものが使われることになろうかと考えています。","voiceIndex":283,"id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"３１０ページの清掃費について、ビルピット汚泥収集運搬の混載化について、お聞きしていきたいと思います。この問題は品川区の問題でもあり、また２３区全体の問題でもあり、さらには特別区長会での検討・結論が求められる問題でもありますので、よろしくお願いいたします。２種類の車両が必要となることで、様々な課題が出てきています。混載が可能となった規制緩和についての認識と評価をお聞きいたします。","respondent":"品川品川区清掃事務所長","answer":"ビルピット汚泥の件です。基本的に、先ほど委員から説明があったとおり、一般廃棄物および産業廃棄物を混載して１つの車で持っていくほうが効率がいいということで、ビルピット協会等からも特別区課長会等に、数年前から意見を頂いているところです。","voiceIndex":286,"id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"陳情の内容は、各区の要綱において、ビルピット汚泥については産業廃棄物との混載を認める旨の改正をしてほしいと、特別区長会において混載実現に向けた検討を求めるものとなっています。そこで最後に、特別区長会において早期の議論が期待されておりますけれども、議論されるに当たり、認識をお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"今後多分、また下命というような形で課長会に下りてきて、再検討するなどという話も考えられると思いますので、またその状況に応じて対応を考えていきたいと考えています。","voiceIndex":288,"id":"exchange-126"},{"speaker":"せお委員","kind":"確認","question":"私からは、２９７ページ、不妊治療等支援事業、同じページで猫の適正飼養および活動支援事業を伺います。不妊治療です。こちらは確認ですが、事項別説明には、生殖補助医療の一環として、保険診療で行った男性不妊治療について５万円まで助成となっていますが、同じ時期に、もし男性も女性も治療があった場合でも、それぞれ助成していただけるとの認識でよろしいでしょうか。３点、お聞かせください。","respondent":"若生健康課長","answer":"ではどこを助成していこうかというところでいうと、特定不妊治療助成というのが、今まで東京都がやっていたところで品川区も上乗せしていたところが、保険適用で終了になりましたということで、これは経過措置も含めて令和６年度まで残るのですが。","voiceIndex":291,"id":"exchange-127"},{"speaker":"せお委員","kind":"提案","question":"ここからは思いだけ、１つお話しさせていただきたいのですけれども、保険適用前から４３歳以上というのは何も支援がないのがずっと引っかかっていて、あるクリニックの院長にお話を伺ったときに、４３歳以上の患者はそちらのクリニックでは４分の１いらっしゃると。４３歳以上の方も不妊治療を頑張っているということで、今日はメッセージだけお伝えします。次に、地域猫活動です。","respondent":"舩木生活衛生課長","answer":"今の委員の、いろいろな専門のボランティアや、いろいろな立場の方が連携して進めていくということも大事かと思いますので、これからこういう協力員制度を活用していく中で、主体的な団体の卵ではないですけれども。","voiceIndex":293,"id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"行政評価によると、それぞれ受診率は、４か月が９４.５％、９か月が８９.４％、１歳６か月児が９７.１％、３歳児が９６.２％、これまでも様々議論がありましたけれども、未健診家庭への対応はどのようにしているのか伺います。それから健康センターです。これを比較すると、利用料金収入が５,３００万円多いのですが、どうして委託料、つまり指定管理のお金が必要になるのか、この関係をお伺いします。","respondent":"小林商業・ものづくり課長、石橋品川保健センター所長、若生健康課長","answer":"令和６年度はですけれども、若干、金額は少し落ちる部分がありますけれども、やはり引き続き資金繰り事情。私からは、乳幼児健診を未受診の家庭のフォローについてご説明いたします。どうして必要かというところで、健康センターの指定管理料につきましては、令和６年度に１億３,０００万円余、計上しているところですが。","voiceIndex":296,"id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"確認","question":"融資のところで、返済状況が滞っているところへの支援というところがあったので、それを確認したいです。","respondent":"小林商業・ものづくり課長","answer":"ちょうど今年度末から来年度初めぐらいにかけて、コロナの期間中に借りた、いわゆるゼロゼロ的な部分といったものの返済というのがちょうど始まるようなところではありますけれども、こういった部分も引き続き資金繰りということで、問題が起きないように。","voiceIndex":300,"id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"健診ですけれども、今、非常に保育士たちがいろいろご苦労されて訪問したりしているのですが、健診の何か月をやっていないなどというのは分かっていくのでしょうけれども、すくすく赤ちゃん訪問事業やおむつ宅配事業など、ほかの事業で、この方は全部そういうのをしていないとか、この方はやっているとか、そういうことはチェックされたりしているのでしょうか。","respondent":"石橋品川保健センター所長","answer":"今、保健センターでやっている事業は、１つのカルテというものに記入していますので、それぞれの事業について、例えば未健診、訪問していないといった現状というのは、しっかり保健師が把握していますので、各事業の情報共有をしながら。","voiceIndex":302,"id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"個人カードのようなものがあって、チェックがなされているということです。健康センターのところなのですが、利用料の見込みの収入額が、先ほどご説明があって、予算書にも出ているのですが、表示があるのですが、最終的に区に入ってくる収入、利用料の一部が入ってくると思うのですが、その表示が予算書にないのですけれども、どこを見れば出ているのでしょうか。","respondent":"若生健康課長","answer":"ちょっと今、後ほど確認いたしますが、こちらの利用料収入が、先ほど申し上げました収入基準額を超えた場合、より収入が多かった場合、その差額の２０％を区に納めていただくというようなことで、協定として取り決めるということにしておりまして。","voiceIndex":304,"id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"その金額が、事務事業の細かい事項別明細だと約６００万円となっています。ですから、ここのところは、指定管理制で利用者の収入が入ってくるという、大変、指定管理制としては非常に合致した、いい制度だと思うのですが、せっかく入ってくる金額が、予算書にも出てこないし、決算書にも出てこない。その点については健康課ではないと思うのですけれども、予算書についてはどうでしょうか。","respondent":"遠藤財政課長","answer":"全て雑入のところに入っていまして、来年度、６００万円ほど計上しています。ほかの金額が大きいので、代表的なものを書いていますので、今後は検討していきたいと思います。","voiceIndex":306,"id":"exchange-133"},{"speaker":"松本委員","kind":"質問","question":"私からは、３１５ページ、創業・スタートアップ等支援経費について伺います。お願いします。","respondent":"小林商業・ものづくり課長","answer":"例えば、ＳＨＩＰにおきましては、従来、大崎地区が工場地帯であったことから、新しい活用方法も、産業関連に近い施設の利用ということで、新たにＳＨＩＰがオープンしているということもございまして、そういう中で、品川区の中でこういう取組が充実したと認識しています。","voiceIndex":309,"id":"exchange-134"},{"speaker":"松本委員","kind":"質問","question":"いい取組で、ほかの自治体から視察もよく来ているようにも伺っていますので、いいことだと思います。それで、創業支援センター等運営費の行政評価シートを拝見すると、入居者数の累計が示されています。これは累積なので、入居者が入れ替わるとどんどん増えていく、自然に増えていくような数字だと思います。そこで、複数の施設があるので、それぞれの施設の直近の入居率をお願いいたします。","respondent":"小林商業・ものづくり課長","answer":"コワーキングスペースは、やはり９割程度です。天王洲が、今１０部屋あるうちの７部屋ということで７０％。広町一丁目工場アパートも同様の、７０％、８０％といった稼働率です。","voiceIndex":311,"id":"exchange-135"},{"speaker":"松本委員","kind":"確認","question":"私のほうでも募集状況などを確認すると、若干、今のお話でも出ましたけれども、広町のほうが７割だったりすることがあるのかということで、ここがなかなか埋まらないことも過去見ているのですけれども、これはなかなか埋まらない状況が発生するのは、どういう理由がありますでしょうか。","respondent":"小林商業・ものづくり課長","answer":"天王洲あるいは広町一丁目工場アパートにつきまして、例えばＳＨＩＰと西大井、武蔵小山との違う点というのが、基本的にレンタルオフィス中心か、そこに運営スタッフなり。","voiceIndex":313,"id":"exchange-136"},{"speaker":"松本委員","kind":"質問","question":"本当は、入居率がまだ引き続き低めに出るようだったら、多分、広町一丁目工場アパートは築年数がたっているということも１つの理由なのかと思っていたのですが、入居率が高まっているということで、いいことだと思います。短期的にそういう状況が続くのはしようがないかと思うのですが、結構もう長く別の使われ方がしているということについて、これは今後どういう見通しをお持ちなのか伺います。","respondent":"小林商業・ものづくり課長","answer":"我々としては、五反田バレーやＩＴ企業というだけではなくて、ものづくり、中小企業といったところの支援もということで、ものづくり創造センターを運用、運営していますけれども、今後、中小企業施策のニーズや変化も見ながら、今後の在り方も考えてまいりたいと考えています。","voiceIndex":315,"id":"exchange-137"},{"speaker":"松本委員","kind":"質問","question":"名前と実態が少し違うのが続くというのは、あまりよくないかと思いますので、検討していただければと思います。次に、品川ビジネスクラブ助成金に関連して、区も共催されていますビジネス創造コンテストについて伺います。高校生ぐらいだったら、もうプレゼンテーションの機会があってもいいのかと思うのですけれども、この点はどうお考えでしょうか。","respondent":"小林商業・ものづくり課長","answer":"ただ最近は、一般枠も実は、小学生はあれなのですけれども、中学生や高校生を排除しているわけではなくて、いわゆる大人の部のほうに例えば中学生が応募したり高校生が応募して、実際、ファイナリストと呼ばれる最後の１０名に残るような状態も出てきているところでございまして。","voiceIndex":317,"id":"exchange-138"},{"speaker":"松本委員","kind":"質問","question":"一方で、ただそちらのほうの一般枠というのは、どうしても狭い門を、全国の方たちと、全国の成人の方たちと戦い抜いてという枠で、結構狭い門かと思います。この起業塾に、区民枠の優秀な方をさらにつないでいって、起業の事業計画などというのをつくるようなことも、試みられてもいいのではないかと思いますが、いかがでしょうか。","respondent":"小林商業・ものづくり課長","answer":"我々としましては、創業支援施設は個々に運営しているというよりは連携して、いろいろイベントなども、取組を通じて協力して、新たな才能を伸ばしていくようなことも応援していければと考えています。","voiceIndex":319,"id":"exchange-139"},{"speaker":"松本委員","kind":"質問・要望","question":"そうですね。もう一問あったのですけれども、時間がなくなりましたので、ぜひ引き続き頑張っていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":321,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"私は、３２３ページ、共通商品券普及促進事業についてお聞きしたいと思います。この事業について、区民に対する販売周知方法について教えてください。","respondent":"小林商業・ものづくり課長","answer":"一番大きく我々がＰＲしているのが広報しながわで、今度、間もなく載るようなところもありますけれども、大きく周知しているということと、あとは中小企業センターをはじめ、区内施設でもこういったパンフレット、あるいは区内の郵便局や。","voiceIndex":323,"id":"exchange-141"},{"speaker":"須貝委員","kind":"意見","question":"区民の皆さんは忙しいのです。日々の生活に追われて、仕事に追われて、趣味やボランティア活動、多忙な日々を送っています。商品券販売について、お知らせに気がつかない方がたくさんいらっしゃると思います。ここで、区の予算を使うならば、この販売に対する周知方法は、私は非常に不平等だと思うのですが、その辺についてご見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"先ほど、広報しながわも含めというところでお知らせいたしましたけれども、そういった紙を使った媒体での周知という以外に、ホームページや、あるいはＳＮＳという形も使って、なるべく世代もいろいろ異なるというところもありますので、幅広い方法で周知しているという状況です。","voiceIndex":325,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"私が調べた中で、新宿区ではしっかり区民の全世帯にプレミアム付商品券の申込みの案内を郵送しているのです。区の予算、税金を使うわけですから、区民全世帯に対して平等に、こういう案内を送るべき、周知するべきだと私は思いますが、お答えください。今の周知方法では、広報などで気がついた人だけが、特定の人だけが利益を得る仕組みになっていませんか。これもついでに教えてください。","respondent":"小林商業・ものづくり課長","answer":"令和５年度でいきますと、４万冊、４万冊ということで、春・秋です。例年の販売状況によって変わりますけれども、実際、その中で９割近く、９５％など、それぐらいの割合で販売ができているというような状況です。","voiceIndex":327,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"区でこれだけの予算を投入して、皆さんに共通商品券を買ってください、産業振興も含めて、皆さん、協力してくださいと言うならば、区の予算を使っているなら何世帯の方がこれを買っているのか、そして、これは予算を投入しているのですから、その成果をやはりきちんと調べておくという姿勢が、産業振興の課、商業・ものづくり課ですが、必要ではないですか。これは毎年、そういうものが何もないのです。","respondent":"小林商業・ものづくり課長","answer":"令和４年度の例えば決算ベースの数字になってしまうのですけれども、春でいくと例えば４万冊、秋でいくと６万１,１７９冊という形で、商店街連合会で後々まとめて、販売状況に応じて、どれぐらいの割合で売れたかという数字は、それぞれの年度において把握しています。","voiceIndex":329,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"全くこれは把握していないのです。「品川区商店街連合会さん、お願いします」。任せている。実際、それが皆さんに平等に使われているのですか。多くの業種にわたっているのですか。何世帯の方が購入しているのですか。そういうことが分からないで、ただ予算を使っています。全く中身がないのですから。やはりその辺は私はきちんとやってほしいのですが、もう一度だけご見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"商店街連合会で取りまとめているというのもありますけれども、我々も区の決算という形で申し上げているところですけれども、先ほど申し上げたような令和４年度の決算のベース。","voiceIndex":331,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"ぜひ、やはり長年やっているのですから、「品川区商店街連合会さん、その実態を教えてください」と。それは区政にやはり反映させたいのですという気持ちで、私はしっかりデータを取得して、品川区としてもきちんと検証すべきだと思いますので、そこはしっかりやってください。品川区も、住民登録がある方に限定するべきではありませんか。そして、この仕組みは間違っていませんか。ご見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"プレミアム付商品券の例でいきますと、実際、区内の方ということプラス、区外の方で買っていらっしゃる方も一部いらっしゃいますけれども、我々の把握している数字としまして、９１％の部分は区民の方が購入されているというところでございまして、そういう意味では。","voiceIndex":333,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"そうしたら、区長だって、いや、区民の税金ですから、区民にやはり還元したい、区民に使ってほしいというのは、誰でもトップに立つ人は当たり前です。こういうふうに、しっかり分けて、ではどういうことですかということは、結局、ここでは半分は、百貨店、家電量販店、スーパーマーケット、ドラッグストア、そしてディスカウントストア、洋服・スーツ店、ショッピングセンターにも使える。","respondent":"小林商業・ものづくり課長","answer":"一方、我々が今年度、事業実施ということで、切れ目なく連続実施ということで、キャッシュレス決済といったものも事業を実施していますけれども、またその場合につきましては、商店街連合会以外の部分もというところで、店舗が対象になるようなことがございまして。","voiceIndex":335,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際、すぐそばにあるのですから。そういうふうに協力しよう。やはり、そういうことも産業振興につながるのではないのですか。しています。全額とは言いません。やはりそのような、消費者にも選べる仕組みというのがあっていいのではないですか。やはり、そういうことが消費者の心理ではないですか。そして、不平等だということは、やはり考えていただきたいと思います。ご見解をお聞かせください。","respondent":"小林商業・ものづくり課長","answer":"ただいまいろいろご指摘いただきまして、今後、我々の産業振興の中も、幅広く支援していく部分と、また見直す部分と、いろいろあるかと思います。そういう部分を含めて研究してまいりたいと考えています。","voiceIndex":337,"id":"exchange-148"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、３０１ページの各種がん検診について伺いたいと思います。本人の人生にとっても、がんの早期発見、早期治療というのは本当に大事なことだと思うのですけれども、それにつなげていくために、私はがん検診の受診率をもっと引き上げて、早期発見、早期治療につなげていくということが、とても大事なことではないかと思うのですけれども、区としての見解を伺います。","respondent":"若生健康課長","answer":"具体的には、科学的根拠に基づくがん検診の実施や区民への周知、それから国の指針に基づくがん検診の実施や精度管理の向上、それから受診率の向上等に努めているところです。","voiceIndex":340,"id":"exchange-149"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この中でも目標というのが出ているのですけれども、年度ごとの目標というのが分からない感じなのです。これは、健康プラン２１の第２期のところでも、それが第１位に挙げられて、この健康格差の解消というところが大きく取り上げられていたわけですけれども、私はこの解消・解決というか、そのためにも、がん検診の無料化に、ぜひ品川区としても踏み出していただきたいと思いますけれども、いかがでしょうか。","respondent":"若生健康課長","answer":"がんの年度ごとの目標ですが、がん対策推進計画ですが、こちらについては５年間のスパンで目標管理をしていくということになってございまして、特段、年度ごとに目標を設置して毎年毎年クリアしていくというようなことはやってございませんが、当然、がん検診の受診率や。","voiceIndex":342,"id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"低所得者といっても生活保護だけですよね。もう一つ伺いたいのが、先ほども出てきたのですけれども、ＰＳＡの、前立腺がんの検診についてです。それから、これが何で今出てきたのかということで伺いたいのですけれども、この理由のところに、がん予防重点健康教育およびがん検診実施のための指針という、そこを理由に挙げているのですけれども、これは、できたのが平成２５年のときですよね。","respondent":"若生健康課長","answer":"前立腺がんにつきましては、国の推奨するがん検診からは外れております。東京都の生活習慣病の指導部会、がん部会からも、これは死亡率減少効果の有無を判断する根拠は現在では不十分だということで、指導を受けているところです。","voiceIndex":344,"id":"exchange-151"},{"speaker":"大倉委員","kind":"提案","question":"３０３ページの任意予防接種、３０７ページ、もったいないプロジェクト、載っていないので商店街に関連して選挙割について伺います。選挙管理委員会でも、商店街での期日前投票や投票所の拡大というところの提案と一緒に、商店街は相性がいいので、選挙割というのもやってはどうですかというところではあるのですが、これはぜひ商店街の視点から教えていただければと思います。","respondent":"河内環境課長、小林商業・ものづくり課長","answer":"一方で、国でも多種類のドギーバッグを用意しておりまして、１つですが、まずこの間、環境講演会でＩＭＡＬＵさんもおっしゃっていましたが、蜜蝋ラップなど、いろいろ、商品名になりますので、何か容器などがありますけれども。商店街におきまして、それぞれのイベントやキャンペーンなども活かしながら、そういう工夫の中で投票率アップに向けて取組を進めていただく、それぞれの自主判断の中で進めていただくということで考えております。","voiceIndex":347,"id":"exchange-152"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後もドギーバッグは、食品ロスを減らしていくというところで、ぜひ進んでいっていただきたい、いろいろ活用していただきたいと思っているのですが、今後またドギーバッグは、今いろいろな使い方、２種類でなどというお話もありましたが、名称や素材、あと利用しやすさやデザイン性なども含めて、ぜひ使いたくなる、ぜひ使ってみたいという工夫をしていただいて。","respondent":"河内環境課長","answer":"それからもう一つ、民間企業のもので恐縮なのですが、無印良品の中で非常に展開されておりまして、ここの利用が高いことが分かってまいりました。無料で登録できますので、ここに関しましてはしっかりとアプリを登録しながら進めてまいりたいと考えています。","voiceIndex":350,"id":"exchange-153"},{"speaker":"大倉委員","kind":"意見","question":"マイボトルは、ここまでいろいろアプリも使いながら周知を進めていっているというところで、マイボトル運動はいろいろなところで既に進んでいるという認識なのですが、区としても、これからもさらにマイボトルを進めていくというところでは、今も、もったいないプロジェクトの店舗登録数などもあって、そういったところへの、無印良品で給水を進めているなどというところのお話だったと思うのですが。","respondent":"河内環境課長","answer":"ただ、まだ出始めで、ロケットで言うと第１段階ぐらいです。一定、周知や利用方法が区民の中で安定してまいりましたら、そういった形の連携もしっかり進めてまいりたいという視野で、今後、設計してまいりたいと考えているところです。","voiceIndex":352,"id":"exchange-154"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、３０７ページ、使い捨てプラスチック削減推進、今もありましたがマイボトル用給水機設置助成について、３０７ページ、環境啓発・推進事業、関連して宅配ボックスの設置推進、３２１ページ、時間があれば商店街活性化事業費、イベント事業助成から宿場まつりの支援強化について伺ってまいります。例えば区の施設内や民間へのウォータースタンド、ウォーターサーバーの設置場所を拡大してほしい。","respondent":"河内環境課長","answer":"こういった事業者を選んだのには理由がございまして、６月から早くもスタートを切りたいということでございまして、そういったところでスピード感を重視いたしまして、専門業者の知見を活かしながら進めてまいりたいと考えているところです。","voiceIndex":356,"id":"exchange-155"},{"speaker":"あくつ委員","kind":"提案","question":"暑過ぎるので。自分たちのアイデアを提案したりする。２０１８年に、これは日本で初めて品川区議会で採択されて、これもいろいろなことがありました。併せて、品川区は２月に内閣府のＳＤＧｓ未来都市および自治体ＳＤＧｓモデル事業に申請されたと伺っています。これは所管が異なってくるのですけれども。具体的にどういう内容で、予算の積算根拠についても教えてください。","respondent":"河内環境課長","answer":"そういった中で、持続可能な社会をつくるに当たりまして、マイボトルの運動が非常に大切になってくるという思いの中で、この予算をつけて行ったですが、もとより予算規模ではございませんで、そういった意義、また子どもが未来を憂う心に触れまして。","voiceIndex":358,"id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区で確認したのですが、こうした発信は今まで広報等ではされたことがないということでした。品川区は、やはりＳＤＧｓ未来都市として、今目指していますけれども、申請を２月の末にされたと伺っておりますが、ソフト面においては、こうしたＣＯ２削減のために、公式のホームページやＳＮＳ等で、再配達を削減する取組について、ぜひ発信していただきたいというのが１つです。","respondent":"河内環境課長","answer":"そういったところに対しまして、積極的な検討を今後加える必要があるかというところで認識しています。","voiceIndex":360,"id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、宿場まつりの支援について伺いたいと思います。時間がないので端的に申し上げますけれども、昨年９月に４年ぶりに宿場まつりのパレードが行われました。こうしたところで、これは品川区の商業・ものづくり課として、しっかり支援していただきたいという要望がありますけれども、この点についてご答弁を頂きたいと思います。","respondent":"小林商業・ものづくり課長","answer":"やはり今、商店街の課題として、後継者というか担い手不足というのがあります。その中で、例えば宿場まつりのように区を代表するような行事ということになりますと、例えば補助金の申請というのが当然出てくるわけですけれども、その業務でも１つ、重たい作業になってまいります。","voiceIndex":362,"id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今朝一番の、こしば委員の質問の中で、業務サポーターは例えば決算の手続などといった補助金の申請などを行うというようなお話もありましたが、やはり、例えば宿場まつりの実行委員会といったところに同席していただいて、水辺の観光フェスタは、文化観光課の職員がぴったり張りついて伴走していただいていますけれども、これは商業・ものづくり課の所管というところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":364,"id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３０５ページ、二酸化炭素排出量算定クラウドサービス利用助成、３１５ページ、創業・スタートアップ等支援経費についてお伺いいたします。最初に、３０５ページのＣＯ２の算定のことについてお尋ねします。そこで、これは新規事業だと思うのですけれども、二酸化炭素、ＣＯ２排出量算定クラウドサービスの利用助成に対しての狙い、あと対象、効果をお尋ねしたいと思います。","respondent":"河内環境課長","answer":"そうしたことから、環境マネジメントシステムの推進ということで中小企業はやってきたのですが、脱炭素社会の実現というところに大きく世界がかじを切ったというところで、具体的には、下請という言い方はおかしいですが、サプライチェーンに加わる意味で。","voiceIndex":366,"id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"確認","question":"今のご説明で、区内の中小企業において、ＣＯ２算定新規事業の利用ニーズがあることは、具体的にアンケートやヒアリングで確認をしたのかどうかというのをお聞きしたいと思います。","respondent":"河内環境課長","answer":"こうした動向を考えますと、こういった手助けが要る事業者を支援することによりまして、区全体の中小企業者に関する、あるいは業務に関する部門のＣＯ２の削減につながるということで、こういったサービスに至ったです。","voiceIndex":368,"id":"exchange-161"},{"speaker":"高橋（伸）委員","kind":"確認","question":"今、これは確認していませんというご説明だったのですけれども、これは、確認していないということは、なぜこのサービスが必要と判断して事業化しようとしているのかというのをお聞きしたいと思います。","respondent":"河内環境課長","answer":"先ほどご説明した流れの中で、今まではマネジメントシステム等で省エネ診断というのを受けていたわけです。これに伴いましてＣＯ２の削減が把握できたのですが、一方で、この流れが変わっていない中でＣＯ２排出量についての明確な数字が必要になってきているです。","voiceIndex":370,"id":"exchange-162"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これは、助成制度の利用者に対して、都が実施する省エネルギー診断の活用を進めるとプレスにも書いてありますけれども、これは義務ではなくて、あくまで勧めるというスタンスだと思うのですけども、その理由はどういう理由なのかをお尋ねしたいと思います。","respondent":"河内環境課長","answer":"こういった二面的なサービスを受けることによりまして、企業はより選択肢が増え、行うことが容易になってくるということから、こういったサービスを進めたです。","voiceIndex":372,"id":"exchange-163"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。ぜひ来年度に向けて進めていただきたいと思います。次に３１５ページ、創業・スタートアップ等支援経費についてお伺いします。これは、まず４点お伺いします。３点目が、品川区が目指すスタートアップエコシステムの姿を踏まえた上で、武蔵小山と西大井、それぞれの創業支援センターがありますけれども、その果たすべき役割をどう捉えているのかということをお尋ねします。","respondent":"小林商業・ものづくり課長","answer":"武蔵小山は女性起業家ということでかなり認知も高まって、またこれは２３区の中でも特別な、特異な位置づけというのですか、オリジナリティがあると考えておりますけれども、西大井の中で、若者・学生といった部分を応援する、先ほどのアントレプレナーの部分ですけれども。","voiceIndex":374,"id":"exchange-164"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"要望で終わらせていただきます。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":376,"id":"exchange-165"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6693#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":132445,"voices":377}},{"id":"r06-20240312-3","meetingId":"r06-c-budget","date":"2024年3月12日","dateIso":"2024-03-12","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"本日は、３６０ページ、防災費について、時間があれば、３６５ページ、備蓄物資購入・管理費について質問いたします。令和６年度、区ではウェルビーイングを実現するために様々な施策を打ち出しています。そこでお伺いするのは、窓ガラスの飛散防止対策を行っている世帯はどのくらいあるのでしょうか。区として把握していらっしゃれば、推定でも構いませんのでお答えいただけますでしょうか。","respondent":"平原防災課長","answer":"この内数が窓ガラスまできちんと対応しているのではないかというふうに推定しています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"３５.９％、思ったよりは多かったのですが、やはりそこまで高くはない数値なのかなと思いました。先ほど対策を行っている世帯の推定数は３５.９％とお伺いしましたが、窓ガラスが割れることに対して対策をとっている世帯が、区内にどの程度あればいいと考えていらっしゃるのか、もし目標数がありましたらお聞かせください。","respondent":"平原防災課長","answer":"先ほど、委員からもございましたとおり、在宅避難、区では、現在、推奨しておるところですので、在宅避難をやるためには、やはり窓ガラスの強化が必要ですので、どのぐらいの割合ということではなくて、全てやっていただくということが考え方にあるかと考えています。","voiceIndex":6,"id":"exchange-002"},{"speaker":"澤田委員","kind":"質問","question":"そうですね、１００％、皆さんやっていただくということがもちろん目標だと思うのですが、次年度どの程度というか、一気に全部１００％というのは難しいと思うので、段階的にはどのような感じでしょうか。","respondent":"平原防災課長","answer":"段階的にといいましょうか、これは普及啓発ですので、やはり災害時の備えとしての必要性を強く訴え続けていくということが重要かというふうに考えてあります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"澤田委員","kind":"質問","question":"１００％を目指す中で、窓ガラスの飛散防止フィルムが普及していない理由として考えられることとしては、区としてどのようにお考えでしょうか。","respondent":"平原防災課長","answer":"浸透していないということでしたら、やはり防災の備えとしての窓ガラスの飛散防止の必要性が理解されていない、浸透していないということと、もう１つは、それが分かっていても、張る手間みたいなところを考えているのかなというふうには推測しています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"澤田委員","kind":"質問","question":"葛飾区では、高齢者や障害のある方に対し、ガラス飛散防止フィルムの張りつけ費用を２万円まで補助したり、足立区では、家具等の転倒防止や扉の開放防止に必要な工事、建物の窓ガラスまたは家具等の窓ガラスに飛散防止フィルムを張る工事に対し、全額ではないものの１０万円ほどの補助を出しています。区としてはどのようにお考えでしょうか。","respondent":"平原防災課長","answer":"区民の皆様が災害時に実際に在宅避難できるようにするためには、やはり平素からの準備が大事ですので、そういう中に窓ガラスの問題も含まれているのだということを、区ではまず訴える。","voiceIndex":12,"id":"exchange-005"},{"speaker":"澤田委員","kind":"質問","question":"度々お答えいただいて、ありがとうあります。しかしながら、旧耐震建築の建物である場合は、倒壊や家具の転倒だけでなく、大地震により窓ガラスが割れてしまう危険性もあるとお聞きします。品川区の全世帯のうち、戸建てとマンションの割合、また、旧耐震の戸建ての現状などを教えてください。","respondent":"長尾建築課長","answer":"今、住宅に関しては、耐震化促進事業の中で、新耐震基準に合致した建物と、耐震改修する、もしくは建て替えをするところを促進しておりますので、その中で窓ガラスの飛散に対しても、一定、対応できていると認識しております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"澤田委員","kind":"質問","question":"ですが、感震ブレーカーなど、きめ細やかな部分まで防災を進めている品川区だからこそ、より細かいところまで、よりきめ細かく防災課がリーダーシップをとり、自力で対策を行うことが難しい６５歳以上の高齢の方や障害のある方、ほかには旧耐震の戸建てにお住まいの方など、対象を絞るような形で補助を行うことはいかがでしょうか。区としての考えをお聞かせください。","respondent":"平原防災課長","answer":"そういったところの優先順位なども考えながら、各所管と連携して、どういう支援方策、あるいは、どういう啓発方法があるのか研究してまいりたいと考えています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"澤田委員","kind":"質問・要望","question":"ぜひ進めていただきたいと思います。続きまして、防災備蓄についてお伺いします。防災備蓄に女性目線のものが増えたことと思います。出産後のママには、母乳パットや、出産直後から一、二か月の間、悪露が出るため、そのためのお産パットも必要になることもあり、こちらの備蓄もあったほうがいいと思いますが、区としては、どうお考えでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"女性目線での備蓄というお話です。現状は、委員ご紹介いただいたとおり、おりものシートを来年度、備蓄してまいります。妊産婦についての備蓄に関しては、今後、検討してまいりたいと思います。","voiceIndex":18,"id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"昨年の第３回定例会での一般質問にて、火災被災者に対して従前居住者用住宅を１か月間以上の仮住まいができるようにと訴えさせてもらった内容の中で、寝具、日常生活用品や電化製品を準備した上でと要望させていただいた際に、区の見解として、火災被災者の従前居住者用住宅への入居期間を数か月間程度に延長することを検討し、電化製品等の常設については今後の研究課題としていくとありました。","respondent":"伊藤災害対策担当課長","answer":"ほかのことにつきましては、まだまだ研究しているような状況ですが、被災された方が居住できるように、再建できるような形で、能登のような長期間という形ではなくて、おおむね１か月程度ということで考えてはおるのですけも。","voiceIndex":21,"id":"exchange-009"},{"speaker":"ゆきた委員","kind":"確認","question":"必要最低限の照明器具、カーテン、エアコンは検討され、毛布類は災害時に提供されるので、ほかの電子レンジ等を含めて考慮されることを確認させていただきました。用地取得では、のんき通りに面する豊町五丁目開放広場、豊町五丁目児童遊園の拡幅をされ、現在の維持管理を公園課でされていますが、この２つの広場と公園の活用について、今後の計画と運用についてお聞きします。","respondent":"小川木密整備推進課長","answer":"今後の予定といたしましては、来年度、基本・実施設計を行いまして、令和７年度に工事を行う予定です。","voiceIndex":23,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ワークショップも開催されて、地域の要望に資する場にしていくということを確認させていただきました。この地域は、やはり防災に資する場としての要望を私もお聞きしています。この課題は、活動拠点を持っていない荏原第三分団においても同じ状況です。そこで、まず、区内の公園や広場、防災広場は、防災活動に資する拠点の機能充実として、どのように活用されているのかお聞きしたいと思います。","respondent":"高梨公園課長","answer":"木密地域をはじめとして、区内に現在２７４ある公園、防災広場等につきましては、地域の一時集合場所等をはじめ、地域の皆様の防災活動区民組織の防災倉庫もあります。そういった意味で、幅広い防災拠点として使用されているという状況です。","voiceIndex":25,"id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"区内の公園が様々防災に資する機能として活用されていることを確認させていただきました。そこで、改めて豊町五丁目開放広場、豊町五丁目児童遊園の拡幅のための用地について、今後のこの地域での安全の必要性から、防災に資する拠点としての可能性についてお伺いできればと思います。","respondent":"小川木密整備推進課長","answer":"それともう１つの開放広場に関しましては、今後、周辺の皆様のご意見を聞きながら検討していきたいと考えています。","voiceIndex":27,"id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"本日もどうぞよろしくお願いいたします。私からは、３４９ページのＰａｒｋ－ＰＦＩの導入、３６１ページの防災訓練経費、３６３ページの携帯トイレ全戸配布経費について伺います。携帯トイレ全戸配布経費について伺います。配布に至った検討経緯、本施策の狙いをお教えください。それから、他区の事例があれば、併せてお教えください。","respondent":"平原防災課長","answer":"災害時に主に下水道の破断によりましてトイレの確保が課題となるということは以前から認識していたところです。","voiceIndex":30,"id":"exchange-013"},{"speaker":"山本委員","kind":"質問","question":"理解いたしました。私も能登半島地震により、災害となり水が使えなくなったときのトイレ問題の重要性を改めて感じることとなりました。迅速な判断を評価いたします。関東でも大地震が起こるかもしれません。今回、全区民への無償配布ですが、特に在宅避難にとって有効となると考えますが、区は、災害発生時の在宅避難者をどのぐらいと想定していますでしょうか、お教えください。","respondent":"平原防災課長","answer":"令和４年度の東京都の被害想定では、避難者数がピークになる時点での在宅避難者数は、区内で約３０万人、具体的には２９万１,３６２人と想定されているところです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問","question":"全体約４０万人に対して３０万人程度という、７０％強、多いですね。マンション住まいなどの在宅避難できる方に、より多く在宅避難をしてもらう環境を整えるために、トイレの準備は欠かせないと考えます。１人２０個ですが、何日分と想定しているのでしょうか、お教えください。","respondent":"平原防災課長","answer":"今回、全区民に配布する予定の２０個ですけれども、私ども、３日分と考えています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"災害の備えは、最低３日分が基本だと思いますので、最低限はカバーできると考えます。一方、経済産業省では、備蓄目安として、１人当たり７日分を推奨しており、多いほどよいと考えますが、不足分はどのように考えておりますでしょうか、お教えください。","respondent":"平原防災課長","answer":"品川区の地域防災計画におきましても、今回の修正で、家庭内備蓄はこれまでの３日分から７日分を推奨する方向で修正させていただいたところですので、私どもも今回の３日分は、３日分の備蓄品を配るというよりは。","voiceIndex":36,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"理解いたしました。この配布の機会を通じて皆様に気づいてもらい、各自での購入を促すことをとてもよいと考えます。配布は、来年度のいつ頃を予定しているのでしょうか、お教えください。","respondent":"平原防災課長","answer":"本事業につきましては、予算をお認めいただきましたら、令和６年度に入りまして契約手続を進めさせていただきまして、併せて、同封する予定の「しながわ防災ハンドブック」、全面改訂いたしますが、こちらの印刷を併せて進め。","voiceIndex":38,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"理解いたしました。本件は予算５億円と、前年度防災費の予算の約４０％に相当する大きな取組です。備蓄品のあっ旋の案内などについてですけれども、先日、防災フェアで配っていたものは、区民の方から、少し古く分かりにくいとの話を伺いました。私もそう思います。少し時間があるので、分かりやすいものに見直しということはいかがでしょうか。今回、自助を促すことが目的の１つです。いかがでしょうか。","respondent":"平原防災課長","answer":"今お話がございました防災用品のあっ旋ですけれども、こちらは内容については随時見直しを行っているところですけれども、よりよいものとなるように、今後も検討を進めてまいりたいと考えています。","voiceIndex":40,"id":"exchange-018"},{"speaker":"山本委員","kind":"質問","question":"ぜひよろしくお願いいたします。来年度、東京都のデジタル地域通貨が進むと考えますが、今後、このポイントサービスを使って、区で防災グッズの購入を促すというのはいかがでしょうか。本件は、最終日の総括質疑のときにお伺いいたします。次に、防災訓練経費について伺います。令和５年度の地域防災訓練の参加状況と課題、それを踏まえての令和６年度の計画についてお教えください。","respondent":"伊藤災害対策担当課長","answer":"基本的には、防災区民組織が主体となっておりますので、協力しながら実施を進めてまいりたいと考えています。","voiceIndex":42,"id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"新しい参加者を増やすために、新たにいろいろとご検討いただいていること、評価いたします。災害発生は、近隣地域の方々との助け合いが重要です。周知と参加のインセンティブについては、これも最終日の総括質疑の際にお伺いいたします。そして最後、Ｐａｒｋ－ＰＦＩの導入ですけれども、時間がもう少なくなりましたので、これはまたの機会でお伺いさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"３３７ページ、下水道管耐震化推進事業、３３１ページ、都市計画道路整備事業、３３９ページ、航空機騒音測定委託、３４２ページ、都市開発費について伺います。伺いますけれども、上下水道の継手の耐震化事業の計画の対象に、区民避難所等と同様、銭湯も入れていただくよう東京都に働きかけていただきたいと思います。働きかけていただけますでしょうか。ご答弁をお願いします。","respondent":"平原防災課長","answer":"今ご提案の銭湯については、重要なものであるというふうに思っておりますけれども、生活再建の中でどういうような順位づけをしていくか、重要なものを次にどういうふうに位置づけるかといったところは、最終的に一義的には東京都が決定していくものと考えていますけれども。","voiceIndex":46,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ検討を進めていただきたいというふうに思いますし、働きかけていただければと思っています。例えば、がん検診に回せば、乳がん検診、１,３８５万円で無料化できます。毎年２,４００万円のランニングコストを区民のために使いたいと、でも、そのためにはどうすればいいか。伺いますけれども、２,４００万円余の財源は、国なのか、都なのか、区なのか、その財源について伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"航空機騒音測定委託の費用ですが、国も、東京都も、独自に航空機騒音測定を行っていますが、区としてもしっかり測定をして区民に提示するということで、これは区の単費で行っているものです。","voiceIndex":48,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ、この羽田新ルートを止めましょう。その単費を本当に区民のために使えるわけです。２,４００万円余ですから、これはぜひ区長、まずは、止めるためには区長が国に中止を求める。先頭に立つということが、他区との連携が必要だという意見もありますけれども、何といっても品川区長なのです。ぜひ中止を求めていただきたいのですが、お願いします。","respondent":"鈴木都市計画課長","answer":"要望の内容につきましては、区民負担軽減につながる取組の早期の提示と実施を強く申し入れ、国からは、大臣から直接、重く受け止めると、しっかり検討していきたいという回答をいただいたところです。","voiceIndex":50,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ区長自らが国に中止を正面から求めることを強く要望して、次の質問に移ります。都市計画道路に関わって、第五次優先整備路線について伺います。伺いますけれども、この第四次優先整備路線で選定された区内の都市計画道路はどこだったでしょうか。それぞれの進捗についても伺います。それと、区としては、今度の第五次計画で、どの路線、どの道路の整備を希望する考えなのでしょうか、伺います。","respondent":"鈴木都市計画課長","answer":"都施工の１路線については、補助２６号線の目黒区境から武蔵小山駅の辺りと、それから、区施工の部分については、八ツ山通りの補助１６２号線、補助１６３号線、それから、西大井駅近傍の補助２０５号線というところでございまして、今の進捗状況ですが、事業着手に向けて。","voiceIndex":52,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"３つの街区でそれぞれ３つの準備組合が立ち上がっています。私は、ある街区の権利者からお話を伺いました。それで、入らないと情報をくれないと言ったら、入ってしまうではないですか。それと、品川区として、当該準備組合でこのようなことが行われているのですから、このような対応をするなと厳重申入れをすることが必要だと思うのですけれども、そのことを求めますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"準備組合等に対しては、やはりなかなか入りづらいという方もいらっしゃる、そういうことも把握しております。ですので、区といたしましては、そうした組織に対して、情報の差がないように、丁寧な対応をしていただきたいというところは求めているところです。","voiceIndex":54,"id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"これ、第一種市街地再開発を進めるための組織なのです。しかも、入ったら、そのパーセンテージが高まった、「もう都市計画手続に入ります」と言って、どんどん半年間で都市計画決定にいくわけではないですか。それはおかしいと思うので、改めて伺いますけれども、これ、地権者にとっては生活、財産、未来を左右する計画なのです。それをやるべきだと思いますけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"準備組合ですが、準備組合が組織される際は、地区内の方が、再開発を踏まえたまちづくりをどのように捉えているのか、前向きに捉えているかどうか、そういったところは、協議会の事務局を務めているところに、区としては把握をして、一定程度の割合があると確認した上で。","voiceIndex":56,"id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは、３３１ページ、道路改良費、３６３ページ、防災普及教育費、３３５ページ、水辺利活用事業についてお伺いいたします。なので、例えば、従来の工事開始前の１時間、終わりの時間を１時間ずらしていって、何とか８時から１０時の２時間を分散させて、通勤とか仕事の支障にならないような工事の工夫、取組をぜひ行っていただきたいと思うのですけれども、区の見解はいかがでしょうか。","respondent":"森道路課長","answer":"ゼームス坂の例を出していただきましたけれども、道路工事におきましては、周辺の歩行者の方の安全を第一に考えながら、迂回ルートといいましょうか、そういったものも含めて実施をしています。","voiceIndex":59,"id":"exchange-027"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひよろしくお願い申し上げます。続いて、防災普及教育費、マンション防災についてお伺いいたします。エレベーター用防災チェアの配布なのですけれども、これは希望されるマンションということを伺ったのですけれども、そのマンションに対しての周知方法、例えば、マンション管理組合に対して順次通知をされていくのか、周知方法についてお知らせください。","respondent":"平原防災課長","answer":"令和６年度に予定しておりますエレベーター用防災チェアの配布事業についてですけれども、次年度、品川区ではマンション防災用のハンドブックにつきましても全面改定する予定で今進めております。","voiceIndex":61,"id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"ということで、品川区がマンションと町会のつなぎ役を果たして防災訓練をやっていただくということはいかがでしょうか。そうした課題がある中、この都の事業をいいきっかけとして、防災訓練に新しい人を集めるということにもつながりますので、そうした東京都の東京とどまるマンション普及促進事業のマンションと町会の防災訓練のつなぎ役を区が行っていくということについて、いかがお考えでしょうか。","respondent":"平原防災課長","answer":"災害時に地域とのつながりがどのような形になるのか、そういったところをよく見える形にして、地域とつながるべき必要性を示しながら、東京とどまるマンション普及促進事業、今回、東京都がかなり拡充するということも聞いてありますので。","voiceIndex":63,"id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"ただ、町会とマンションとの防災訓練は、今、防災ハンドブック等々でお示しいただいて、その中でマンションが自主的に判断して、決定をしていくということなのかと思うのですけれども、かなり町会とマンションとの連絡というか、意思の疎通は難しいことがあると思いますので、その点、区に相談がありましたら、ぜひアドバイスなどをしていただけたらいいなと思うのですけれども。","respondent":"平原防災課長","answer":"私ども防災課には、マンション防災アドバイザーがおりますし、それ以外の職員も、町会とマンションのつながりというものは非常に重視していますので、何かお困りのことがありましたら、何なりとご相談いただければというふうに思ってあります。","voiceIndex":65,"id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"一般質問等々で、私およびほかの議員も、東八潮、その近接の東京国際クルーズターミナルとの連携ということを提言されております。それで、まちづくりマスタープラン、１５８ページに記載をしていただきましたけれども、そこで、東八潮の有効な利活用方策についての検討というものが、まちづくりマスタープラン、１５８ページに書いてあるのですけれども、現在、この状況はどうなっておりますでしょうか。","respondent":"鈴木都市計画課長","answer":"マスタープラン、東八潮の有効な活用方針ということで、東八潮地区につきましては、現在、都立潮風公園ですとか、船の科学館があります。","voiceIndex":67,"id":"exchange-031"},{"speaker":"せらく委員","kind":"質問・要望","question":"反対意見も１０件ほどありますが、お子様がいる家庭では、年齢によってなど、家庭の状況によって意見も様々であり、時間帯の感覚やボールの音を感じやすい方もいらっしゃると思いますので、子どもたちが伸び伸びと遊ぶことと、近隣住民の安心感、バランスをとるような取組でしたり、公園遊びが気になる住民にとっても、公園の利用に対する理解を得るための工夫が求められています。","respondent":"高梨公園課長","answer":"一方で、キャッチボール場の中での硬いボールを使ってのボール遊び、キャッチボール等についての苦情、フェンスにボールを当てて音がうるさいであるとか、小さいお子様が遊んでいる中で、大きな子どもたちがサッカーボールで。","voiceIndex":71,"id":"exchange-032"},{"speaker":"せらく委員","kind":"確認","question":"今後なのですけれども、苦情などが入った際には、すぐに追加看板の設置ではなくというふうな対応をしていくというふうに、議事録などでも確認をさせていただいたのですけれども、今既に設置されているところは、個別にご相談だとか、そういったことをさせていただけるのでしょうか。","respondent":"高梨公園課長","answer":"公園によって様々なケースがありますので、その公園に合わせて、これからよりよい看板の在り方については考えてまいりたいというふうに感じてあります。","voiceIndex":73,"id":"exchange-033"},{"speaker":"せらく委員","kind":"質問・要望","question":"さきに挙げた意見の中でもありました運動施設の一般開放についてですけれども、オンラインで確認できるようにしてほしいという以外にも、今は一般開放されていない天王洲公園も、予約のない時間に一般開放してほしいというようなご要望がありました。一般開放している運動施設と、していないところでは、どのような違いがありますでしょうか。","respondent":"高梨公園課長","answer":"予約が多く埋まっているような施設については、やはり一般開放できる時間が少ないということで、現在、一般開放はしていないところですが、この間、しながわ区民公園であるとか、子供の森公園等。","voiceIndex":75,"id":"exchange-034"},{"speaker":"せらく委員","kind":"確認","question":"予約の状況、利用の状況を見ながら、よろしくお願いいたします。開放情報をオンラインで確認という部分なのですけれども、私もよく利用するしながわ中央公園の多目的広場が、Ｘで一般開放情報を上げているのをたまに確認しています。ほかの施設でも発信をしていただいたり、各施設の情報を一覧でシームレスに見ることができたら、利用者は助かると思うのですけれども、この２点についてお願いします。","respondent":"高梨公園課長","answer":"拡大をしていますその他の野球場等の一般開放の状況についても、ほかの会社になるのですけれども、管理している会社と、現在、公表の仕方について検討を進めているところですので、今。","voiceIndex":77,"id":"exchange-035"},{"speaker":"せらく委員","kind":"提案","question":"区内は広々とした土地がない中で、限られた場所、公園の有効な活用については、これまでご意見をくださった皆様のご要望だと思いますので、引き続きよろしくお願いいたします。活動には報酬が出るものの、品川区として、活動の応援として、団員の皆様へインフルエンザの予防接種の費用を助成するなど、感染症対策を提案しますが、いかがでしょうか。こちらはいかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"委員にお話しいただきましたとおり、消防団の皆様におかれましては、日頃から地域の防災リーダーとしてご活躍いただき、また、災害時には率先して災害活動に対応していただいている心強い存在であると我々も認識しております。","voiceIndex":79,"id":"exchange-036"},{"speaker":"横山委員","kind":"確認","question":"私からは、３２９ページ、樹木健全度診断事業、３３９ページ、空港環境経費、３５１ページ、しながわ水族館運営費、３６１ページ、防災対策総合推進費についてお伺いいたします。１点目に、しながわ水族館運営費についてお伺いいたします。２点目に、空港環境経費についてお伺いいたします。はこちらの内容について、簡単にご説明をお願いいたします。","respondent":"高梨公園課長、鈴木都市計画課長","answer":"リニューアル後のＢＣＰについてですが、基本的には、現在のしながわ水族館のＢＣＰの対策を基本といたしまして、さらに、今回の震災等を受けまして、バージョンアップといいますか、拡大した内容について、現在。環境影響に関する予算ですが、基本的には、空港環境経費です、騒音に関する委託経費と、その他の事務費です。","voiceIndex":83,"id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"もし災害時の緊急避難措置として、区民への影響が想定される場合の運用などが、Ａ２－ＢＣＰなどに計画されていくのであれば、近隣区としてリアルタイムで把握していただきたいというふうに要望いたしますが、今後、国土交通省、大田区、東京都、他の近隣区などと、どのように情報共有や連携をしていくのか、区のお考えをお聞かせください。３点目に、防災対策総合推進費についてお伺いいたします。","respondent":"平原防災課長","answer":"関係機関との連携ですけれども、令和４年度に実施いたしました東京都との合同総合防災訓練の中で、実際に遺体安置所を開設してみる、そのときの手順を確認するというような訓練も行いましたし、私ども防災課と警察、消防、自衛隊の皆様との間で。","voiceIndex":86,"id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。安心いたしました。ぜひこれからも訓練等を進めていただきたいと考えています。４点目に、樹木健全度診断事業についてお伺いいたします。診断の内容と、対象の樹木の範囲とスケジュールを教えていただきたいと思います。区内の状況を教えてください。","respondent":"森道路課長","answer":"Ｃ判定として伐採をする必要があれば、都度、対応していくということにしております。","voiceIndex":88,"id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"最近、急に危険木が増えた理由について、世田谷区の事例なのですけれども、近年の猛暑で樹勢が弱まっていたところに病虫害が予想以上に進行したためというふうに指摘する声があるとのことですが、区内における樹木のナラ枯れの発生状況が分かりましたら、教えてください。","respondent":"森道路課長","answer":"ナラ枯れにつきましては、発生しておりません。区内で対象樹木が８本しかございませんので、引き続き経過観察を進めてまいります。","voiceIndex":90,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"樹木診断の結果や点検の結果で被害が確認された場合は、しっかり対処していただきたいと思いますので、お願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-041"},{"speaker":"えのした委員","kind":"質問・要望","question":"区内全域にも区独自の感震ブレーカー設置助成も拡大されますが、昨年の一般質問でも、防災対策について様々要望させていただき、まずは、先ほど澤田委員からもお話がありましたが、品川区もリニューアルをする「しながわ防災ハンドブック」の全戸配布の実施について、また、予算の目玉でもある約４０万人の全区民に携帯トイレを１人２０個ずつ、これを一緒に無料配布、非常に歓迎しております。","respondent":"平原防災課長","answer":"今回「しながわ防災ハンドブック」と、携帯トイレ全戸配布を併せて行わせていただきたいと思いますが、こちらについての詳細は、これから契約等で詰めていくことになると思いますけれども、送り方につきましては、例えば家族数に応じて郵送であったりとか、宅配を活用とか。","voiceIndex":94,"id":"exchange-042"},{"speaker":"えのした委員","kind":"質問","question":"これからということですが、また、先ほど、マンション防災、筒井委員からもお話がございました。こちらもパンフレットの予算に入っておりますが、全面改訂とご答弁がございました。これ、ハンドブックとは別のものになると理解しておりますが、内容も含めてお知らせ願えますでしょうか。","respondent":"平原防災課長","answer":"今ご質問にございましたとおり、マンションの防災啓発資料につきましては別で作成するものでございまして、マンションの住民向けと、マンションの管理組合向けの２種類を作成する予定です。","voiceIndex":96,"id":"exchange-043"},{"speaker":"えのした委員","kind":"質問","question":"２種類ある、初めて知りました。先日も防災フェアに伺わせていただきましたが、本当に入り口から長蛇の列で、特にお子様連れのご家族が多く見受けられ、消防車に試乗できるなど、楽しみながら防災を学べるよい事業だと評価しております。このように区民の方が多く来てくださるイベントでも、防災ハンドブックや携帯トイレを展示することによって周知啓発が広がると考えますが、区のご見解をお知らせください。","respondent":"平原防災課長","answer":"区民の方への自助を促していくといったところですけれども、まずは、区では、しっかりと普及啓発を進めてまいるところで考えてありますが、そのような中で、どのような効果的な手段があるかといったところにつきましては、他自治体の事例なども見つつ。","voiceIndex":98,"id":"exchange-044"},{"speaker":"えのした委員","kind":"質問","question":"本当に実感していただくことは重要だと考えています。先月、地元の小山小学校での避難所訓練に参加してきましたが、防災トイレ、自動排泄処理できるラップポンというのですか、拝見してまいりました。最新式で、いいトイレだとは思うのですが、こちらを採用された理由などがありましたら、お知らせください。","respondent":"羽鳥防災体制整備担当課長","answer":"地域の方から、設置や使用方法が難しいというお声もいただいております。それに対しまして、区といたしましては、分かりやすい手順書をつけて、トイレと一緒に備蓄しているほか、メーカーのほうにも利用者の声ということで改善を要求しています。","voiceIndex":100,"id":"exchange-045"},{"speaker":"えのした委員","kind":"質問・要望","question":"特徴もよく理解いたしました。区民の方が分かりやすくなるように取り組んでいただければと思います。ラップポン以外にも、防災トイレはありますが、例えば、大震災が起きた日から１週間ですとか、関心を示しやすい時期に常設展示などして周知啓発、あと、これからも発災時のトイレ問題は、より一層の取組を考えていただけるよう要望いたします。こちらは何棟分の予定になりますでしょうか。","respondent":"平原防災課長","answer":"令和６年度から実施予定ですマンションへの防災チェアの提供事業ですけれども、区内にあります３階建て以上かつ１５戸以上の住戸を有するマンションを対象といたしまして、全体で３,２００棟を対象として、こちらを３年計画で実施しようというふうに考えてあります。","voiceIndex":102,"id":"exchange-046"},{"speaker":"えのした委員","kind":"質問・要望","question":"３,２００棟、理解いたしました。区内に住む約７割の方がマンションで暮らしております。より一層のマンション防災の拡充を要望いたします。続けて、中学生向け防災プロジェクトについてお伺いいたします。どのように進めていくのか、具体的な内容をお知らせください。","respondent":"平原防災課長","answer":"このプロジェクトにおきましては、企業の協賛を得て、中学生向けの防災教材を作成し、それを３か年にわたって使っていただくということで、発災時に自宅や学校周辺で主体的な避難行動をとることができ、また。","voiceIndex":104,"id":"exchange-047"},{"speaker":"えのした委員","kind":"質問・要望","question":"企業と連携してということで、こちらは一般質問でも要望させていただきましたが、地域の方からのお声もすごく多かったです。中学生は特に平日の日中に発災した場合には、地域の力になると考えて歓迎いたします。続いて、備蓄品についてお伺いいたします。そして、こちらは、品川区としては、都市型災害としての備蓄品の見直しなどはありますでしょうか。区のご見解をお知らせください。","respondent":"羽鳥防災体制整備担当課長","answer":"断水時でもすぐに使えるようなウエットシートを備蓄しています。今後、女性やお子様、高齢者の方、ペット同行避難など、多様な避難に対応して、皆様が安全に安心して避難生活を送ることができるよう、必要な物資を備蓄していく必要があるかと考えております。","voiceIndex":106,"id":"exchange-048"},{"speaker":"えのした委員","kind":"確認","question":"備蓄品の見直しの確認がとれました。続いて、能登半島地震、こちらの被災地では、通信状況が不安定となり、災害派遣医療チーム（ＤＭＡＴ）からは、スターリンクを持っていき効果的であったとの報告も上がっております。避難所となる学校の体育館、こういったところにも持ち運びができるスターリンクは、情報収集する上で大変役に立つと考えますが、区のご見解をお知らせください。","respondent":"平原防災課長","answer":"こちらにつきましては、都との連絡という形ですけれども、そのような中で基地局に依存しないために、停電による通信途絶がないという特性がどのように活用できるのか。都から提供いただきました機材をしっかりと検証してまいりたいというふうに考えてあります。","voiceIndex":108,"id":"exchange-049"},{"speaker":"えのした委員","kind":"意見","question":"最後、時間が少なくなりましたが、避難行動要支援者、こちらは先日も地区の避難誘導ワークショップを受講してまいりました。出席者は、まだかなり理解されていないなという実感がありますが、この予算、取組の内容をお知らせください。","respondent":"平原防災課長","answer":"こちらにつきましては、特に福祉との連携についての強化をしています。","voiceIndex":110,"id":"exchange-050"},{"speaker":"新妻委員","kind":"質問・要望","question":"公園から伺います。地元の町会からも、長年改修の要望の声が品川区に届けられていたと伺っております。公園をつくっていく際には、地元の声を十分に聞いていただけると思いますけれども、特に防災に特化したかまどベンチの設置や、トイレの設置もできるのではないかというご要望もあるようですので、区の見解を伺います。グリーンインフラと記載があります。このスケジュールを伺いたいと思います。","respondent":"高梨公園課長","answer":"東大井公園につきましてですが、最初にスケジュールです。来年度、基本設計と実施設計、要するに、１年間かけて設計作業を行い、令和７年度から工事にかかるということで、現在のところ、令和７年度から８年度にかけて工事を行うというようなことで考えてあります。","voiceIndex":113,"id":"exchange-051"},{"speaker":"新妻委員","kind":"質問・要望","question":"浜川北公園に関しては、マンホールトイレを設置ということが具体的になっていると確認いたしました。そしてまた、公園の設置に当たっては、住宅街にあり、また、インクルーシブ公園というふうに記されておりますので、多くの方が来られるということでは、自転車置場の設置とか、そこら辺の配慮もしていただきたいと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"駐輪場につきましては、大井坂下公園に大分多くの駐輪があったという事例もありますので、東大井公園の立地等を鑑みて、自転車置場についても設計の中でしっかりと考えてまいりたいというふうに考えてあります。","voiceIndex":115,"id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"防災関係についてお伺いいたします。現在、品川区では、ＰＤＦのデータとしては区のホームページに載っていると思いますけれども、今後、多くの方がいろいろな場面で活用できますように、デジタル化も要望させていただきたいと思います。そして、区の公式ＬＩＮＥにも日頃の防災というものがありますが、そこにもぜひ掲載をしていただくこともご検討いただきたいと思いますが、見解を伺います。","respondent":"平原防災課長","answer":"デジタル化につきましては、これは当然進めさせていただければというふうに考えてありますが、今、内容につきましては検討しておりますので、まだ詳細は固まっておりませんが、しっかりと対応させていただきたいと思います。","voiceIndex":117,"id":"exchange-053"},{"speaker":"新妻委員","kind":"質問","question":"先ほどのトイレの件ですけれども、携帯トイレを全戸配布するに当たっては、事前に区民の意識を啓発することが大事で、送るだけではなく、どういう意図で品川区が送るのかということをしっかりと分かっていただくことが必要となりますので、町会・自治会、またはＰＴＡやスポーツクラブの方々に、少し時間をいただいて事前説明をする場などもあってもいいのかなと思いますが、併せて見解を伺います。","respondent":"平原防災課長","answer":"続きまして、トイレの全戸配布等々についてですけれども、区の意図が明らかになるように、配布につきましても、防災ハンドブックと一緒、さらには、備蓄の考え方が分かるようにすると同時に、事前周知をさせていただきまして、委員ご指摘のとおり。","voiceIndex":119,"id":"exchange-054","title":"町会・自治会支援"},{"speaker":"おぎの委員","kind":"質問","question":"区民の安全を守るため、様々なことを想定した結果が、来年度の予算に反映されていることが伺えます。首都直下地震や、それに伴う火災で自宅避難ができなくなった場合、区内の避難所がいっぱいになってしまった場合の区民の避難先の１つとして検討してみてはどうでしょうかというだけでは、検討する情報が少な過ぎますので、今定例会が始まる前日に実際に行ってみました。約２時間４５分の道のりでした。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":122,"id":"exchange-055"},{"speaker":"おぎの委員","kind":"質問","question":"２０１１年の東日本大震災のときは、余震が続いて不安な思いをしていた町民が宴会場ホールに集まり、数日間、みんなで過ごした実績もあります。２か所目は、矢祭小学校の体育館です。間もなく築８年となる新しい校舎です。今までの区内の民間企業、住民同士の草の根交流の実績を踏まえ、ぜひこの縁を大切に、新しい防災相互協定先として検討してみることはいかがでしょうか。区の見解をお聞きします。","respondent":"平原防災課長","answer":"他自治体との相互援助に関する協定ですが、現在、東京都内の自治体を含めて９３自治体、都外の自治体でいくと３１自治体との間で締結していますが、こちらは相互応援ということもありますので。","voiceIndex":126,"id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ぜひ前向きに検討していただきますようお願いいたします。続きまして、３６１ページ、地区総合防災訓練についてお聞きします。プレス資料７３ページの町会・自治会との地域力向上へ他団体との協働に補助金が使えるということですが、こういったマンションと地域の方との大規模な防災訓練などにもこちらの補助金は使えるのでしょうか。","respondent":"平原防災課長","answer":"今ご紹介いただきました補助金につきましては、地域活動課所管ですので、具体的にどのようなものが対象になるかといったところまでの詳細は、私ども、承知しておりませんけれども、いずれにしましても、町会とマンション住民。","voiceIndex":128,"id":"exchange-057","title":"町会・自治会支援"},{"speaker":"ひがし委員","kind":"質問","question":"午後もよろしくお願いいたします。私からは、３３１ページ、点字ブロックを活用した音声による移動支援検討について、３４９ページ、立会川・勝島地区まちづくりについて、３６５ページ、災害時応急物資確保費と、３６７ページ、避難所管理費に関連して、女性視点での備蓄、避難所運営について質問いたします。区は、具体的にどのようなものを検討しているのでしょうか。","respondent":"森道路課長","answer":"もう１つは、ＱＲコードを点状ブロックに設置して、それをまた別になりますけれども、専用アプリで読み込むことによって、そこまでのルートを点状ブロックごとに案内してくれるというものです。","voiceIndex":132,"id":"exchange-058"},{"speaker":"ひがし委員","kind":"質問","question":"２種類検討しているということで、当事者の方からは、既に音声を使用した移動支援の機械もあるが値段が高いといった課題があるとのお話を聞いております。今回、品川区が検討しているものは、スマホがあれば、アプリを使用し無料で利用できるという認識でよろしいでしょうか。","respondent":"森道路課長","answer":"こちらにつきましては無料のアプリで、先ほど言いましたＱＲコードにつきましては、ｉＰｈｏｎｅのみの対応と、今のところそうなっておりますけれども、無料のアプリをダウンロードするだけで対応可能というふうに聞いております。","voiceIndex":134,"id":"exchange-059"},{"speaker":"ひがし委員","kind":"質問・要望","question":"この記事、１人で歩きたい、みんなが困っているときだからこそ、みんなの手をかけないように自分で移動したいのにというような言葉で始まります。今まで白杖を使って１人で歩行していたが、避難所では点字ブロックもなく、人に当たる可能性もあるため、白杖を振って歩けない。ぜひ災害時にも活用できるといった視点も考えながら、この事業を進めていくよう求めますが、区の見解をお聞かせください。","respondent":"森道路課長","answer":"こちらは、先ほど申し上げました幾つかの黒い輪を設置するというような技術に関しましては、メーカーも、例えば避難誘導みたいなことも考えたいというお話をされていました。","voiceIndex":136,"id":"exchange-060"},{"speaker":"ひがし委員","kind":"質問・要望","question":"スマホを利用すると無料で利用できるということは、先ほど確認させていただきました。そこで、障害者団体の方にもお話を伺いました。ほかにも白杖の電子化の研究も進んでいると思いますが、今回、品川区がこの音声アプリに取り組むことにした理由、また、区としてアプリを選択するかについて、今後どのような段階を踏んで進めていくのかについても伺います。","respondent":"森道路課長","answer":"今のところ、案内については障害者支援課、整備については道路課というふうな役割分担でおりますけれども、スマホの研修につきましても、福祉部のほうでも高齢者に対するスマホの研修をやられているので、それにつきましても考えていきたいというふうに思います。","voiceIndex":138,"id":"exchange-061"},{"speaker":"ひがし委員","kind":"確認","question":"最後に１点だけ確認をさせてください。視覚障害者団体からは、このようなアプリを用いた誘導システムが整備されることで、従来の点字ブロック、また、音響式信号機の整備が立ち後れてしまうのではないかというような不安の声も届いています。この点について、区としてどのように考えているのか、最後にお聞かせください。","respondent":"森道路課長","answer":"こちらの点字ブロックの音声による誘導につきましては、音響式の信号機とは別の形で、区のほうでしっかりと進めていきたい、検証していきたいというふうに考えておりますので、それぞれの事業の中で考えていければと思っています。","voiceIndex":140,"id":"exchange-062"},{"speaker":"ひがし委員","kind":"質問","question":"様々検討いただけるということで、うれしく思っております。次に、立会川・勝島地区まちづくりについて伺います。区民への説明会では、勝島人道橋について、ルートが３か所示され、真ん中のルート２の位置に決定したとのことです。今回、設置に当たって、安全性についてどのように考え決定したのか、また、真ん中、このルート２にした理由、人道橋の目的について伺います。","respondent":"森道路課長","answer":"施工性であったり、維持管理の特性であったりというところで、２回、地域の方に説明会をさせていただきまして、都市計画の決定を行ったものです。安全対策につきましては、令和５年７月の説明会の中でも、地域の方から安全性に対する意見が出ました。","voiceIndex":142,"id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"私も区民の方々からお話を伺いまして、先ほどご答弁ありましたように、佐川急便の事務所が対岸にあるということで、災害時の対応、防犯の観点から、安全性を確保してほしいというようなご要望をいただきました。現在の対応状況については確認させていただきましたので、今後、安全性の観点を含め、区民の方々の声を聞く機会があるのかという点について確認をさせてください。","respondent":"森道路課長","answer":"そういったお話をしていく中で、今、委員からお話がありました安全性だとか、防災性だとか、そういった部分の意見を聞いて反映していければというふうに考えています。","voiceIndex":144,"id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ区民の方々、不安の声があるということを受け止めていただきながら、この声に対して丁寧に説明をしていただくように求めて、次の質問に移ります。次は、女性視点での備蓄、避難所運営について伺います。このような声を受けて、品川区として、女性視点での備蓄や避難所運営について、どのように考えているのか、まずはお聞かせください。","respondent":"平原防災課長、羽鳥防災体制整備担当課長","answer":"現時点ですけれども、避難所運営といいましょうか、避難所内の整備ですけれども、５２か所全ての区民避難所におきまして、女性の更衣室、授乳室など、女性に配慮したスペースを用意させていただいているような状況です。先ほども答弁させていただきましたけれど、女性視点での備蓄、大変重要なものと考えております。来年度以降、おりものシート、そういったものを備蓄してまいります。今後とも必要なものに関して検討してまいりたいと思います。","voiceIndex":146,"id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問","question":"おりものシートは新しく取り入れてくださるということで、大変うれしく思っておりますが、それだけでは足りないなというふうに、午前中の澤田委員のお話を聞いていても、私自身、思いました。今回、女性視点での備蓄、避難所の見直しに向けて、女性視点の取り入れ方は、どのように進めていく予定なのかを伺います。区として課題があれば、併せてお聞かせください。","respondent":"平原防災課長","answer":"続きまして、課題ですけれども、先ほど、女性の更衣室等の整備はできたということなのですけれども、いわゆるソフト対策といいましょうか、本当の運営のところで、備蓄物資を充実しても、その配り方、捨て方、活用方法。","voiceIndex":149,"id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問・要望","question":"現在、８名の女性職員を筆頭にして、中心で考えてくださっているということでした。その女性の職員の方々を筆頭に考えてくださるということですが、ぜひその方々を中心にしながらも、区民の声を拾い、女性視点での防災避難所に対する意見を取り入れていくよう求めます。そのような方々にアンケートをとりながら、備蓄、そして避難所運営についても考えていく必要があるかと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"女性視点でのお声のとり方ですけれども、今、委員ご指摘のとおり、様々なところから広くとっていく必要があるというふうに考えてありますので、正に様々、私ども行っております各種の訓練、あるいは、地域の方々とのお話合い、それだけではなく。","voiceIndex":151,"id":"exchange-067"},{"speaker":"中塚委員","kind":"質問・要望","question":"３６１ページ、防災対策総合推進費より、引き続き、キッチンカーについて伺いたいと思います。災害時の活用について、飲食業界との連携を進めていきたいと答弁がありました。私は、ぜひ災害協定を目指していただきたいと思いますが、いかがでしょうか。併せて、災害時について、キッチンカーにどのような役割を期待しているのか、区の基本的な考えを伺いたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"こういったところを解決するために、発災直後はどうしても区が備蓄している非常食、そういったもので対応していただくようになりますけれど、避難生活が長期化したときには、そういった温かい食事の提供が重要になってまいりますので。","voiceIndex":155,"id":"exchange-068"},{"speaker":"中塚委員","kind":"提案","question":"被災地からは様々声は上がっているけれども、なかなかその仕組みづくりがうまくいかないということをよく伺います。先ほど、協定などの話もありましたけれども、ぜひ事前に災害協定も結んでいただいて、被災地への支援、品川区が被災地となったときの対応など、支援策の具体化を進めていただきたいと思いますが、いかがでしょうか。","respondent":"羽鳥防災体制整備担当課長","answer":"今後とも、民間の力を活用できるように、協定も含めて検討してまいりたいと思います。","voiceIndex":157,"id":"exchange-069"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ様々な指針が示されながら具体化できていない分野でもありますので、災害協定などを結びながら進めていただきたいと思います。そこで、区立公園におけるキッチンカーの営業についても伺いたいと思います。そこで得た様々な連携を災害時に発揮していただく、こうした仕組みづくりができないものかと思いますけれども、いかがでしょうか。","respondent":"高梨公園課長","answer":"災害時におけるキッチンカーとの連携、公園での日常営業といったことにつきましては、防災部門とも連携の上、今後の可能性について検討してまいりたいと考えています。","voiceIndex":159,"id":"exchange-070"},{"speaker":"中塚委員","kind":"質問・要望","question":"キッチンカーの業界も今大きく広がっており、キッチンカー自身も災害時に自ら社会的な役割として発揮できるものがないかというふうに動き始めておりますので、ぜひ協力関係を築いていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-071"},{"speaker":"せお委員","kind":"提案","question":"よろしくお願いします。私からは、３４９ページ、子どもたちのアイデアを活かした公園づくり、３５１ページ、おもてなしトイレ整備、３２９ページ、しなみちレポートについてお伺いします。この３公園は、先ほどのワークショップのときのアイデアブックを活用して整備すると理解していますが、それ以外のところでは、どういった形で子どもたちや地域の皆さんのご意見、ご要望を反映していくのでしょうか。","respondent":"高梨公園課長","answer":"予算書に記載しています３公園についてですが、西五反田公園、こちらはもう現在、工事中ですが、こちらは子どもたちのアイデアを活かした公園づくりの中のワークショップでいただいたアイデアブックの中から、目玉焼きのトランポリンということで、設置を進めているところです。","voiceIndex":163,"id":"exchange-072"},{"speaker":"せお委員","kind":"質問・要望","question":"しなみちレポートも、以前からよい取組だなと思って注目していて、さらに充実するために、いつも苦情が多い公園のほうにも対象を広げることを要望させていただいたり、町会・自治会単位で使用することができると広がっていくのではないか、町会・自治会の負担を増やすわけではなく、できる人が取り組んでいただければ、もっと広がっていくのかなということで。","respondent":"高梨公園課長","answer":"令和４年度から、公園課については、公園の通報システムを開始いたしまして、令和２年度に比べて令和５年度のほうが、やはり通報の数自体は増えてはきているものの、道路と比べると絶対数がまだまだ少ないというところが課題だというふうに考えてあります。","voiceIndex":167,"id":"exchange-073","title":"町会・自治会支援"},{"speaker":"せお委員","kind":"質問・要望","question":"同じ会派のえのした委員も、町会・自治会で、消火器を点検する業務というか、そういうものもあるということで、そういうものをしなみちレポートとかで、写真を撮って、有効期限とかもそうですし、そういったことができたらいいなというお話もあったりするので、そういった町会・自治会単位で、負担のないように、負担が減らせるようにするための何かそういった利用も考えられたらなと思って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-074","title":"町会・自治会支援"},{"speaker":"つる委員","kind":"質問","question":"３３１ページ、路面等改良費、３２７ページ、道路維持費、３２５ページ、駅周辺等放置自転車対策事業、３５２ページ、建築費、３４７ページ、公園・児童遊園費について伺っていきたいと思います。これに関連して、ここは今、かむろ坂でありますけれども、その他の地域への展開でありますとか整備状況、これを教えていただくことと、併せて、街路樹の中で、桜の本数、現在において何本あるか教えてください。","respondent":"森道路課長","answer":"整備できる箇所も幾つか限られますけれども、新工法も適用しています。今後とも、そういったところがあれば、しっかりと適用を考えていきたいというふうに思っております。桜につきましては、３,８６１本のうち１,４６７本、３８％です。","voiceIndex":171,"id":"exchange-075"},{"speaker":"つる委員","kind":"質問・要望","question":"桜の本数については、これは毎度確認していますが、品川区の利便性の向上の１つである駅から桜が見える環境を、１本でも多くつくっていただきたい、これは引き続きお願いしておきたいと思います。同じページに関連して、グリーンインフラでありますが、先ほど、新妻委員からも確認が若干ありました。","respondent":"高梨公園課長","answer":"今後、こういったグリーンインフラについて、区民に広く知っていただくように、広報に力を入れてまいりたいと考えています。","voiceIndex":173,"id":"exchange-076"},{"speaker":"つる委員","kind":"質問・要望","question":"このグリーンインフラの取組については、グリーンインフラ大賞が設けられているかと思いますので、その受賞等も目指して品川区の施策展開をやっていただきたいと思うのですが、茨城県の守谷市では、市の施設にグリーンカーテン、ビールのホップを栽培して地ビールとして販売をして、その売上げを財源として展開しているということとか、同じく学校の敷地内、壁面に、２万本ですか、植えて。","respondent":"森道路課長","answer":"マンホールカードにつきましては、今ある２つの種類を追加で印刷していく予定です。","voiceIndex":175,"id":"exchange-077"},{"speaker":"つる委員","kind":"質問","question":"１６のキャラクターが戦力外通告を受けたと。サンリオとの契約自体は文化観光課と認識しておりますけれども、この辺のデザインの考え方、もう一方、併せて伺ってしまうと、３月３１日で１６のキャラクターが最後です。もう１つ、戦力外になってしまったものがあるのです。これが「わ！この辺りについての新たなキャッチを使ったときの考え方とか、新たなデザイン化とか、カードの作成について教えてください。","respondent":"森道路課長","answer":"しながわ」というふうな形で書いているところですけれども、今後、広報広聴課のほうで様々なキャッチ等を考えられると思いますけれども、そういったものに、例えば、更新のタイミングで変更していく、あるいは、数も少ないので。","voiceIndex":177,"id":"exchange-078"},{"speaker":"つる委員","kind":"質問・要望","question":"分かりました。ぜひ権利関係だとか、いろいろな観点で確認いただきたいというところと、「わ！一部の自治体では、限定でありますけれども、そういった取組をやっているところがありますので、いろいろな展開をぜひ引き続きご検討いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":179,"id":"exchange-079","title":"町会・自治会支援"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お願いします。私からは、３４９ページのＰａｒｋ－ＰＦＩの導入と、３５１ページ、しながわ水族館リニューアル経費、３４９ページの勝島人道橋工事、いければいきます。お願いします。ＰＦＩですけれども、民間企業に委託するということなのですけれども、そのほとんどが株式会社なのかと思います。会社法上、株式会社の所有権は株主にあるという認識でよろしいでしょうか。","respondent":"高梨公園課長","answer":"Ｐａｒｋ－ＰＦＩの制度で、公園の中で収益施設を出していただく会社につきましては、区と所有権関係を結ぶわけではございませんので、引き続き、その会社の所有、株主の所有ということで間違いありません。","voiceIndex":181,"id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。今、ヨーロッパを中心に、世界的には、ＰＦＩというよりは、どちらかというと、再民営化とか、公共化が進んでいるという個人的な理解なのですけれども、その辺の受け止めはいかがでしょうか。","respondent":"高梨公園課長","answer":"国内においても、やはり民間としっかりと連携して、公園については、区民の方々に、より楽しんでいただけるものを、行政だけではなくて、民間の力を借りながら、しっかりと連携して、よりよいものをつくっていこう。","voiceIndex":183,"id":"exchange-081","title":"町会・自治会支援"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"世界的な主流と少し逆行して、日本は、どちらかというと、ＰＦＩに傾いているというところで、例えば、２０１８年のイギリスおよびＥＵの会計検査院は、ＰＦＩでの入札価格は４０％割高で、コスト削減効果もなく、透明性も悪化、問題点が改善するまでＰＰＰを広い分野で集中的に使うべきではない。そういったことをぜひ考慮していただきたいのですけれども、今、どのような進め方をされていますでしょうか。","respondent":"高梨公園課長","answer":"今、委員からもご提案ありましたとおり、やはり地域の皆様のご同意、同じ方向を向いてつくっていかないと、公園の中で皆さんに楽しんでいただく施設はできないというふうに考えてあります。","voiceIndex":185,"id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひお願いします。１点付け加えると、つくられる施設、これからですけれども、例えば、バリアフリー化がされているかとか、赤ちゃん連れでも利用できるかとか、そういった観点もしっかりと入れ込んでいただければというふうに思いますので、そういった視点もお願いいたします。これは要望です。次に、水族館のほうに行きます。理由をお聞かせいただければと思います。","respondent":"高梨公園課長","answer":"それと３つ目は、昨今のイルカをはじめとした海洋哺乳類にまつわる情勢の変化といったところの３点を挙げさせていただいているところです。","voiceIndex":187,"id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"提案","question":"分かりました。例えば流しソーメンみたいなものをバーッと広げて、そこでカワウソが水遊びをする流しカワウソということをやって、市川市動植物園なのですけれども、そういったものがありまして、非常に活動的なので、ショーとかではなく、見ていて楽しめる展示になると思うのですけれども、そういった提案はいかがでしょうか。","respondent":"高梨公園課長","answer":"ご提案ありましたカワウソについてですが、現在も２頭のカワウソがしながわ水族館におりまして、餌やり体験等で人気を博していますので、ご提案いただいた内容等についても、また設計の中で考えてまいりたいと考えています。","voiceIndex":189,"id":"exchange-084","title":"町会・自治会支援"},{"speaker":"やなぎさわ委員","kind":"提案","question":"２匹ぐらいだったらどこでもいると思うのですけれども、それをたくさん入れて、とにかく動いてもらうというようなところで、私自身が、実はカワウソの愛護活動をしておりまして、カワウソは、今、輸入禁止とかになっているのですけれども、唯一インドネシアの政府から許可を得て、正規に輸入をして、そこで展示したり繁殖したりしている民間の業者と私も一緒に連携をしておりまして。","respondent":"高梨公園課長","answer":"様々な声を聞きながら頑張って検討してまいりたいと思います。","voiceIndex":191,"id":"exchange-085"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３４３ページの市街地整備事業費に関わって再開発について、３４９ページ、（仮称）勝島人道橋整備工事の中止を求めて質問します。再開発です。安藤委員の質疑の続きですが、準備組合に入っていなくても、関係権利者には情報提供すべきだと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"そうした方につきましては、区のほうにお問合せいただけましたら、組合と調整等はあるかと思いますけれども、そういった不安は取り除いていきたいと考えております。","voiceIndex":194,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"組合が判断するものというふうにおっしゃいますけれども、地権者がやはり情報を得られなければ、今後の自分の身の振りを考えることもできないということになりますので、区として組合に注意すべきだと思いますけれども、いかがでしょうか。これはやめさせるべきだと思いますが、いかがでしょうか。","respondent":"中道都市開発課長","answer":"準備組合に入らないと情報が手に入らないですが、準備組合は権利者に対して一般的な説明会も開催しています。ですので、情報が手に入らないということはないというふうな区の認識です。","voiceIndex":196,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"区はそういう認識かもしれませんが、組合は、そう言って加入を迫ってくるということですので、これはぜひやめさせるべきだと、これは求めておきたいと思いますし、その情報提供も組合が判断するものだと言いますが、任意の団体だということだと思いますけれども、その中で住民の暮らしが壊されるということになりますので、これは情報をしっかり提供していかなければならないというふうに思います。","respondent":"中道都市開発課長","answer":"住宅が壊される、住民が追い出されるといったことですけれども、市街地再開発事業は、地区内の権利者の方々が話し合って進めている事業になります。先日、武蔵小山でも、説明会、中間報告会等がございました。","voiceIndex":198,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、行われてきた地区ではどうかということで伺いたいのですけれども、１つの資料として、再開発本組合設立時の同意率を伺います。主な地区として、戸越五丁目１９番地区、大崎駅西口Ｆ南地区、区役所近くの大井一丁目南第１地区、国際自動車教習所跡の西品川一丁目地区の土地所有者、いれば区分所有者も、借地権者の各地権者数と、同意した人数、同意率を伺います。","respondent":"中道都市開発課長、大石まちづくり立体化担当課長","answer":"ですので、区民の方も、自分の今後の生活について、きちんと向き合って進めているものというような認識です。同意率ですが、大崎Ｆ南ですが、こちらは、土地所有者が１２名、借地権者が１５名です。戸越五丁目１９番地区についてお答えいたします。当該地域は、所有権者が１３名、借地権者が８名、同意者といたしましては、所有権者が１１名、借地権者が８名となっております。","voiceIndex":200,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問","question":"正確な数字は分かりませんけれども、１００％の同意率には至っていないということで、進めてほしくない人、反対者がいるという下でこの再開発が進められて、住民が追い出されているということだと思います。その下で、武蔵小山第２地区も予算化するのはなぜか、第１地区が予算化されていないのはなぜか、すべきではないと思いますけれども、いかがでしょうか。","respondent":"中道都市開発課長","answer":"小山三丁目第１地区につきましては、現在まだそのような補助金を支給するような状況になっていないと聞いていますので、それに対して対応しています。","voiceIndex":203,"id":"exchange-090"},{"speaker":"こしば委員","kind":"質問","question":"よろしくお願いします。私からは、３６７ページ、自衛官等募集事務費について、３４７ページ、ドッグラン設置検証についてお伺いいたします。一昨日、隣の中央公園にて防災フェアを見学してまいりました。今日は、土木費の中で、法定受託事務の自衛官募集事務についてお伺いいたします。区では、法定受託事務となっております募集事務、これをどのように活用されているのか、まず教えてください。","respondent":"伊藤災害対策担当課長","answer":"自衛官の広報、募集に関しましてのご質問でした。五反田にあります自衛官の募集案内所と連携をしてございまして、募集パンフレット等を受領しています。併せまして、予算としまして収入があります。","voiceIndex":206,"id":"exchange-091"},{"speaker":"こしば委員","kind":"質問","question":"庁舎の中でも広報のものとなるパンフレットを置かれているとお伺いいたしました。そういったものも通しまして、近年の区内在住者の自衛隊への入隊状況について、その推移について教えてください。","respondent":"伊藤災害対策担当課長","answer":"区内の自衛官の合格者、入隊者という内容ですが、遡りまして、令和３年につきましては１７名、令和４年につきましては１５名、今年が、今のところ５名と聞いておりますが、この人数については、また入隊、入校時に変わってくると読んです。","voiceIndex":208,"id":"exchange-092"},{"speaker":"こしば委員","kind":"質問","question":"法定受託事務の範囲内で自治体が取り組めることはあります。年間を通じて採用を行っています自衛官の候補生や、曹候補生、技術曹候補生、また、幹部候補生、キャリア採用など、採用ルートも多岐にわたるわけですが、例えば、先ほど、パンフレットの活用もおっしゃっておりましたが、区の施設や町会・自治会の掲示板も含めて、こういった案内を張り出していくということを検討してみてはいかがでしょうか。","respondent":"伊藤災害対策担当課長","answer":"今、委員からご指摘ありましたとおり、募集のタイミングで何かしらの打ち出しのようなものができればと考えてございまして、現在考えているものとしまして、デジタルサイネージが、庁舎内ですとか、地域センター等にありますので、そういったものを活用した方策についても、現在。","voiceIndex":210,"id":"exchange-093","title":"町会・自治会支援"},{"speaker":"こしば委員","kind":"質問","question":"先日、五反田にあります自衛隊の募集案内所に伺いまして、所長といろいろと意見交換等をさせていただきました。住民基本台帳の件も品川区の対応に感謝していると言葉をいただいております。品川区も、こういった誤解や批判を受けることないように、品川区でもホームページで、この募集事務についての取扱い、また、その法的な根拠をぜひお示しいただければと思いますが、お考えを教えていただけばと思います。","respondent":"伊藤災害対策担当課長","answer":"ですので、今のやり方がよろしいのではないかというふうに考えております。一方で、ホームページに品川区の名簿の提供の方法について記載することについては、関係課と共有しまして、今後検討していきたいと考えております。","voiceIndex":212,"id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問","question":"よろしくお願いします。私からは、３３２ページの河川費について、そして３６０ページ以降の防災費についてお伺いしてまいります。初めに、防災費ですが、防災課にお聞きします。新庁舎建設に向けて、今、様々取り組まれていますが、新庁舎は、いわゆる品川区の防災拠点としての認識でよろしいのでしょうか。","respondent":"平原防災課長","answer":"防災拠点という認識でおります。","voiceIndex":216,"id":"exchange-095"},{"speaker":"石田（し）委員","kind":"提案","question":"先日、一般質問でも、シェルターについて質問をさせていただき、答弁の中で、品川区には、緊急一時避難施設としてシェルター的な役割をするのが９９か所あるというご答弁をいただきました。今回は少し踏み込んで提案をしますが、核シェルターについて、区として整備の考えがあるのか、今後についてお聞かせください。","respondent":"伊藤災害対策担当課長","answer":"今後もやはり地下シェルターの在り方については、併せて検討させていただきたいと考えておりますので、よろしくお願いいたします。","voiceIndex":218,"id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これは要望で終わります。その１つとして、やはり水質の問題はずっとある。そこで、品川区として、水質改善は、これ、ずっとやられていますが、今後どうしていくのですか。ずっとこのまま同じような金額をずっと使って、年間何千万円も使って、水質改善をやるんだ、調査をやるんだ、また水質改善をやるんだとずっとやっているのですけれども、これ、どうしていこうと思っているのか、お知らせください。","respondent":"北原河川下水道課長","answer":"一方、長期的には、やはり下水道施設の合流施設の改善が必要でして、今、目黒川でも一部稼動しているのですけれども、それはまだ本領発揮していないというか、河川の整備が進まないと、本格的に合流改善施設としては使えないという状況もございまして。","voiceIndex":220,"id":"exchange-097"},{"speaker":"石田（し）委員","kind":"意見","question":"ただ、やはり聞いていると、どうしてもそこにある壁は、やはり東京都なのかなと、管轄ということで言えば、やはり東京都が大きな壁になって、なかなか品川区が単独で何ができるかということは難しいのかなと思います。目黒川や立会川について、品川区選出の都議会議員として、これまでどのような取組を都議会でされてきたのか、また、その経験をどうやって品川区に持ってくるのかお知らせください。","respondent":"北原河川下水道課長","answer":"東京都に対しては、区としてもきちんと要望していくことが大事だと思いますし、区長とも、我々としても、現状を報告しながら、きちんと区として何ができるのかということは取り組んでいきたいと考えています。","voiceIndex":222,"id":"exchange-098"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"なぜ聞いたかというと、今まで、なかなか区で一生懸命頑張ってきたけれども、どうしてもできない。それはやはり東京都の壁がある。改めて何か考えがあれば、教えてください。","respondent":"北原河川下水道課長","answer":"現状について、まず区民の皆さんにもきちんともっと発信していかなければいけないと思いますし、私も東京都から来ている身でもありますので、知っている情報もありますので、きちんと実現できるように真摯に取り組んでいきたいと考えております。","voiceIndex":224,"id":"exchange-099"},{"speaker":"木村委員","kind":"質問・要望","question":"今日もすみません、座ったままで質問いたします。ページ数が３２５ページ、上から４行目、交通安全啓発事業の中から、交通安全運動についてお聞きいたします。車、バイク、自転車、歩行者と、それぞれの立場で運転ルールを守り、事故に遭わないように、起こさないことが求められています。品川区から区民に対し、これはといったお言葉を、何かあればお聞かせください。","respondent":"工藤交通安全担当課長","answer":"区民に向けた言葉ということで、交通事故防止の観点から言いますと、やはり交通事故ゼロを目指すという力強い言葉を区民に向けて訴えかけていきたいと考えています。","voiceIndex":227,"id":"exchange-100"},{"speaker":"木村委員","kind":"質問・要望","question":"これは全ての区民に対して発する言葉であろうと思いますけれども、ぜひまた頑張っていただきたいと思います。これで本区の事故が大きく減ることを期待いたします。交通事故はないほうがいいに決まっていますが、テレビやラジオからは、連日発生している事故のニュースが流れてきます。交通安全運動は、交通事故を防止する運動だと認識していますが、その効果のほどはいかがでしょうか。お聞かせください。","respondent":"工藤交通安全担当課長","answer":"こちらでは、去年、今年と、交通事故件数自体は若干増加傾向にあるのですけれども、東京都全体の傾向でもあるのですが、一方で、自転車が関与する事故につきましては、品川区は前年比マイナス０.３ポイントということで、若干の減少傾向が見られるということで。","voiceIndex":229,"id":"exchange-101"},{"speaker":"木村委員","kind":"意見","question":"若干そういう意味では件数が減っているということでありますけれども、それはどういうことが作用しているのか。何かお気づきの点があればお聞かせください。","respondent":"工藤交通安全担当課長","answer":"品川区では、自転車が関与する交通事故が多いということで、令和４年度から自転車安全利用指導員という制度を実施しています。","voiceIndex":231,"id":"exchange-102"},{"speaker":"木村委員","kind":"質問","question":"ことわざで、喉元過ぎれば熱さを忘れるという言葉がありますけれども、ほとんどの方々に当てはまることでしょうけれども、私自身も気をつけていきたいと思っています。全ての人々で完璧にルールや規則を守っている人々は、どれぐらい存在しているのでしょうか、これも分かればお聞かせください。","respondent":"工藤交通安全担当課長","answer":"ただ、細かな交通ルールになりますと、なかなか理解が難しいところもありますので、そこら辺は何とも答えられませんが、引き続き、交通ルールの周知についてはやってまいりたいと考えています。","voiceIndex":233,"id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"今こそ本当に機運を高める絶好の機会でもあると思っていますし、区民の皆さんの協力をお願いいたします。次に、交通安全教室でありますけれども、お伺いいたします。交通安全運動期間以外にも、交通安全の意識づけは必要だと私は思っています。交通安全の機運を高めるには、区民の方々の協力なくして成り立たないと思いますが、どのような連携の形があるのかお聞きしたいと考えています。","respondent":"工藤交通安全担当課長","answer":"交通安全運動時の地域との連携ということでお答えさせていただきたいと思います。安全運動期間中、各町会・自治会のほうからテントを出していただきまして、それぞれ安全運動だということをアピールしていただいているところです。","voiceIndex":235,"id":"exchange-104"},{"speaker":"塚本委員","kind":"質問・要望","question":"私からは、３５３ページ、私道整備事業、それから、３６１ページ、防災区民組織育成費、そして３５７ページの住宅改善工事助成について伺っていきたいと思います。この事業の効率性を妨げているというふうに指摘をされている要因があるだろうと思うのですけれども、これについて、何が効率性を妨げているのか、お聞かせいただきたいと思います。","respondent":"長尾建築課長","answer":"たくさんの方で共有されて持っているという状況がありますので、やはりそこの私道整備、申請していただくまでの合意形成であるとか、遠方に住んでいる方もいらっしゃいますので、その方とのやり取り、そういったところが、効率性といいますか。","voiceIndex":240,"id":"exchange-105"},{"speaker":"塚本委員","kind":"質問・要望","question":"確かにそういった合意形成とかが大変で、また、現状、私道整備の助成の条件は、道幅２.５ｍ以上が全額助成、それ未満で１.２ｍ以上が９０％助成ですか、そういった形になっておりますけれども、また、幅に合わないとか、１回整備して老朽化したものも一応対象にはなっているのですけれども、その場合、どこまで老朽化すれば対象となって、どこまでだとまだ大丈夫だねとなるのかとか、条件的に、適用される。","respondent":"長尾建築課長","answer":"１回整備して、また老朽化が見られてきて、再度ご利用いただくというところも、現地を確認しまして、やはり劣化が進んでいるようでしたら、改めて制度を使ってきれいにするというところも実際に対応しております。","voiceIndex":242,"id":"exchange-106"},{"speaker":"塚本委員","kind":"質問","question":"幅が必ずしも今、助成対象となるような幅ではなくても、私道として、駅のそばとか、公共施設のそばとか、非常に人通りがたくさんあって、そういったところで幅がないから整備できなくて荒れている道路、こういうものも、まま品川区には散見されると思います。その点については、いかがお考えでしょうか。","respondent":"長尾建築課長","answer":"道幅に関してですけれども、駅の周辺であるとか、一定、人通りの多いような道ですと、おおむね、助成要件にしている１.２ｍ以上、自己負担があるパターンですけれども、１.２ｍ以上。","voiceIndex":244,"id":"exchange-107"},{"speaker":"塚本委員","kind":"質問・要望","question":"この私道整備助成、まだまだやはり区内の安全性の確保とか、生活環境の向上という意味では、需要のある事業と捉えておりますので、今後とも事業がしっかり区民のニーズに応えていけるように、様々、拡充についての適用条件といいますか、そういうことについての検討をお願いしたいと思います。これについて、なぜこの違いがあるのかということについてお聞かせいただきたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"ふだんの訓練からも、地域の総合防災訓練であったり、また、上位団体の消防団、こちらも操法大会も二重巻きでやられているですので、やはりふだんからやられている活動の延長に災害時の対応があることが望ましいのかなというふうに考えてあります。","voiceIndex":246,"id":"exchange-108"},{"speaker":"塚本委員","kind":"質問","question":"今ご答弁いただいた中で、そこの疑問を持たれている消火隊の方々、キャスターつきのバッグに折り島田で入れて運ぶということを独自でやられています。こういったことについての評価というか、区としての考え方、最後にこの質問の答弁をお願いしたいと思います。","respondent":"羽鳥防災体制整備担当課長","answer":"区といたしましては、そういったときには、防災資機材整備助成金をご用意しておりますので、そういったものをご活用いただければというふうに考えてあります。","voiceIndex":248,"id":"exchange-109"},{"speaker":"塚本委員","kind":"意見","question":"一例を言えば、屋根の軽量化がそういったものに入ってくるということで今なっていますけれども、確かに今回の能登半島沖地震などを見ても、瓦が重くて家屋が倒壊するというようなことを本当に目の当たりにいたしましたので、こういった事業は大変に有効だなと考えていますが、その一方で、住宅改善工事助成、通称がエコ＆バリアフリー住宅改修というような言い方もされているので。","respondent":"竹田住宅課長","answer":"これまでも区のホームページ、年３回の広報紙への掲載、町の掲示板に掲示する統合ポスターへの年２回の掲載、防災訓練、住宅まつりでのチラシの配布や相談コーナーの設置、それから、毎月第３水曜日に庁舎で開催しております住宅相談会などで周知を行ってきたところです。","voiceIndex":250,"id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"私は、３点、３４５ページ、戸越公園駅周辺地区再開発事業関連のまちづくりについて、３４９ページ、勝島人道橋について、３６７ページ、帰宅困難者対策についてお伺いします。さらに、東京都の補助２９号線の整備ということであります。地元では、まちづくり協議会もしっかりとした形でできておりますので、ぜひそういった視点での取組をお願いしたいと思いますが、そのことについてお伺いします。","respondent":"大石まちづくり立体化担当課長、森道路課長、羽鳥防災体制整備担当課長","answer":"様々な意見をまちづくり協議会等からいただいておりますので、その辺を踏まえまして、しっかりと東京都ならびに関係各団体と連携いたしまして、引き続き。これから進めていく中で、地域の方々に、改めて人道橋の意義であったりとか、目的だったりということをしっかりとご説明をさせていただきながら。都と連携して、区もしっかり対応を進めてまいりたいというふうに考えております。","voiceIndex":253,"id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"それぞれありがとうございました。それぞれが住民本位の視点で取組事業を進めていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":257,"id":"exchange-112"},{"speaker":"西村委員","kind":"質問","question":"３３１ページ、点字ブロックを活用した音声による移動支援検討、３５１ページから３５３ページ、グリーンインフラ全般、時間が許せば、３４１ページ、密集住宅市街地整備促進事業について伺いたいと思います。植物が持つ保水機能などを利用して、気温低減効果等を活用したみどりのインフラとして緑地整備を実施している取組には、どのようなものがあるのか伺います。","respondent":"高梨公園課長","answer":"今回、プレスで発表させていただきましたグリーンインフラの推進についてですが、来年度予算で、今ご紹介がありましたレインガーデンといたしまして、公園内、また、道路区域も現在検討していますけれども。","voiceIndex":259,"id":"exchange-113"},{"speaker":"西村委員","kind":"質問・要望","question":"近年多発しているゲリラ豪雨ですとか、ヒートアイランド現象を緩和すること。防災や都市環境の改善、美しい景観ですとか安らぎといった多面的な効果が期待されると考えています。ケース・バイ・ケースだとは思うのですが、その結果、整備や維持管理コストの縮減効果が見込まれるのであれば、ぜひとも可視化していただきたいと思いますし、そのような事例があったのであれば、お聞かせいただきたいと思います。","respondent":"高梨公園課長","answer":"区におきましては、これからグリーンインフラとして推進していくところですので、定量的な指標等は現在持ち合わせておりませんが、今まで取り組んできた緑化に加えて、防災といった側面も加えて、また、今回、地域の皆様との暮らしを豊かにするであるとか。","voiceIndex":261,"id":"exchange-114"},{"speaker":"西村委員","kind":"質問","question":"そうでした。家庭菜園講座も始まるということで、私も個人的に大変楽しみにしております。品川区管轄で１５か所、ＵＲと連携しているところで３０か所と伺っております。マイガーデンなど、雨水を浸透吸収し、防災機能を果たすグリーンインフラとしての活用、様々な活用はできないか、ご検討いただけないかと考えていますが、お伺いいたします。","respondent":"小川木密整備推進課長","answer":"本来の目的は、やはり広場、公園等、空間をつくるということが目的でありまして、事業用地をまとめながら、より大きな広場等を整備していきたいという思いがまずはありますので、そういった別の用途につきましては、またこれからいろいろと研究して。","voiceIndex":263,"id":"exchange-115"},{"speaker":"西村委員","kind":"質問・要望","question":"区内在住の環境を専門にしている方から、このグリーンインフラについて伺わせていただきました。２０２１年東京オリンピック・パラリンピックの際に、点字ブロックの音声アナウンスなど、これを機に社会が変わったと言える社会にしたいと要望させていただきました。物すごく可能性が広がる取組だと考えています。","respondent":"森道路課長","answer":"そうすると、ある程度、事業として進めていくためには、なるべく早くやっていかないといけないというところもありますし、地域の方々、一人一人が本当に困っていらっしゃるというふうなところがありますので、それを１日でも、半日でも早く対応していけるように。","voiceIndex":265,"id":"exchange-116"},{"speaker":"西村委員","kind":"意見","question":"私も二葉から毎日三間通りを通って自転車で来ますけれども、本当にこの道路とか、点字ブロックを含めて、陳情がとても多い要件でして、それだけの本数のお声が届いているということを改めて驚いています。ただ、スピード感を持って対応しないと対応し切れないというふうなところも改めて実感したところでありますので、素早いご対応に感謝申し上げますが、引き続き、お願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":267,"id":"exchange-117"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、３６０ページ、防災費について伺いたいと思います。そう思っている中で、先日、消防署の災害対策担当課長にお願いをして、災害の発生後、３日間を乗り越えるには、地域として何をやったらいいですかということを、講師としてお願いしますということで、その課長が持ってきた題は、自助と共助です。それはなぜないのか。それまで何としても地域で守ってほしいということがお願いでありました。","respondent":"平原防災課長","answer":"その際、発災直後は自助のウエートが大きくなりますけれども、それから少し時間がたってからは、共助といったところが、その動きができるかどうかで生存あるいは生活再建につながるということで、非常に重要な役割があると考えていますが、一方で。","voiceIndex":269,"id":"exchange-118"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひここは、もちろんＪＥＲＡだけれども、東京電力なのか、中部電力なのかと言ったら、基本的には東京電力だと思いますけれども、大手のデベロッパーと話をしているそうでありますので、ただ、必ず地域の自治体と話をしますという話をしているわけですから、それは決まってから話を持ってこられても困るわけで、ぜひ早めに言っていただいて、必ずあそこは、総合レジャーランドでもいいですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":271,"id":"exchange-119"},{"speaker":"松永委員","kind":"質問","question":"よろしくお願いします。私からは、３２５ページの地域公共交通機能の充実整備について、同じく３２５ページの鉄道駅可動式ホーム柵整備助成について、３２５ページの地域公共交通会議経費、そして３３９ページの羽田空港アクセス線新駅可能性地域まちづくり検討経費、続きまして、３４７ページのドッグラン設置検証について伺います。初めに、３２５ページの地域公共交通機能の充実整備について伺います。","respondent":"鈴木都市計画課長","answer":"来年度、実証実験に向けて検討を進める、実証実験を行っていくという内容ですが、グリーンスローモビリティ、ご紹介のとおり、２人乗りから１０人乗り、１２人乗り、様々なタイプがありますけれども、グリーンスローモビリティと名前が示すとおり。","voiceIndex":274,"id":"exchange-120"},{"speaker":"松永委員","kind":"質問・要望","question":"どういった感じか、大体イメージはできましたが、これは今年の秋の１か月間ということなのですけれども、その中での実証実験は、例えば、ビッグデータを活用して、こういったところからこういったところまでというふうな移動手段とかを検討されると思うのですけれども、その後、もし品川区として今後進めていくのであれば、料金設定も、どういった形で決めていかれるのかということと、その後。","respondent":"鈴木都市計画課長","answer":"導入の前に、どこでやったらいいかということを、アンケートを実際にとるかどうかについては、これは先ほどの携帯電話の２か月ほどの、区内全域のビッグデータに基づいて検討していきますので、ある意味、移動実態が、裏を返せば。","voiceIndex":276,"id":"exchange-121"},{"speaker":"松永委員","kind":"意見","question":"ぜひアンケートのほうもよろしくお願いします。実は、南大井から大井町へのバスがまた減便されました。多くの方々が困っており、例えば、モビリティを使って、例えば他区、品川から臨海斎場までとか、そういった大田区へ行きたいのだけれども、そこの途中で下ろされるとか、そういったこともあるかと思うのですけれども、そうした場合は可能なのかどうかをお知らせください。","respondent":"鈴木都市計画課長","answer":"ＡＩオンデマンド、それからグリーンスローモビリティ、より小さな移動手段と、路線バスは、どうしても定められたルートを一定の大量の輸送を行うというのが路線バスの形で、ＡＩオンデマンドというのは、本当にエリアを決めて、ある意味、ミーティングポイントを複数決めて。","voiceIndex":278,"id":"exchange-122"},{"speaker":"松永委員","kind":"質問","question":"分かりました。次に、３２５ページの鉄道駅可動式ホーム柵整備助成について伺います。東急池上線の五反田駅についてですが、旗の台駅や戸越銀座駅のような自動ホーム柵ではなくて、ただの柵なのか、そして、京急青物横丁駅のホーム柵については、特急や急行や普通の停車駅となっておるのですが、移動柵について、例えば関西のようにロープ式になるのか、少しその実態をお聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"京浜急行電鉄については、１つの車両にドアが２つのタイプ、それから、３つのタイプがございまして、それに対応できるように、センサーが感知をして、場合によって、３つのドアが入ってきた場合は、状況によっては開く、２つのタイプが入ってきた場合は。","voiceIndex":280,"id":"exchange-123","title":"町会・自治会支援"},{"speaker":"松永委員","kind":"質問・要望","question":"少し気になったので伺いました。これは要望です。次に、３３９ページの羽田空港アクセス線の新駅についてですが、現在どこまでお話し合いがされているのでしょうか。２０２３年６月より、東山手ルートが本格的な開業に向けた工事が始まっており、羽田空港等、東京都心部の距離がさらに近くなっております。","respondent":"鈴木都市計画課長","answer":"協議の状況ですが、令和４年度に基本的なルートの沿線の土地利用の状況ですとか、その適地について、課題ですとか、簡単な概略の金額ですとか、そういった調整委託をかけておりまして、折に触れてＪＲとは意見交換なども行っておりますが。","voiceIndex":282,"id":"exchange-124"},{"speaker":"松永委員","kind":"質問","question":"２０３１年に開業する予定となっており、その前に手を挙げないと駅がつくれないのではないかという心配で質問させていただきました。ぜひそのことについても伺いたいと思います。今後、手を挙げられるのであれば、八潮みらい懇談会や大井第一地区などの近隣住民との話合いも必要だと思いますので、そのところはぜひよろしくお願いいたします。","respondent":"鈴木都市計画課長","answer":"その際は、区民の方のご意見をどういう形でお聞きするのか、当然ながら、適時適切に議会等にもしっかりご説明、ご報告しながら進めていきたいというふうに考えてあります。","voiceIndex":284,"id":"exchange-125"},{"speaker":"松永委員","kind":"質問・要望","question":"我が会派からの要望もありました３４７ページのドッグランの設置検証について伺いたいと思います。そこで、この事業についてでありますが、主にどういった内容なのか伺いたいと思います。例えば、広さ、柵の高さ、また大型犬も可能なのか、利用時間、あとは会員制としてやられるのかなど、そのところについて伺いたいと思います。","respondent":"高梨公園課長","answer":"来年度につきましても、引き続き、年間で１６回ほどマナー講習会を実施する予定ですが、その講習会の際に仮設ドッグランを設置し、利用者であったり、周辺にお住まいの方々の意見を聞きたいということで行う事業です。","voiceIndex":286,"id":"exchange-126"},{"speaker":"松永委員","kind":"質問","question":"ぜひ今後もよろしくお願いします。最後に、区民公園のバーベキュー場ですけれども、この間、防犯パトロールで回ったときに、喫煙所が封鎖されておりまして、その中に木の材木とかが置かれて使用できなくなっておりましたが、今後、公園内にある喫煙スペースについて、どのような感じで進められていくのでしょうか。","respondent":"高梨公園課長","answer":"公園内の喫煙所については、コロナ禍以降、閉鎖をしています。周辺であったり、利用者の方々の意見も聞きながら、開放については考えるですので、キャンプ場についても、これから利用者や周辺の方々にご意見を伺って決めてまいりたいというふうに考えてあります。","voiceIndex":288,"id":"exchange-127"},{"speaker":"西本委員","kind":"質問・要望","question":"質問を先に申し上げます。区民の皆様方の中には、自分が睡眠をとる、そこだけでも強固にしていきたい、耐震を図りたいというご要望が結構あって、なので、今そういうものもできておりますので、広く条件を緩和して、いろいろ考えられてはどうかなというふうに思いますので、ご意見をお聞きします。大丈夫ですか、１５億円で。毎年一緒ですよね、１５億円ですから。お考えをお聞きします。港区ですよ。","respondent":"高梨公園課長、長尾建築課長、羽鳥防災体制整備担当課長、平原防災課長、大石まちづくり立体化担当課長","answer":"先ほども答弁で申し上げましたが、依然として登録者数が伸びていないような状況ですので、公園内の掲示等、広報をしっかりと行って、今。区としましては、来年度、耐震化の事業につきましても、耐震診断を無償化ですとか、除却助成の範囲を区内全域に広げてですとか。その動きの中でチラシの書き方を分かりやすいようにして、連携している業者に分かりやすい説明を求めてまいります。ただ、もちろん内容については、毎年見直しを図っていくべきものだと考えていますので。","voiceIndex":291,"id":"exchange-128"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、すぐお金ができるわけではないので、そのお金は計画的に、そして、いろいろな事業が出てくると思いますので、それに対応できるように積み上げをしていただきたいと要望しておきたいと思います。それぞればらばらにいるのではなくて、しっかり連携を組みながら、そして品川区としてどうするのだということをしっかり考えていただきながら、開発に関わっていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-129"},{"speaker":"若林委員","kind":"確認","question":"３６０ページ、防災費のほうでは、第１回定例会の本会議で、耳で聴くハザードマップ「Uni-Voice Blind」という新しいアプリで、視覚に障害があってもハザードマップの説明が耳で聞けるという、そういうようなアプリのご紹介をしながら、区のほうでは導入の検討を確認させていただきました。区民が利用できるようにしなくてはいけないと思いますけれども、区の取組をお聞きします。","respondent":"北原河川下水道課長、平原防災課長","answer":"目黒川のしゅんせつ等支障物撤去ですけれども、平成２９年度より、順次、区間を決めて、フーチング部分のしゅんせつと、支障物の撤去をセットで進めてきておりまして、今年度につきましては。ただ一方、導入時期につきましては、今、内部で検討していますけれども、私ども初めてということもありますので、どのように広めていくかも勘案しながら導入時期を決めてまいりたいと思いますが。","voiceIndex":299,"id":"exchange-130"},{"speaker":"若林委員","kind":"質問・要望","question":"お尋ねですけれども、令和５年度の予算を組むに当たって、予算を組んでから、都が同じ区間を工事をするということが分かったということなのでしょうか。それから、同じ区間の中で、区と都の工事は同時にできないのでしょうか。それから、不調が分かってからでも、工事の形態が違うので、区は実施できると理解するのですけれども、この３点についてお答えをいただきたいと思います。","respondent":"北原河川下水道課長","answer":"都が不調になったのが区の工事が契約した後でございまして、その後に対応することが難しかったという状況があります。","voiceIndex":302,"id":"exchange-131"},{"speaker":"若林委員","kind":"質問・要望","question":"非常に残念な今のご答弁だと思います。これは明確にそういうことだと思います、予算を両方組んでいるわけですから。都の不調は、それは都のほうの話ですから関係ありませんけれども、こういう予算の立て方は、品川区の目黒川の水質浄化の姿勢として、私は、石田しんご委員も憤っておられましたけれども、同様に、やはりこれは大変に残念だと、今年度、令和７年度という話ではないですか。","respondent":"北原河川下水道課長","answer":"目黒川の水質改善については、委員もおっしゃいますように、東京都、目黒区等と連携して検討会を行うなど密に実施してきているところであります。","voiceIndex":304,"id":"exchange-132"},{"speaker":"せりざわ委員","kind":"提案","question":"さらにというところで提案になりますが、駐車場の車椅子マークについてご提案したいと思います。そういったことを周知していくだけではなくて、例えば、赤ちゃんの防災に対して、品川区では出産応援のカタログギフトをやっていると思いますが、そういったところに、赤ちゃんの、もしくは子育て世帯の防災グッズの支援も１つ載せていただいてもいいのかなと思うので、ご見解をお聞かせいただきたいと思います。","respondent":"高梨公園課長、平原防災課長","answer":"その中にも身体障害者用マークをつけて運用しているところがありますので、今、委員からご提案があった内容につきまして、駐車場を管理している会社とも話し合って。そういったところで、令和６年度以降、様々な場でそれを強化していこうというふうに考えている中で、今、ご提案がございました防災グッズをどのように提供していくか等も含めまして、今後。","voiceIndex":307,"id":"exchange-133"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"視覚障害者についてですが、先ほど、点字ブロックのお話がいろいろ出てきました。これはぜひ避難所の中でも活用していただきたいと思います。点字ブロックの音声つきのガイドは、床に置いてあってというところになるのですが、これのすごいところは、印刷をしておけば、そもそもＡ４とかの紙でもできるということと、壁に張ることができるのです。ご見解をお聞かせください。","respondent":"平原防災課長","answer":"すみません、先ほどの赤ちゃん防災のところにつきましては、しながわ防災学校での取組などもありますので、防災グッズの在り方について、所管と連携しつつ検討してまいりたいと考えています。","voiceIndex":310,"id":"exchange-134"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"点字の件は、ぜひ印刷で事前に用意しておくということで、それと一緒に、例えば、こちらのほうにトイレがありますよとかという、目で見えるほかの文字の情報というものも残しておくことで、共に使えるような情報提供ができると思いますので、ご検討ください。道路のほうからお伺いしたいのですが、愛称道路のルール、どういうふうにつくっていくのかをお聞かせいただきたいと思います。","respondent":"森道路課長","answer":"道路の愛称につきましては、一部、ホームページ等でも公開をしていますけれども、地域の方が、日頃から、今まで、昔から呼んでいるものを、道路に親しみを持っていただくということで、区としても愛称として設定しています。","voiceIndex":312,"id":"exchange-135"},{"speaker":"せりざわ委員","kind":"提案","question":"そもそも品川区という地域の、諸説ありますけれども、その川の地名の由来になったのが目黒川と言われていて、目黒川が流れているのに、品川が今、目黒川は目黒区もあって、品川区もあって、目黒区に流れている目黒川は目黒川でいいと思うのですけれども、品川区の川については、品川、品川運河と言いますけれども、品川と愛称を変えていくというのは、法的にではなくて。","respondent":"北原河川下水道課長","answer":"河川の愛称は全国的には多数あると聞いていますので、まずはそちらを研究してまいりたいと思います。","voiceIndex":314,"id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３４９ページの公園などの整備、それから、順番は逆ですみません。３４１から３４９ページの様々な整備事業についてお尋ねします。こちらも大きな２つのポイントを伴った公園ですので、これは大変期待していますということで、今後、よろしくお願いしますという要望だけです。その原因は地域の方々にご説明いただいたと伺っていますが、今後のというか、現在の浸水防止の区としての対応をお尋ねします。","respondent":"高梨公園課長","answer":"現在、同じような状況、大雨と大潮が重なって、区民公園の中にある潮通し管という下水道管から水があふれるというような状況だったわけなのですが、同じような状況が起きても、区民公園から外の宅地のほうに水が出ないような対策工事を、現在。","voiceIndex":317,"id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それぞれありがとうあります。手すりについては、ぜひ東京都の交渉の中で要望をお願いいたします。次に、３４１ページからの様々な整備事業ですが、これを歳入のほうの１３３ページ辺りの補助金の中の都市計画交付金の充当事業として見てみますと、東中延一丁目とか、東五反田とか、大崎西口Ｆ南などの８事業には補助金が充当されています。この違いについてご説明ください。","respondent":"中道都市開発課長","answer":"補助金につきましては、組合が設立して事業認可が下りたものに対して補助金が入るということになっております。","voiceIndex":319,"id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということですと、８事業は、都市計画決定したり事業認可が下りていて、それで都市計画交付金が充当されているという理解でよろしいでしょうか。ということは、充当されていない様々なこちらに幾つか出ている事業も、いずれその対象となっていくというふうに考えてよろしいでしょうか。","respondent":"中道都市開発課長","answer":"市街地再開発事業につきましては、事業が認可した際に都市計画交付金等々、そういったものを活用して進めていくというものになります。","voiceIndex":321,"id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"都市計画交付金との関係を確認させていただきましたので、分かりました。それで、勝島関係の工事は、設計とかいろいろあるので、これは要望なのですけれども、その４０万円が、今幾つかある勝島関係のところのどこに充当されるかということが予算書では分からないので、今後、正確に表示していただければと思います。これは要望です。その財源については、貪欲に確保していっていただきたいと思います。","respondent":"遠藤財政課長","answer":"金額といたしましては、都全体で３,０００億円弱ぐらいになるのですけれども、実際、区に交付金が来ているのが、大体７％程度というところで、ただ、都市計画事業といたしましては、大体、都と区の割合で７対３というところで、７％に対して３０％というところで。","voiceIndex":323,"id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"事業が３対７ですが、実際の交付金は７％に過ぎないというところで、非常に理不尽という言い方が強い言い方なのかはあれですけれども、そういう形だったと思います。今、少しお話がありましたけれども、今のようなお話を品川区においても、分かりやすい形で、区長の見解をホームページにアップしていただきたいのですが、もう一度その点を確認します。","respondent":"遠藤財政課長","answer":"不合理な税制の部分とかは載せている部分はあるのですが、すみません、都市計画金を載せていたかどうか確認できておりません。載っていない場合には、速やかにこちらのほうも丁寧に説明していきたいというふうに考えております。","voiceIndex":325,"id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ということで、ホームページ載せていただけると。ただ、それではなかなか厳しいということ、それだけでは駄目ですので、私、歳入のときに、区長に特別区長会で強い主張をお願いしたいというふうにお話ししたのですが、この都市計画税についても、しっかりと特別区長会の中で特別区協議会が一体となって東京都に主張していただきたいと思います。その辺のご決意を伺いたいと思います。","respondent":"遠藤財政課長","answer":"この間、先ほど申しましたとおり、いわゆる財調協議の中でこの都市計画金についても必ず説明といいますか、抗議をしていますけれども、東京都のところにつきましては、これは財調協議と違うと、都市計画金は別の話だという形でかわされているようなところがあります。","voiceIndex":327,"id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、粘り強く交渉していただけるということですので、ぜひ３対７のその分に近づけるように、区長会一丸となって東京都と交渉していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":329,"id":"exchange-143"},{"speaker":"松本委員","kind":"質問","question":"よろしくお願いします。私からは、３４９ページ、Ｐａｒｋ－ＰＦＩの導入、３５９ページ、住宅運営費について伺います。このＰａｒｋ－ＰＦＩですけれども、予算が今回４００万円計上されています。これはどういった内容なのか、最初に伺いたいと思います。","respondent":"高梨公園課長","answer":"来年度予算で計上しています４００万円につきましては、Ｐａｒｋ－ＰＦＩで、先ほど答弁させていただいたとおり、来年度、事業者を決定したいというふうに考えてありますが、その事業者との協議で、収益施設と一緒に区が整備するべきものも考えられるということで。","voiceIndex":331,"id":"exchange-144"},{"speaker":"松本委員","kind":"質問","question":"この計画の所管は、多分、企画部かと思うのですが、そうは言っても、実際に運用していくのは所管なので、所管の見通しについて伺いたいと思います。一方で、規程の中に優先的検討の対象で公園も含まれています。そうすると、計画策定後は、事業費の総額が１０億円以上の公園整備事業については、原則的にＰＰＰ／ＰＦＩ手法を優先的に検討するというふうなことになるかというところをお伺いいたします。","respondent":"高梨公園課長","answer":"今ご案内のとおり、内閣府から出ていますＰＰＰ／ＰＦＩ手法導入優先的検討規程策定の手引き等でもご案内がありますけれども、１０億円以上の整備の際には検討を要するということで、ちなみに、国土交通省のほうからいただく国費の関係の要件にも。","voiceIndex":333,"id":"exchange-145"},{"speaker":"松本委員","kind":"確認","question":"そういった国費の関係もあるので、とても大事かと思うのですが、ただ一方で、今回、品川区で今、策定を目指されている規程の内容を確認すると、対象とするＰＰＰ／ＰＦＩ手法、検討するときに、こういうＰＰＰ／ＰＦＩ手法を検討しますというふうなものが掲げられておりまして、例えば、コンセッションとか、通常のＰＦＩとか、指定管理者制度などが挙げられているのですけれども、ただ。","respondent":"高梨公園課長","answer":"今回のＰａｒｋ－ＰＦＩにつきましては、ここの検討するべきＰＦＩ手法でいうところのＰＦＩというのは、ＰＦＩ法上のＰＦＩ事業ということになってありますが、我々が今、実現を目指しているＰａｒｋ－ＰＦＩにつきましては、都市公園法上の制度ということで。","voiceIndex":335,"id":"exchange-146","title":"町会・自治会支援"},{"speaker":"松本委員","kind":"質問・要望","question":"ここは答弁を求めないので、企画部にもお伝えできればと思うのですけれども、これ多分、もともとの内閣府が作成された手引きが、平成２８年につくられているので、そもそもＰａｒｋ－ＰＦＩの制度が始まる前につくられたものではないかと思います。要望で終わります。次に、住宅運営費についてですけれども、昨年の決算特別委員会では、民間の高齢者の住宅確保について伺いました。","respondent":"竹田住宅課長","answer":"お亡くなりになられた後、区のほうで、ご存命中の対応記録や入居書類、あるいは戸籍調査等を行いまして、ご親族の有無の調査を行った結果、今までのところ、相続人が見つからなかったというケースはございません。","voiceIndex":337,"id":"exchange-147"},{"speaker":"松本委員","kind":"質問・要望","question":"自治体によっては、そういうふうな場合には、もうそれ以上、相続財産管理人、財産がない方について、それをおっしゃられても、あまり回収見込みがないので、要綱とか要領の形で所有権を放棄してもらうというふうな、これは同意も得ないといけないと思いますけれども、そうした扱いをやっている自治体もありますが、当区で、今後こういうふうな方向性があるのか、要望も含めてお願いしたいと思います。","respondent":"竹田住宅課長","answer":"極力相続人の方を見つける方向で進めていきますが、万が一見つからなかった場合は、裁判所による相続財産管理制度の法的手段を検討してまいります。","voiceIndex":339,"id":"exchange-148"},{"speaker":"藤原委員","kind":"質問","question":"３２５ページ、交通安全について、まずお伺いします。ありがとうございました。そして、交通安全担当でやっている駅前放置自転車クリーンキャンペーンのキャッチフレーズが「自転車の代わりに置こう思いやり」、これ、すばらしいと思うのですけれども、課長は、この品川区に、どのような思いやりの心を残していってくれるのでしょうか。","respondent":"工藤交通安全担当課長","answer":"それぞれ対応した１つ１つが交通安全に寄与したものであったと期待をしています。こういったほかでは経験できないようなことを経験させていただきましたので、また次のところでも生かして頑張ってまいりたいと、精進してまいりたいと考えています。","voiceIndex":342,"id":"exchange-149"},{"speaker":"藤原委員","kind":"質問・要望","question":"今度は東京都全体を見ていただくわけですから、ぜひこの品川区で得たことを土台にしてやっていっていただきたいと思います。西大井駅前のシェアサイクル、これ、何回も要望していますが、どうなっているか教えてください。西大井駅、今年の８月、ニコン本社が稼働すると思うのですけれども、西口の改札口、何回も要望していますが、これはどうなっているでしょうか。ホーム柵はどうなっているでしょうか。","respondent":"平原防災課長、櫻木土木管理課長、北原河川下水道課長、鈴木都市計画課長、工藤交通安全担当課長、小川木密整備推進課長、中道都市開発課長、大石まちづくり立体化担当課長、高梨公園課長、長尾建築課長、竹田住宅課長、森道路課長、佐藤企画課長、崎村人事課長","answer":"今後、この対応指針で示されました対策など、都が具体化する対応策を踏まえまして、区の対策を見直すところは見直しまして。西大井広場公園の改修に合わせて検討してまいりましたが、需要が集中している状況ですので、具体的に検討してまいりたいと考えています。令和８年度の完了というところで進めてきておったところですが、少しシールドにも遅れが出ているところと、次期工事、今後。ただ、今の状況ですと、十分改札は対応しているですが、ニコンの稼働によって、現在、１,０００人の就業人口が。","voiceIndex":344,"id":"exchange-150"},{"speaker":"藤原委員","kind":"質問","question":"人事課長、それを言っては駄目ですよ。今日、反省会で、うちの幹事長に厳しいご指導を受けてしまうから。西大井という地域が。うちの幹事長からも言われるのです、「また同じ質問かよ」と。でも、私は、これがきちんとできるまで質問していきます。どう考えても、あそこは人が多いですよね。増えるわけです。私がこういうふうに何回も西大井のことを思って質問してはいけませんか。その辺、答弁してください。","respondent":"鈴木都市計画課長","answer":"そうした観点からも、西大井を全体的に俯瞰的に、決算特別委員会、予算特別委員会、様々な場で総合的にご意見をいただくというのは、やはりまちづくりを所管している者としては、非常にありがたい、重要なことだと思いますので、引き続きしっかり検討に取り組んでいきたいです。","voiceIndex":359,"id":"exchange-151"},{"speaker":"鈴木委員","kind":"質問","question":"首都直下地震が起こったとき、品川区はどうなるのかというところで、都の被害想定が出されていますけれども、その中で身の回りで起こり得る災害シナリオと被害の要素というところがありまして、上下水道については、３日後には断水の復旧は限定的、１か月後に断水がおおむね解消ということになっていまして、下水道も、３日から１週間は、一部地域で下水道利用が困難、１か月後に。","respondent":"平原防災課長","answer":"その先の流下支障世帯というような形になってまいりますので、６.４％掛けるという形になりますので、例えば、人口でいくと、２万６,０００人が影響を受ける、そういうようなことになってまいりますので、本当に６.４％ということでお考えいただければというふうに思います。","voiceIndex":362,"id":"exchange-152"},{"speaker":"鈴木委員","kind":"質問・要望","question":"火災危険度は、特に品川区は木密地域が多くて本当に大変な状況があると思うのですけれども、そういうときに、今回の輪島市の朝市の商店街でも、２００棟以上が火災で焼けてしまいましたけれども、そのところで、消防団の方とか消防の方が来ても、結局、水道管が壊れて断水したために消火栓が使えなかったということが、被害をこれだけ拡大したということにもなっていると思うのですけれども。","respondent":"北原河川下水道課長","answer":"上水道の耐震化につきましては、ダクタイル鋳鉄管への更新というものと、継手部の耐震化という形になりますので、耐震継手化がなされていけば耐震性能を持つものと考えられますが、非常に数も多いということで、計画的に順次進めていると認識しております。","voiceIndex":364,"id":"exchange-153"},{"speaker":"鈴木委員","kind":"質問・要望","question":"災害列島と言われる中で、これだけ巨大地震が起こって、本当に被害の地域の大変な事態をずっと私たち目にしているわけですから、ここのところは本当に税金を入れられないということではないので、税金を入れてでも、しっかりとインフラ整備をするというところで、私は、区のほうからも求めていただきたい。","respondent":"北原河川下水道課長、羽鳥防災体制整備担当課長","answer":"同じやり方をしていけば、技術的には耐震化が図れるものと認識しておりますが、やはり先ほどの水道の話にもなりますけれども、非常に量が多いということで、重点化して進めているものというふうに認識しています。トイレの備蓄につきましてですけれど、トイレにつきましては、様々な形のトイレを備蓄するという対応をとっているところです。","voiceIndex":366,"id":"exchange-154"},{"speaker":"鈴木委員","kind":"質問・要望","question":"でトイレのところについてお答えいただきたいのと、リニアのほうに移りたいと思います。その時点で、私は、ぜひ区民に対して説明会を、１回説明したものと全く違う状況になっているわけですから、説明会をぜひ開いていただきたいということで、区のほうからも要望していただきたいと思うのですけれども、その点を伺いたいと思います。お願いします。","respondent":"羽鳥防災体制整備担当課長、大石まちづくり立体化担当課長","answer":"トイレの備蓄につきましては、区民全体ということではなくて、避難所避難者用です。携帯トイレに関しましては、３日間分の量を備蓄しています。説明会を求めることにつきましては、調査掘進終了後にＪＲ東海は説明する機会を設けると聞いておりますので、そちらで説明されると聞いております。教訓を生かすということですが、教訓を生かして作業を進めていると感じております。","voiceIndex":369,"id":"exchange-155"},{"speaker":"大倉委員","kind":"質問・要望","question":"３４７ページ、公園・児童遊園で、西五反田公園について伺えればと思うのですが、今回、先ほどもお話があった目玉焼きのトランポリンみたいなものがあって、子どもたちがより楽しくというところで、この公園については、今回、残していただきましたけれども、大迷路があって、これは私も小学校の頃から遊んでいたシンボリックな公園の遊具というところで、ほかにもいろいろあったのですが。","respondent":"櫻木土木管理課長、高梨公園課長、森道路課長","answer":"年間の剥がしている件数としましては、大体５万６,０００枚程度、今年度に関しては、１月までで５万１,０００枚程度ということで、基本的には。ベンチについてですが、委員からご案内ありましたとおり、新しい改修後の公園におきましては。私からは、かむろ坂の桜についてお答え申し上げます。","voiceIndex":373,"id":"exchange-156"},{"speaker":"大倉委員","kind":"質問","question":"シルバーセンターへの委託ということでやられているのですが、ボランティアで今やっていただいているものを、少し地域貢献のポイントみたいなものがほかのところでありますけれども、そういったボランティアではなくて、少し有償でもいいので、何か一緒にやりませんかというところができないかなということを今少し思っているので、その点について伺いたいと思います。","respondent":"櫻木土木管理課長、高梨公園課長","answer":"確かにボランティア数については、もう少し広げていって、草の根的に広がるようなことがあるといいのかなと考えていますので、何かしら、ボランティアという性質上。熱中症対策による屋根の設置ですが、安全領域の関係上、全てにつけることができません。今、新しい製品等も出てまいりますので、ミストの設置等も含めて複合的に考えてまいりたいと考えているところです。","voiceIndex":377,"id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問","question":"３６０ページ、防災費から、罹災証明書の発行について、３５９ページ、居住支援事業、３５７ページ、マンション管理支援事業の順番で聞いてまいります。品川区は、能登半島地震の被災地へ区職員を派遣されたと伺っておりますが、派遣された職員が罹災証明書の発行に関して、どのような職務に従事をされたのか、教えてください。","respondent":"平原防災課長","answer":"１名は本日出発です。具体的な内容ですけれども、罹災証明発行の段階は、単に書面交付ということにはなるのですけれども、その際に、内容の説明、あるいは、その次の手続の説明等々を伴いますので、そういういわゆる窓口業務といったところが主になります。","voiceIndex":381,"id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問・要望","question":"６年前の平成３１年、コロナ前ですけれども、品川区と東京都行政書士会品川支部が、災害時における区民の行政手続の支援活動に関する協定、いわゆる防災協定を締結しました。この防災協定では、災害時において、区の要請によって行政書士会が３つの業務を協力して行うとなっています。協議を詰めていただきたいと思いますが、いかがでしょうか。","respondent":"平原防災課長","answer":"行政書士会品川支部との間では、平成３１年１月２２日に協定を締結させていただいておりまして、委員ご案内のとおりの協力内容となっておりますけれども、やはりその中で、罹災証明が出ましたとき、それは支援のために出すということになりますので。","voiceIndex":383,"id":"exchange-159"},{"speaker":"あくつ委員","kind":"提案","question":"ぜひよろしくお願いいたします。次に、居住支援事業で、民生費に続きまして、高齢者の住まいについて伺ってまいります。昨年、定例会の一般質問で、日本維新の会の松本委員からも、名古屋市の例を挙げて孤立死や残置物撤去の保険料を自治体が負担することや、現在居住支援を行っている社会福祉協議会への助成などを提案されており、私もそれは非常に有効かなと思いました。","respondent":"竹田住宅課長","answer":"様々なメリットをご紹介していただいたので、居住支援法人も活用しながら、高齢者を入れることの様々なメリットもご紹介しながら、高齢者の居住支援に努めてまいりたいと考えております。","voiceIndex":385,"id":"exchange-160"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これは全国的に少ないのですが。北九州市の認定ＮＰＯ法人抱樸、これは代表の方は牧師なのですけれども、私も直接お話を伺ったことがありますが、不動産会社と、そして家賃債務保証業者と協力をして、住宅要配慮者を対象とした社会共有資源として空き家を活用するビジネスモデルを実践されている。これを５５室のサブリース運用で、年間約７２６万円の収入として、そこから事業費と人件費を捻出している。","respondent":"竹田住宅課長","answer":"ぜひ品川区でも、そういったものを実現させていきたいと思いますので、居住支援法人と連携をとりながら、高齢者の支援を進めていきたいと考えております。","voiceIndex":387,"id":"exchange-161"},{"speaker":"あくつ委員","kind":"質問・要望","question":"前向きなご答弁だったので、うれしかったです。ひとり親とか、あとは経済的困窮者も含むのですが、やはりそういったところも含めて、そういった施策も輝いていただいて、２つが輝くことによって、品川区はより光を放つということで、この前、質問させていただきましたけれども、ぜひそういったメッセージを掲げていただきたいと思いますが、最後にご答弁をお願いいたします。","respondent":"竹田住宅課長","answer":"これは正に委員おっしゃるとおり、高齢者、障害者、ひとり親、それから低所得者を対象とした事業です。こういった事業を通じて、住宅確保要配慮者という方々の支援をして、どなたにも住みやすい品川区をつくってまいりたいと考えております。","voiceIndex":389,"id":"exchange-162"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よろしくお願いします。３３１ページ、無電柱化推進事業、３４１ページ、防災街区整備事業、３４７ページ、公園・児童遊園整備費、立会川児童遊園、旗の台北公園についてお尋ねをしたいと思います。最初に、３３１ページの無電柱化推進事業についてお伺いします。今年度も補助２６号線から文庫の森の区間、地中化施設整備が、今、スケジュールどおり工事をされているかと思います。","respondent":"森道路課長","answer":"なかなか商店街の方々と、しっかりと連携しながら進めて、ご理解、ご協力いただきながら進めていく必要があるかと思っておりまして、現在のところは、今行っております２路線をしっかりと進めていきたいというふうに考えています。","voiceIndex":392,"id":"exchange-163"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"東口通り商店街の商店街長、町会長からも、今、課長のご答弁のとおり、話を伺っております。ほかの商店街でも、歩道がないところで無電柱化もされている、北品川とかもありますね。トランスの配置もいろいろ苦慮されていると思うのですけれども、やはりこれ、私が申し上げた進捗に当たって課題になっていることは、今、私の発言のとおりでいいのかどうか、ほかに何かあれば、教えていただきたいと思います。","respondent":"森道路課長","answer":"北品川の戸越銀座で行っております柱体にトランスを載せるというような形の方式になるのかなというふうには考えておりますけれども、それにしても、商店街の方々に大分ご迷惑をかけるところもありますので、慎重に協力を得ながら考えていきたいと思ってあります。","voiceIndex":394,"id":"exchange-164","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今後の事業化に向けて、スケジュールは、これからどのようにお考えになって、完成の見込みは、まだ当然分からないと思うのですけれども、もし私が聞き取りをされたとき、見込みとして、どういうふうに区としてお考えになっているのか、教えていただきたいと思います。","respondent":"森道路課長","answer":"今行っております２路線に加えまして、拡幅が行われています林試の森公園につきましても、来年度から検討を進めるところです。","voiceIndex":396,"id":"exchange-165"},{"speaker":"高橋（伸）委員","kind":"質問","question":"権利者も７０名ぐらいいると思うのですが、やはり地べたを持っておられる土地の所有者が遠方に住んでいたりとか、当然、分かっているかと思うのですけれども、本当にこれ、密集法ということで、今度は防災街区整備推進機構に指定をされたということで、来年度の予算のスケジュールは、今、課長からもお話がありましたけれども、いつというのは、多分これ、判断できないと思うのですけれども。","respondent":"小川木密整備推進課長","answer":"来年度は、意向調査等を行いながら事業計画をしっかりと立案して、来年度末ぐらいには、事業の方針等を示していきたいというふうに考えてあります。","voiceIndex":400,"id":"exchange-166"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これも来年度予算に計上されております立会川の児童遊園、これ、その３というところがあるのですけれども、その改修工事について、昨年の私の予算特別委員会の質問において、地元から親しまれているカエル公園と呼ばれているのですけれども、このカエルの彫像の取り扱いについて、どうなったか確認をしたいのですけれども、私の知る限りは、現在ある彫像は、恐らく３体目だと認識しているのですけれども。","respondent":"高梨公園課長","answer":"非常に地域の皆様から愛され、なでられて、ぴかぴかに光ってあります。周辺の植栽帯の特徴的なラインとか、そこら辺も、今ある形をできるだけ残した形で、ただ、施設自体は新しくということで、現在、設計を進めているところです。","voiceIndex":402,"id":"exchange-167"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"もう１つ、これも昨年質問したのですけれども、樹木の根上がり、立会川なので、暗渠ですよね。暗渠だと高さがないから、どうしても根上がりがあると思うのだけれども、これが設計での調査の結果、どのようなものであったかということを教えていただきたいと思います。それで、その結果を踏まえて、どのような改修が行われるのかお伺いしたいと思います。","respondent":"高梨公園課長","answer":"動かすとなると、なかなか耐えられないということになりますので、できるだけ大きな木については、今の状態を見て、動かさないで済むものは移植せずに、現状、既存木として、できるだけ生かすというところで設計を進めているところです。","voiceIndex":404,"id":"exchange-168"},{"speaker":"高橋（伸）委員","kind":"質問","question":"やはり予算審議、これも昨年なのですけれども、課長のご答弁で、これは地域の方々、それと利用者の方々から、しっかりとお声を聞いて設計に反映していきたいと思っているとの答弁があったと認識しているのですけれども、実際に、地域の方、利用者から、どのような意見が寄せられたのかお聞きしたいと思います。","respondent":"高梨公園課長","answer":"立会川児童遊園は、その１、その２も、その３も、その４もそうなのですが、地域の皆様の玄関先になっているようなお宅もあったというところで、お声としては、ふだんの生活の支障についてのご不安というか、そこをしっかり確保してほしいというようなご意見がございました。","voiceIndex":406,"id":"exchange-169"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ町会、本当に地域に愛される公園づくりというところで、高齢者からお子さんまで、それぞれ皆さんの集いの場になっておりますので、ぜひそういった意見を反映して、今後につなげていきたいと思いますので、どうぞよろしくお願いいたします。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":408,"id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6695#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":135962,"voices":409}}]);
